/**
 * Resolve a ledger line's source to its owning page and dispatch the deep-link
 * CustomEvent (caught by AdminDashboard). Turns a `source_id` into the foreign
 * keys the pure router needs, per source_type, then fires nys:open-*.
 *
 * @param {{source_type: string, source_id: string}} src - the line's JE source
 * @param {{info?: Function, error?: Function}} [toast] - for the no-target/error path
 * @gotcha splits (destination AND expense) resolve to their PAYOUT, never to an
 *   expense; only direct oop_* entries route to Expenses. @see ledgerSourceLink.
 */
async function openLedgerSource({ source_type, source_id }, toast) {
  if (!isNavigableLedgerSource(source_type) || !source_id) return;
  let keys = {};
  try {
    if (source_type === 'invoice') {
      const { data, error } = await supabase.from('invoices')
        .select('campaign_id, reward_entry_id').eq('id', source_id).single();
      if (error) throw error;
      keys = { campaignId: data?.campaign_id, rewardEntryId: data?.reward_entry_id };
    } else if (source_type === 'payout') {
      // payroll_period rides along because a MONTHLY paycheck has no campaign and no reward
      // entry, so without it the line answers "No linked entry for this line".
      const { data, error } = await supabase.from('creator_payouts')
        .select('campaign_id, reward_entry_id, payroll_period').eq('id', source_id).single();
      if (error) throw error;
      keys = {
        campaignId: data?.campaign_id,
        rewardEntryId: data?.reward_entry_id,
        payrollPeriod: data?.payroll_period,
      };
    } else if (source_type === 'split') {
      const { data: s, error: sErr } = await supabase.from('payout_splits')
        .select('payout_id').eq('id', source_id).single();
      if (sErr) throw sErr;
      if (s?.payout_id) {
        const { data, error } = await supabase.from('creator_payouts')
          .select('campaign_id, reward_entry_id, payroll_period').eq('id', s.payout_id).single();
        if (error) throw error;
        keys = {
          campaignId: data?.campaign_id,
          rewardEntryId: data?.reward_entry_id,
          payrollPeriod: data?.payroll_period,
        };
      }
    } else if (source_type === 'oop_creator' || source_type === 'oop_partner' || source_type === 'oop_company') {
      const { data, error } = await supabase.from('expense_oop_payments')
        .select('expense_id').eq('id', source_id).single();
      if (error) throw error;
      keys = { expenseId: data?.expense_id };
    }
  } catch {
    if (toast?.error) toast.error({ title: 'Could not open entry', body: 'Lookup failed. Try the source page directly.' });
    return;
  }
  const evt = ledgerSourceEvent(keys);
  if (!evt) { if (toast?.info) toast.info('No linked entry for this line.'); return; }
  if (typeof window !== 'undefined') window.dispatchEvent(new window.CustomEvent(evt.name, { detail: evt.detail }));
}

/**
 * Wraps a ledger line's description so a navigable line becomes a quiet link to
 * its owning entry. Non-navigable lines (manual, year-end close) render their
 * children as-is. The link stops propagation so it never triggers the row's own
 * click (reconcile tick / GL expand), and on the reconcile table it yields to an
 * active text selection so drag-to-highlight still works.
 *
 * @param {object} props
 * @param {string} props.sourceType - JE source_type
 * @param {string} props.sourceId - JE source_id
 * @param {object} props.toast - useToast handle, for the no-target path
 * @param {React.ReactNode} props.children - the description content
 * @gotcha keep this a real <button> so it is keyboard reachable; the keydown
 *   stopPropagation prevents Enter from also expanding the GL row underneath.
 */
function LedgerSourceLink({ sourceType, sourceId, toast, children }) {
  if (!isNavigableLedgerSource(sourceType) || !sourceId) return children;
  return (
    <button
      type="button"
      className="ledger-srclink"
      title="Open the linked entry"
      onClick={(ev) => {
        ev.stopPropagation();
        // A real text selection means the user is highlighting, not navigating.
        const sel = typeof window !== 'undefined' ? window.getSelection() : null;
        if (sel && !sel.isCollapsed && String(sel).trim().length >= 3) return;
        openLedgerSource({ source_type: sourceType, source_id: sourceId }, toast);
      }}
      onKeyDown={(ev) => { if (ev.key === 'Enter' || ev.key === ' ') ev.stopPropagation(); }}
    >
      <span className="ledger-srclink-text">{children}</span>
      <ArrowRightIcon className="ledger-srclink-arrow" size={12} aria-hidden />
    </button>
  );
}

