/**
 * Human label for a date range ('All time', 'Mar 1 -> Apr 30, 2026', 'up to...').
 *
 * @invariant a To before the From is NAMED out of order, never drawn as a plain range. Both
 *            callers render this inside the filter card, ABOVE their own reversed-range
 *            refusal, so a bare `left to right` states a window the sentence under it denies.
 *            The compare is lexical on 'YYYY-MM-DD', the same idiom the two `rangeReversed`
 *            guards use, so the label and the refusal cannot disagree.
 */
function fmtRangeLabel(from, to) {
  if (!from && !to) return 'All time';
  const opts  = { month: 'short', day: 'numeric' };
  const optsY = { month: 'short', day: 'numeric', year: 'numeric' };
  const parse = (s) => s ? new Date(s + 'T00:00:00') : null;
  const fd = parse(from);
  const td = parse(to);
  if (fd && td) {
    const sameYear = fd.getFullYear() === td.getFullYear();
    const left  = sameYear ? fd.toLocaleDateString('en-US', opts) : fd.toLocaleDateString('en-US', optsY);
    const right = td.toLocaleDateString('en-US', optsY);
    if (to < from) return `${left} → ${right} (out of order)`;
    return `${left} → ${right}`;
  }
  if (fd) return `${fd.toLocaleDateString('en-US', optsY)} → now`;
  return `up to ${td.toLocaleDateString('en-US', optsY)}`;
}

