/**
 * Admin Financials shell. Owns the active tab + the globally-shared account
 * list (loaded once, threaded into every tab). Each tab unmounts on switch.
 *
 * @param {object} props
 * @param {object} [props.initialFilter] - cross-link payload: {tab} jumps to a
 *        tab; {source_type:'invoice', source_id} or {accountId} pre-filters GL;
 *        {tab:'tax', year} opens Tax Center on a year; {tab:'payroll', month}
 *        opens Payroll on a 'YYYY-MM', which is where a monthly paycheck's
 *        ledger line resolves to since it owns no record to open.
 * @param {function} [props.onFilterConsumed] - called once the filter is applied.
 * @param {boolean} [props.isAdmin=true] - gates every write affordance.
 * @see docs/CODEBASE.md (ledger UI)
 */
export default function LedgerPage({ initialFilter, onFilterConsumed, onNavigateToPaymentSetup, isAdmin = true }) {
  const [tab, setTab] = useState('activity');
  const [accounts, setAccounts] = useState([]);
  const [accountsLoading, setAccountsLoading] = useState(true);
  const [accountsError, setAccountsError] = useState(null);
  // People-tab drill-down: temporarily overrides the parent initialFilter so
  // a row click filters the GL tab to that person's ledger account.
  const [drillFilter, setDrillFilter] = useState(null);

  // Account list is needed by every tab - load once globally.
  //
  // @gotcha `error` is not optional here either. Every statement is drawn by mapping lines
  //         ONTO these accounts, so an empty list is a complete set of statements at $0.00
  //         whose tie-out passes, exactly the shape useAllLines was hardened against. A
  //         refused list and a genuinely empty one arrive as the same `data || []`.
  const loadAccounts = useCallback(async () => {
    const { data, error } = await supabase
      .from('ledger_accounts').select('*').order('code', { ascending: true });
    if (error) {
      log('accounts', error);
      setAccounts([]);
      setAccountsError(error);
      setAccountsLoading(false);
      return;
    }
    setAccountsError(null);
    setAccounts(data || []);
    setAccountsLoading(false);
  }, []);
  // Chart of Accounts refetches through loadAccounts after every write, and that refresh
  // stays silent. Only the retry re-enters the loading state.
  const retryAccounts = useCallback(() => { setAccountsLoading(true); loadAccounts(); }, [loadAccounts]);
  useEffect(() => { loadAccounts(); }, [loadAccounts]);

  // initialFilter from PaymentsPage/RewardsPage cross-links (default to GL)
  // or from PartnersView "View K-1" link (initialFilter.tab='tax').
  useEffect(() => {
    if (!initialFilter) return;
    setTab(initialFilter.tab && TABS.some((t) => t.id === initialFilter.tab) ? initialFilter.tab : 'gl');
  }, [initialFilter]);

  return (
    <div className="page">
      <div className="page-header">
        <div>
          <h1 className="page-title">
            FINANCIALS
            {(() => {
              const t = TABS.find((x) => x.id === tab);
              return t?.helpSlug ? <HelpIcon slug={t.helpSlug} /> : null;
            })()}
          </h1>
          <div className="page-subtitle">General ledger, statements, and reconciliation</div>
        </div>
      </div>

      <div className="tab-bar" style={{ display: 'flex', gap: 4, borderBottom: '1px solid var(--border)', marginBottom: 24, flexWrap: 'wrap' }}>
        {TABS.filter((t) => !t.adminOnly || isAdmin).map((t) => (
          <button
            key={t.id}
            className="btn btn-ghost"
            onClick={() => setTab(t.id)}
            style={{
              borderRadius: 0,
              borderBottom: tab === t.id ? '2px solid var(--orange)' : '2px solid transparent',
              color: tab === t.id ? 'var(--orange)' : 'var(--muted)',
              padding: '8px 14px',
              fontWeight: tab === t.id ? 700 : 400,
            }}
          >{t.label}</button>
        ))}
      </div>

      {accountsLoading ? <Loading /> : accountsError ? (
        <ReadError error={accountsError} onRetry={retryAccounts} />
      ) : (
        <>
          {tab === 'activity' && <ActivityTab accounts={accounts} isAdmin={isAdmin} onJumpToGl={(je) => setTab('gl')} />}
          {tab === 'people' && (
            <PeopleTab
              accounts={accounts}
              onJumpToGl={(accountId) => { setDrillFilter({ tab: 'gl', accountId }); setTab('gl'); }}
            />
          )}
          {tab === 'gl'    && <GeneralLedgerTab accounts={accounts} initialFilter={drillFilter || initialFilter} onFilterConsumed={() => { setDrillFilter(null); onFilterConsumed && onFilterConsumed(); }} isAdmin={isAdmin} />}
          {tab === 'coa'   && <ChartOfAccountsTab accounts={accounts} isAdmin={isAdmin} onAccountsChanged={loadAccounts} onNavigateToPaymentSetup={onNavigateToPaymentSetup} />}
          {tab === 'hist'  && <HistoryTab />}
          {tab === 'tb'    && <TrialBalanceTab    accounts={accounts} />}
          {tab === 'pl'    && <PLReportTab        accounts={accounts} isAdmin={isAdmin} />}
          {tab === 'bs'    && <BalanceSheetTab    accounts={accounts} />}
          {tab === 'recon' && <ReconcileBankTab   accounts={accounts} isAdmin={isAdmin} />}
          {/* adminOnly in TABS hides the button; guard the body too so a stale
              `tab` value from a role change can never render it to a creator. */}
          {tab === 'payroll' && isAdmin && <PayrollTab initialMonth={initialFilter?.month} />}
          {tab === 'tax'   && <TaxCenter initialYear={initialFilter?.tab === 'tax' ? initialFilter?.year : null} onConsumed={onFilterConsumed} />}
        </>
      )}
    </div>
  );
}

/**
 * Load every posted, live line and entry up to `asOfDate` for the statement tabs (Trial
 * Balance / P&L / Balance Sheet). Returns {entries, lines, loading, error, reload}; each line
 * is decorated with its entry's `entry_date` for downstream asOf filtering.
 *
 * @gotcha `error` is not optional for a consumer to read. An empty ledger and a refused one
 *         arrive here as the same {entries: [], lines: []}, and a statement built from no
 *         lines is a complete set of zeroes whose tie-out passes, because 0 = 0. All three
 *         tabs must render `error` BEFORE they render a statement. @see components/shared/ReadError.js
 *
 * @gotcha utils/ledger.js does NOT re-filter, so this is the only place the reversal pair is
 *         dropped. A reversal cancels its original: drop the original via
 *         `.is('reversed_by_je_id', null)` AND the counter-entry via isReversalEntry, or the
 *         net effect is double-counted. This mirrors filterFiscalYearLines in
 *         utils/ledger-tax.js.
 * @perf lines fetched in 500-id chunks to stay under PostgREST's `in` limit, and each chunk is
 *       then paged to exhaustion by fetchAllRows. Both bounds are real and different: `in`
 *       limits how many IDS fit in the request URL, the 1,000-row cap limits how many ROWS come
 *       back.
 * @see utils/ledger-tax.js (filterFiscalYearLines), utils/journalEntry.js (isReversalEntry)
 */
function useAllLines(asOfDate) {
  const [data, setData] = useState({ entries: [], lines: [], loading: true });
  // Bumped by reload() to re-run the effect on the SAME asOfDate, so the error state can
  // offer a retry rather than telling the reader to reload the page.
  const [attempt, setAttempt] = useState(0);
  const reload = useCallback(() => {
    setData({ entries: [], lines: [], loading: true });
    setAttempt((n) => n + 1);
  }, []);
  useEffect(() => {
    let alive = true;
    (async () => {
      // @gotcha reads to EXHAUSTION, and this is the half that did not. PostgREST caps any
      //         single response at 1,000 rows and reports nothing was cut, so the Trial
      //         Balance, the P&L and the Balance Sheet were all built from whatever the first
      //         thousand entries happened to be. The LINES fetch below already paged, which
      //         is exactly what kept this invisible: the hook read as though it paginated.
      //; utils/fetchAllRows.js
      let entries;
      try {
        entries = await fetchAllRows(() => {
          let q = supabase
            .from('ledger_journal_entries')
            .select('id, entry_date, description, source_type, reversed_by_je_id')
            .eq('is_posted', true)
            .is('reversed_by_je_id', null)
            .order('id');
          if (asOfDate) q = q.lte('entry_date', asOfDate);
          return q;
        });
      } catch (eErr) {
        if (!alive) return;
        log('useAllLines entries', eErr);
        setData({ entries: [], lines: [], loading: false, error: eErr });
        return;
      }
      if (!alive) return;
      // Exclude entries that are themselves reversals (description starts with 'REVERSAL')
      const liveEntries = (entries || []).filter((e) => !isReversalEntry(e));
      const ids = liveEntries.map((r) => r.id);
      if (ids.length === 0) { setData({ entries: liveEntries, lines: [], loading: false }); return; }
      // Chunk to avoid PostgREST "in" overflow at large sizes.
      // @gotcha one refused chunk fails the WHOLE read. A chunk holds whole journal entries
      //         and a journal entry's own lines balance, so a chunk that goes missing takes an
      //         equal debit and credit with it: the Trial Balance still reports BALANCED, the
      //         Balance Sheet still ties out, and every figure is short by whatever that chunk
      //         held. There is no imbalance to notice, so a catch here that logs and continues
      //         is a wrong number nothing can see. fetchAllRows holds the same invariant one
      //         page down and this loop is the only place that can undo it.
      const chunks = [];
      for (let i = 0; i < ids.length; i += 500) chunks.push(ids.slice(i, i + 500));
      const all = [];
      for (const c of chunks) {
        try {
          const ls = await fetchAllRows(() => supabase
            .from('ledger_entry_lines').select('*').in('journal_entry_id', c).order('id'));
          for (const l of ls) all.push(l);
        } catch (lErr) {
          if (!alive) return;
          log('useAllLines lines', lErr);
          setData({ entries: [], lines: [], loading: false, error: lErr });
          return;
        }
      }
      // Decorate lines with entry_date for asOf filtering downstream
      const dateById = new Map(liveEntries.map((e) => [e.id, e.entry_date]));
      const decorated = all.map((l) => ({ ...l, entry_date: dateById.get(l.journal_entry_id) }));
      if (alive) setData({ entries: liveEntries, lines: decorated, loading: false });
    })();
    return () => { alive = false; };
  }, [asOfDate, attempt]);
  return { ...data, reload };
}

/**
 * General Ledger tab: filterable, paginated (100/page) JE table with row
 * expand (lines + audit history + reverse), Manual Entry, and CSV export.
 *
 * @gotcha unlike the statement tabs this lists reversal/reversed JEs (with a
 *         REVERSED badge) on purpose, so the GL stays a faithful event log.
 *         Account filtering happens on the lines side, so a row only stays
 *         visible if it has >=1 line on the chosen account.
 */
function GeneralLedgerTab({ accounts, initialFilter, onFilterConsumed, isAdmin }) {
  const [dateFrom,    setDateFrom]    = useState('');
  const [dateTo,      setDateTo]      = useState('');
  const [customOpen,  setCustomOpen]  = useState(false);
  const [accountId,   setAccountId]   = useState('');
  const [sourceFilt,  setSourceFilt]  = useState('all');
  const [search,      setSearch]      = useState('');
  const [entries,     setEntries]     = useState([]);
  const [lines,       setLines]       = useState([]);
  const { loading, refreshing, begin, end } = useLoadState();
  const [readError,   setReadError]   = useState(null);
  const [pageCount,   setPageCount]   = useState(1);
  const [expanded,    setExpanded]    = useState(null);
  const [reverseFor,  setReverseFor]  = useState(null); // { entry, lines }
  const [auditByJe,   setAuditByJe]   = useState({});
  const [showManualEntry, setShowManualEntry] = useState(false);
  const toast = useToast();

  const accountById = useMemo(() => new Map(accounts.map((a) => [a.id, a])), [accounts]);

  // Sort state for the GL table. Default Date desc (matches fetch order).
  const sorter = useSortState('entry_date', 'desc');

  // Refs for scrolling reversal cross-reference jumps into view.
  const rowRefs = React.useRef({});

  // Apply initial cross-link filter once.
  useEffect(() => {
    if (initialFilter && initialFilter.source_type && initialFilter.source_id) {
      // ANY source type, not just 'invoice': a health record names a payout, a split or a
      // year-end close just as often, and one hard-coded type leaves the rest on an unfiltered
      // ledger that reads as a link doing nothing. We cannot accountId-filter without knowing
      // which account the record posted to; the source filter narrows it well enough.
      setSourceFilt(initialFilter.source_type);
      if (onFilterConsumed) onFilterConsumed();
    }
    if (initialFilter && initialFilter.accountId) {
      setAccountId(initialFilter.accountId);
      if (onFilterConsumed) onFilterConsumed();
    }
  }, [initialFilter, onFilterConsumed]);

  const fetchPage = useCallback(async () => {
    begin();
    setReadError(null);
    let q = supabase
      .from('ledger_journal_entries')
      .select('*')
      .eq('is_posted', true)
      .order('entry_date', { ascending: false })
      .order('created_at', { ascending: false })
      .limit(PAGE_SIZE * pageCount);

    if (dateFrom) q = q.gte('entry_date', dateFrom);
    if (dateTo)   q = q.lte('entry_date', dateTo);
    if (sourceFilt !== 'all') q = q.eq('source_type', sourceFilt);
    if (initialFilter && initialFilter.source_type && initialFilter.source_id) {
      q = q.eq('source_type', initialFilter.source_type).eq('source_id', initialFilter.source_id);
    }
    // @gotcha `entryId` is the ONLY way to reach half the entries a health check names: a
    //         lopsided pair and an unclaimed reversal carry no source id, and a reversal's
    //         source_type is 'manual', so neither the source nor the account filter finds them.
    if (initialFilter && initialFilter.entryId) q = q.eq('id', initialFilter.entryId);
    if (search.trim()) q = q.ilike('description', `%${search.trim()}%`);

    // @gotcha neither half may be swallowed, and the LINES half is the one that reads as
    //         normal. Its rows carry no copy of their own: they become the per-entry debit
    //         and credit totals, so a refused read draws $0.00 in both money columns of
    //         every real entry, and an empty expansion under it. A refused ENTRIES read is
    //         the softer twin, "No journal entries match these filters." over a ledger
    //         nobody read. @see components/shared/ReadError.js
    const { data: e, error: eErr } = await q;
    if (eErr) { log('entries', eErr); setEntries([]); setLines([]); setReadError(eErr); end(); return; }
    const ids = (e || []).map((r) => r.id);
    const l = [];
    // The page grows by PAGE_SIZE on every Load more, so this read climbs into both of the
    // bounds useAllLines already respects: `in` limits how many IDS fit in the request URL,
    // and the 1,000-row cap limits how many ROWS come back. Past roughly 500 entries an
    // unpaged read left the last rows on screen carrying a real date, a real description and
    // $0.00 in both money columns. Chunked at 500 and paged, the same as useAllLines.
    // @see utils/fetchAllRows.js
    try {
      for (let i = 0; i < ids.length; i += 500) {
        const chunk = ids.slice(i, i + 500);
        const page = await fetchAllRows(() => {
          let lq = supabase.from('ledger_entry_lines').select('*').in('journal_entry_id', chunk).order('id');
          if (accountId) lq = lq.eq('account_id', accountId);
          return lq;
        });
        for (const row of page) l.push(row);
      }
    } catch (lErr) {
      log('lines', lErr); setEntries([]); setLines([]); setReadError(lErr); end(); return;
    }
    setEntries(e || []);
    setLines(l);
    end();
  }, [dateFrom, dateTo, accountId, sourceFilt, search, pageCount, initialFilter, begin, end]);

  useEffect(() => { fetchPage(); }, [fetchPage]);

  // Lazy-load audit log rows for an expanded JE.
  async function ensureAudit(jeId) {
    if (auditByJe[jeId] !== undefined) return;
    const { data, error } = await supabase
      .from('ledger_audit_log')
      .select('*')
      .eq('journal_entry_id', jeId)
      .order('created_at', { ascending: true });
    if (error) { log('audit', error); return; }
    setAuditByJe((m) => ({ ...m, [jeId]: data || [] }));
  }

  const linesByJe = useMemo(() => {
    const m = new Map();
    for (const ln of lines) {
      if (!m.has(ln.journal_entry_id)) m.set(ln.journal_entry_id, []);
      m.get(ln.journal_entry_id).push(ln);
    }
    return m;
  }, [lines]);

  // Decorate lines with account info for display + reversal modal.
  const decoratedLines = (jeId) => (linesByJe.get(jeId) || []).map((l) => {
    const a = accountById.get(l.account_id);
    return { ...l, account_code: a?.code, account_name: a?.name, account_normal_balance: a?.normal_balance };
  });

  // Per-entry debit/credit totals (precomputed once so sort comparators are O(1)).
  const entryTotals = useMemo(() => {
    const m = new Map();
    for (const e of entries) {
      const ls = linesByJe.get(e.id) || [];
      const t = ls.reduce(
        (acc, l) => ({ d: acc.d + Number(l.debit || 0), c: acc.c + Number(l.credit || 0) }),
        { d: 0, c: 0 }
      );
      m.set(e.id, t);
    }
    return m;
  }, [entries, linesByJe]);

  // Show only entries that have at least one line matching the account filter.
  const visibleEntries = useMemo(() => {
    const filtered = !accountId ? entries : entries.filter((e) => (linesByJe.get(e.id) || []).length > 0);
    return sorter.sortRows(filtered, {
      entry_date: (e) => e.entry_date,
      debit:      (e) => entryTotals.get(e.id)?.d || 0,
      credit:     (e) => entryTotals.get(e.id)?.c || 0,
    });
  }, [entries, accountId, linesByJe, sorter, entryTotals]);

  // Map id -> entry, for reversal cross-reference lookups.
  const entryById = useMemo(() => new Map(entries.map((e) => [e.id, e])), [entries]);

  // For an entry that IS a reversal (description starts with REVERSAL:),
  // find the original entry whose reversed_by_je_id points back here.
  const originalByReversalId = useMemo(() => {
    const m = new Map();
    for (const e of entries) if (e.reversed_by_je_id) m.set(e.reversed_by_je_id, e);
    return m;
  }, [entries]);

  function jumpToEntry(jeId) {
    if (!jeId) return;
    setExpanded(jeId);
    ensureAudit(jeId);
    // Defer scroll until after expansion render.
    setTimeout(() => {
      const el = rowRefs.current[jeId];
      if (el && el.scrollIntoView) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }, 50);
  }

  const filtersDirty =
    !!dateFrom || !!dateTo || !!accountId || sourceFilt !== 'all' || !!search.trim();
  // @invariant a reversed range is named, never answered. Both ends go straight to `.gte` and
  //            `.lte`, so a To before the From asks for entries on or after a later date out of
  //            a set already capped at an earlier one: zero rows, and the ordinary no-match
  //            sentence then claims nothing happened in that window. ISO YYYY-MM-DD sorts
  //            lexically, so the string compare is safe.
  const rangeReversed = !!dateFrom && !!dateTo && dateTo < dateFrom;
  function clearAllFilters() {
    setDateFrom(''); setDateTo(''); setAccountId(''); setSourceFilt('all'); setSearch('');
    setCustomOpen(false);
  }

  function handleExportCsv() {
    const csv = formatGeneralLedgerCsv(entries, lines, accounts, {
      dateFrom: dateFrom || null,
      dateTo:   dateTo   || null,
      accountId: accountId || null,
      sourceTypes: sourceFilt === 'all' ? null : [sourceFilt],
      search: search.trim() || null,
    });
    downloadString(`general-ledger-${todayYMD()}.csv`, csv);
  }

  return (
    <>
      {/* Filter bar */}
      <div className="card" style={{ marginBottom: 16, padding: '18px 20px' }}>
        {/* Row 1: typographic date filter: active range readout + preset row */}
        <div style={{
          display: 'flex',
          alignItems: 'baseline',
          justifyContent: 'space-between',
          gap: 24,
          flexWrap: 'wrap',
        }}>
          <div style={{
            fontFamily: 'var(--font-body)',
            fontSize: 14,
            fontWeight: 600,
            color: 'var(--white)',
            letterSpacing: '1.4px',
            textTransform: 'uppercase',
            fontVariantNumeric: 'tabular-nums',
          }}>
            {fmtRangeLabel(dateFrom, dateTo)}
          </div>
          <div style={{
            display: 'flex',
            alignItems: 'baseline',
            fontSize: 11,
            letterSpacing: '1px',
            textTransform: 'uppercase',
            fontWeight: 500,
          }}>
            {DATE_PRESETS.map((p, i) => {
              const r = p.range();
              const active = (dateFrom || '') === r.from && (dateTo || '') === r.to;
              return (
                <React.Fragment key={p.id}>
                  {i > 0 ? <span style={{ color: 'var(--dim)', padding: '0 10px' }}>·</span> : null}
                  <button
                    onClick={() => { setDateFrom(r.from); setDateTo(r.to); setCustomOpen(false); }}
                    className="ledger-date-preset"
                    style={{
                      background: 'transparent',
                      border: 0,
                      padding: '2px 0',
                      cursor: 'pointer',
                      color: active ? 'var(--orange)' : 'var(--muted)',
                      fontFamily: 'inherit',
                      fontSize: 'inherit',
                      fontWeight: active ? 600 : 500,
                      letterSpacing: 'inherit',
                      textTransform: 'inherit',
                      transition: 'color 120ms ease',
                    }}
                  >{p.label}</button>
                </React.Fragment>
              );
            })}
            <span style={{ color: 'var(--dim)', padding: '0 10px' }}>·</span>
            {(() => {
              const noPresetMatches = !DATE_PRESETS.some((p) => {
                const r = p.range();
                return (dateFrom || '') === r.from && (dateTo || '') === r.to;
              });
              const active = customOpen || noPresetMatches;
              return (
                <button
                  onClick={() => setCustomOpen((v) => !v)}
                  className="ledger-date-preset"
                  style={{
                    background: 'transparent',
                    border: 0,
                    padding: '2px 0',
                    cursor: 'pointer',
                    color: active ? 'var(--orange)' : 'var(--muted)',
                    fontFamily: 'inherit',
                    fontSize: 'inherit',
                    fontWeight: active ? 600 : 500,
                    letterSpacing: 'inherit',
                    textTransform: 'inherit',
                    transition: 'color 120ms ease',
                  }}
                >Custom</button>
              );
            })()}
          </div>
        </div>

        {/* Row 1b: custom date inputs: only visible when Custom is toggled */}
        {customOpen ? (
          <div style={{
            display: 'flex',
            gap: 12,
            marginTop: 12,
            alignItems: 'flex-end',
            paddingTop: 12,
            borderTop: '1px solid var(--border)',
          }}>
            <Field label="From" style={{ marginBottom: 0 }}>{(id) => (<>
              <input id={id} className="form-input" type="date" min={DB_DATE_MIN} max={DB_DATE_MAX} value={dateFrom} onChange={(e) => setDateFrom(e.target.value)} style={{ width: 160 }} />
            </>)}</Field>
            <Field label="To" style={{ marginBottom: 0 }}>{(id) => (<>
              <input id={id} className="form-input" type="date" min={dateFrom || DB_DATE_MIN} max={DB_DATE_MAX} value={dateTo} onChange={(e) => setDateTo(e.target.value)} style={{ width: 160 }} />
            </>)}</Field>
            {(dateFrom || dateTo) ? (
              <button
                onClick={() => { setDateFrom(''); setDateTo(''); }}
                style={{
                  background: 'transparent',
                  border: 0,
                  padding: '8px 0',
                  cursor: 'pointer',
                  color: 'var(--muted)',
                  fontSize: 11,
                  letterSpacing: '1px',
                  textTransform: 'uppercase',
                  fontWeight: 500,
                  marginBottom: 4,
                }}
              >Clear dates</button>
            ) : null}
          </div>
        ) : null}

        {/* Row 2: account + search */}
        <div style={{ display: 'flex', gap: 12, marginTop: 16, flexWrap: 'wrap', alignItems: 'flex-end' }}>
          <Field label="Account" style={{ marginBottom: 0, flex: 1, minWidth: 240 }}>{(id) => (<>
            <select id={id} className="form-select" value={accountId} onChange={(e) => setAccountId(e.target.value)}>
              <option value="">All accounts</option>
              {accounts.filter((a) => a.is_active !== false).map((a) => (
                <option key={a.id} value={a.id}>{a.code} · {a.name}</option>
              ))}
            </select>
          </>)}</Field>
          <Field label="Search description" style={{ marginBottom: 0, flex: 2, minWidth: 240 }}>{(id) => (<>
            <input id={id} className="form-input" type="text" maxLength={200} value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Free-text search" />
          </>)}</Field>
        </div>

        {/* Row 3: source-type filter + actions */}
        <div style={{ display: 'flex', gap: 6, marginTop: 16, alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap' }}>
          <div style={{ display: 'flex', gap: 4 }}>
            {SOURCE_FILTERS.map((s) => (
              <button
                key={s.id}
                className="btn btn-ghost btn-sm"
                onClick={() => setSourceFilt(s.id)}
                style={{
                  borderRadius: 999,
                  border: '1px solid var(--border2)',
                  color: sourceFilt === s.id ? 'var(--orange)' : 'var(--muted)',
                  background: sourceFilt === s.id ? 'var(--orange-glow)' : 'transparent',
                }}
              >{s.label}</button>
            ))}
          </div>
          <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
            {filtersDirty ? (
              <button className="btn btn-ghost btn-sm" onClick={clearAllFilters} title="Reset every filter">Clear filters</button>
            ) : null}
            {/* A reversed range takes Export CSV with it, the same way the P&L tab withholds its
                Export PDF (P150). `formatGeneralLedgerCsv` applies these same two bounds, so
                every line drops and what lands on disk is a header row with nothing under it,
                while neither the header nor the file name says which two dates emptied it.
                The refusal below the card names both. */}
            {rangeReversed ? null : (
              <button className="btn btn-ghost btn-sm" onClick={handleExportCsv}>Export CSV</button>
            )}
            {isAdmin ? (
              <>
                <button className="btn btn-secondary btn-sm" onClick={() => setShowManualEntry(true)}>+ New Manual Entry</button>
                <HelpIcon slug="manual-entry" />
              </>
            ) : null}
          </div>
        </div>
      </div>

      {/* Result count */}
      {!loading && entries.length > 0 ? (
        <div style={{ marginBottom: 8, fontSize: 11, color: 'var(--muted)', letterSpacing: 0.4, textTransform: 'uppercase' }}>
          Showing {visibleEntries.length} of {entries.length} {entries.length === 1 ? 'entry' : 'entries'}
        </div>
      ) : null}

      {/* Transaction table */}
      <Refreshing on={refreshing} />
      {loading ? <Loading /> : readError ? (
        <ReadError error={readError} onRetry={fetchPage} />
      ) : (
        rangeReversed ? (
          <EmptyState
            title="The To date is before the From date."
            text={`Set To on or after ${fmtDate(dateFrom)} to see the entries in that range.`}
            action={<button className="btn btn-ghost btn-sm" onClick={clearAllFilters}>Clear filters</button>} />
        ) : visibleEntries.length === 0 ? (
          /* Every filter here runs in the QUERY, so there is no unfiltered array to hold up
             against this one and `filtersDirty` is the whole discriminator the surface has.
             It is a sound one, because this tab opens completely unfiltered. The title said
             "match these filters" on BOTH branches, so a brand new set of books was told its
             filters were hiding something, on the very tab hub-ui.md holds up as the model.
             Same shape as ActivityTab, which is where the wording comes from. */
          <EmptyState
            title={filtersDirty ? 'No journal entries match these filters' : 'No journal entries yet'}
            text={filtersDirty
              ? 'Adjust the date range, the account or the search.'
              : 'Posted entries appear here as they happen.'}
            action={filtersDirty
              ? <button className="btn btn-ghost btn-sm" onClick={clearAllFilters}>Clear filters</button>
              : null} />
        ) : (
          <div className="table-wrap">
            <table style={{ width: '100%' }}>
              <thead>
                <tr>
                  <th scope="col" style={{ width: 28 }} aria-label="Expand" />
                  <th scope="col" style={{ width: 110, whiteSpace: 'nowrap' }}
                    aria-sort={sorter.sortBy === 'entry_date' ? (sorter.sortDir === 'asc' ? 'ascending' : 'descending') : 'none'}
                  >
                    <button type="button" className="th-sort" onClick={() => sorter.toggle('entry_date')}>
                      Date<SortIcon col="entry_date" sortBy={sorter.sortBy} sortDir={sorter.sortDir} />
                    </button>
                  </th>
                  <th scope="col">Description</th>
                  <th scope="col" style={{ width: 110 }}>Source</th>
                  <th scope="col"
                    style={{ width: 110, textAlign: 'right', whiteSpace: 'nowrap' }}
                    aria-sort={sorter.sortBy === 'debit' ? (sorter.sortDir === 'asc' ? 'ascending' : 'descending') : 'none'}
                  >
                    <span className="gl-th-wrap">
                      <button type="button" className="th-sort" onClick={() => sorter.toggle('debit')}>
                        Debit<SortIcon col="debit" sortBy={sorter.sortBy} sortDir={sorter.sortDir} />
                      </button>
                      <ColHeaderInfo
                        title="What does Debit mean?"
                        rows={[
                          'Increases: Assets and Expenses.',
                          'Decreases: Liabilities, Equity, Revenue.',
                        ]}
                        foot="The accounting term is Debit (DR)."
                      />
                    </span>
                  </th>
                  <th scope="col"
                    style={{ width: 110, textAlign: 'right', whiteSpace: 'nowrap' }}
                    aria-sort={sorter.sortBy === 'credit' ? (sorter.sortDir === 'asc' ? 'ascending' : 'descending') : 'none'}
                  >
                    <span className="gl-th-wrap">
                      <button type="button" className="th-sort" onClick={() => sorter.toggle('credit')}>
                        Credit<SortIcon col="credit" sortBy={sorter.sortBy} sortDir={sorter.sortDir} />
                      </button>
                      <ColHeaderInfo
                        title="What does Credit mean?"
                        rows={[
                          'Increases: Liabilities, Equity, Revenue.',
                          'Decreases: Assets and Expenses.',
                        ]}
                        foot="The accounting term is Credit (CR)."
                      />
                    </span>
                  </th>
                </tr>
              </thead>
              <tbody>
                {visibleEntries.map((e) => {
                  const dl = decoratedLines(e.id);
                  const totals = entryTotals.get(e.id) || { d: 0, c: 0 };
                  const isExpanded = expanded === e.id;
                  const isReversed = !!e.reversed_by_je_id;
                  function toggleRow() {
                    const next = isExpanded ? null : e.id;
                    setExpanded(next);
                    if (next) ensureAudit(next);
                  }
                  return (
                    <React.Fragment key={e.id}>
                      <tr
                        ref={(el) => { if (el) rowRefs.current[e.id] = el; }}
                        className="gl-row"
                        role="button"
                        tabIndex={0}
                        aria-expanded={isExpanded}
                        onClick={toggleRow}
                        onKeyDown={(ev) => {
                          if (ev.key === 'Enter' || ev.key === ' ') {
                            ev.preventDefault();
                            toggleRow();
                          }
                        }}
                      >
                        <td style={{ textAlign: 'center' }}>
                          <svg
                            className={`gl-caret${isExpanded ? ' gl-caret--open' : ''}`}
                            viewBox="0 0 16 16"
                            width="10"
                            height="10"
                            aria-hidden="true"
                          >
                            <path d="M6 4l4 4-4 4" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
                          </svg>
                        </td>
                        <td style={{ fontVariantNumeric: 'tabular-nums', whiteSpace: 'nowrap' }}>{fmtDate(e.entry_date)}</td>
                        <td>
                          <LedgerSourceLink sourceType={e.source_type} sourceId={e.source_id} toast={toast}>
                            <span className={isReversed ? 'gl-reversed-desc' : undefined}>{e.description}</span>
                          </LedgerSourceLink>
                          {isReversed ? <span className="badge" style={{ marginLeft: 8, background: 'color-mix(in oklab, var(--red) 10%, transparent)', color: 'var(--red)' }}>REVERSED</span> : null}
                          {e.is_locked ? <span title="Locked period" style={{ marginLeft: 8, color: 'var(--muted)', display: 'inline-flex', alignItems: 'center' }}><LockIcon size={12} title="Locked period" /></span> : null}
                        </td>
                        <td><span className="gl-source-chip">{e.source_type || 'manual'}</span></td>
                        <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{fmtMoney(totals.d)}</td>
                        <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{fmtMoney(totals.c)}</td>
                      </tr>
                      {isExpanded ? (
                        <tr>
                          <td colSpan={6} className="gl-expanded-cell">
                            <ExpandedEntry
                              entry={e}
                              lines={dl}
                              totals={totals}
                              audit={auditByJe[e.id] || []}
                              isAdmin={isAdmin}
                              onReverse={() => setReverseFor({ entry: e, lines: dl })}
                              reversingEntry={e.reversed_by_je_id ? entryById.get(e.reversed_by_je_id) : null}
                              originalEntry={originalByReversalId.get(e.id) || null}
                              onJumpToEntry={jumpToEntry}
                            />
                          </td>
                        </tr>
                      ) : null}
                    </React.Fragment>
                  );
                })}
              </tbody>
            </table>
            {entries.length === PAGE_SIZE * pageCount ? (
              <div style={{ textAlign: 'center', padding: 12 }}>
                <button className="btn btn-secondary btn-sm" onClick={() => setPageCount((n) => n + 1)}>Load more</button>
              </div>
            ) : null}
          </div>
        )
      )}

      {reverseFor ? (
        <ReverseEntryModal
          journalEntry={reverseFor.entry}
          lines={reverseFor.lines}
          onClose={() => setReverseFor(null)}
          onReversed={() => { setReverseFor(null); setExpanded(null); fetchPage(); }}
        />
      ) : null}

      {showManualEntry ? (
        <ManualEntryModal accounts={accounts} onClose={() => setShowManualEntry(false)} onCreated={() => { setShowManualEntry(false); fetchPage(); }} />
      ) : null}
    </>
  );
}

/**
 * People tab: per-person out-of-pocket totals (lifetime / this year /
 * outstanding) plus a trailing-12-month sparkline, split into Creators and
 * Partners. A card click drills the GL tab to that person's ledger account.
 *
 * @gotcha partner OOP is allocated across partners by partner_allocation_pct
 *         (normalised to the active partners' total, defaulting to 100). Only
 *         posted, non-reversed expense_oop_payments rows count.
 * @see docs/MONEY.md Pattern P (creator OOP), Pattern Q (partner OOP)
 */
function PeopleTab({ accounts, onJumpToGl }) {
  const [rows, setRows] = useState({ creators: [], partners: [] });
  const [destinationsByCreator, setDestinationsByCreator] = useState({});
  const [sparklines, setSparklines] = useState({}); // personId -> [m0..m11] (oldest to newest)
  const [loading, setLoading] = useState(true);
  // The four states in order. Without the error one, a refused read renders "No
  // out-of-pocket entries recorded yet." on a company that owes a creator money.
  // @see .claude/rules/hub-ui.md, components/shared/ReadError.js
  const [err, setErr] = useState(null);
  const [attempt, setAttempt] = useState(0);
  const reload = useCallback(() => { setErr(null); setAttempt((n) => n + 1); }, []);
  const year = new Date().getFullYear();

  useEffect(() => {
    let cancelled = false;
    async function load() {
      setLoading(true);
      const today = new Date();
      const sparkStart = new Date(today.getFullYear(), today.getMonth() - 11, 1);
      const sparkStartYmd = `${sparkStart.getFullYear()}-${String(sparkStart.getMonth() + 1).padStart(2, '0')}-01`;
      // fetchOopByPerson throws; the other three report through { error }. All four
      // build one answer, so any of them failing fails all of it.
      let people;
      let pdRes; let oopRes; let partnerRes;
      try {
        [people, pdRes, oopRes, partnerRes] = await Promise.all([
          fetchOopByPerson({ year }),
          supabase
            .from('payment_destinations')
            .select('oop_creator_id, ledger_account_id')
            .not('oop_creator_id', 'is', null),
          supabase
            .from('expense_oop_payments')
            .select('amount, paid_at, payer_type, payer_creator_id, je:ledger_journal_entries!journal_entry_id(is_posted, reversed_by_je_id)')
            .gte('paid_at', sparkStartYmd),
          supabase.from('profiles').select('id, partner_allocation_pct').eq('role', 'admin'),
        ]);
      } catch (e) {
        if (!cancelled) { setErr(e); setLoading(false); }
        return;
      }
      if (cancelled) return;
      const readErr = pdRes.error || oopRes.error || partnerRes.error;
      if (readErr) { setErr(readErr); setLoading(false); return; }
      const { data: pds } = pdRes;
      const { data: rawOop } = oopRes;
      const { data: partnerProfiles } = partnerRes;
      const byCreator = {};
      (pds || []).forEach((pd) => { byCreator[pd.oop_creator_id] = pd.ledger_account_id; });
      setDestinationsByCreator(byCreator);
      // Per-person, per-month buckets across the trailing 12 months.
      const partnerOnly = (partnerProfiles || []).filter((p) => p.partner_allocation_pct != null);
      const totalAlloc = partnerOnly.reduce((s, p) => s + Number(p.partner_allocation_pct || 0), 0) || 100;
      // paid_at is a `date` column (schemas/SCHEMA.sql, expense_oop_payments), so
      // new Date(paid_at) is UTC midnight, which is the PREVIOUS day everywhere in the US:
      // an expense paid on the 1st was drawn in the previous month's bar. parseLocalDate
      // reads the parts. @see .claude/rules/hub-data.md
      const monthIndex = (ymd) => {
        const d = parseLocalDate(ymd);
        if (!d) return 0;
        const months = (d.getFullYear() - sparkStart.getFullYear()) * 12 + (d.getMonth() - sparkStart.getMonth());
        return Math.max(0, Math.min(11, months));
      };
      const sparks = {};
      for (const o of rawOop || []) {
        if (!o.je?.is_posted || o.je.reversed_by_je_id) continue;
        const idx = monthIndex(o.paid_at);
        const amt = parseFloat(o.amount) || 0;
        if (o.payer_type === 'creator' && o.payer_creator_id) {
          if (!sparks[o.payer_creator_id]) sparks[o.payer_creator_id] = Array(12).fill(0);
          sparks[o.payer_creator_id][idx] += amt;
        } else if (o.payer_type === 'partners') {
          for (const p of partnerOnly) {
            const pct = Number(p.partner_allocation_pct || 0);
            if (pct <= 0) continue;
            if (!sparks[p.id]) sparks[p.id] = Array(12).fill(0);
            sparks[p.id][idx] += amt * (pct / totalAlloc);
          }
        }
      }
      setSparklines(sparks);
      setRows(people);
      setLoading(false);
    }
    load();
    return () => { cancelled = true; };
  }, [year, attempt]);

  const partnerAccountByProfile = useMemo(() => {
    const map = {};
    (accounts || []).forEach((a) => {
      if (a.source_type === 'partner' && a.code && a.code.startsWith('30')) {
        map[a.source_id] = a.id;
      }
    });
    return map;
  }, [accounts]);

  if (loading) return <Loading />;
  if (err) return <ReadError error={err} onRetry={reload} />;

  const hasAnything = rows.creators.some((c) => c.lifetime > 0 || c.outstanding > 0)
    || rows.partners.some((p) => p.lifetime > 0);

  if (!hasAnything) {
    return (
      <EmptyState variant="note" style={{ padding: '14px 4px' }}
        text="No out-of-pocket entries recorded yet." />
    );
  }

  const renderSparkline = (personId, kind) => {
    const series = sparklines[personId] || Array(12).fill(0);
    const max = Math.max(...series, 0.0001);
    return (
      <div className={`oop-sparkline${kind === 'creator' ? ' is-creator' : ''}`} aria-hidden="true">
        {series.map((v, i) => (
          <div key={i} className="oop-sparkline-bar" style={{ height: `${Math.max(2, (v / max) * 100)}%`, opacity: v > 0 ? 0.95 : 0.18 }} />
        ))}
      </div>
    );
  };

  return (
    <div className="oop-people-grid">
      <div>
        <div className="oop-people-col-label">Creators</div>
        {rows.creators.length === 0 ? (
          <EmptyState variant="note" text="No creator OOP entries." />
        ) : rows.creators.map((c) => {
          const acctId = destinationsByCreator[c.id];
          return (
            <div
              key={c.id}
              className="oop-person-card"
              onClick={acctId ? () => onJumpToGl(acctId) : undefined}
              role={acctId ? 'button' : undefined}
              tabIndex={acctId ? 0 : -1}
              onKeyDown={(e) => { if ((e.key === 'Enter' || e.key === ' ') && acctId) { e.preventDefault(); onJumpToGl(acctId); } }}
            >
              <div className="oop-person-card-name">{c.name}</div>
              <div className="oop-person-card-underline" />
              {c.outstanding > 0 ? (
                <>
                  <div className="oop-person-card-outstanding-label">Outstanding</div>
                  <div className="oop-person-card-outstanding">{fmtMoney(c.outstanding)}</div>
                </>
              ) : null}
              <div className="oop-person-card-totals">
                <span>This year <strong>{fmtMoney(c.thisYear)}</strong></span>
                <span>·</span>
                <span>Lifetime <strong>{fmtMoney(c.lifetime)}</strong></span>
              </div>
              {renderSparkline(c.id, 'creator')}
            </div>
          );
        })}
      </div>

      <div>
        <div className="oop-people-col-label">Partners</div>
        {rows.partners.length === 0 ? (
          <EmptyState variant="note" text="No partner OOP entries." />
        ) : rows.partners.map((p) => {
          const acctId = partnerAccountByProfile[p.id];
          return (
            <div
              key={p.id}
              className="oop-person-card"
              onClick={acctId ? () => onJumpToGl(acctId) : undefined}
              role={acctId ? 'button' : undefined}
              tabIndex={acctId ? 0 : -1}
              onKeyDown={(e) => { if ((e.key === 'Enter' || e.key === ' ') && acctId) { e.preventDefault(); onJumpToGl(acctId); } }}
            >
              <div className="oop-person-card-name">{p.name}</div>
              <div className="oop-person-card-underline" />
              <div className="oop-person-card-totals">
                <span>This year <strong>{fmtMoney(p.thisYear)}</strong></span>
                <span>·</span>
                <span>Lifetime <strong>{fmtMoney(p.lifetime)}</strong></span>
                <span style={{ marginLeft: 'auto', color: 'var(--dim)' }}>{p.allocationPct}%</span>
              </div>
              {renderSparkline(p.id, 'partner')}
            </div>
          );
        })}
      </div>
    </div>
  );
}

/**
 * Manual journal-entry builder. Raw debit/credit line editor that only enables
 * submit when debits == credits and every row has an account + amount. A Refund
 * purpose switches to a guided sub-form that derives the line pair for you.
 *
 * @invariant SUM(debit) == SUM(credit) before insert (DB also enforces this via
 *            the per-JE constraint trigger).
 * @gotcha refund mode auto-derives the Pattern L/M/N lines and disables manual
 *         line editing; the reason is required and written to ledger_audit_log.
 * @security entry_date is capped at today (already-happened events) so a typo
 *           cannot date a JE years out; range pinned to [].
 * @see docs/MONEY.md Patterns L (revenue refund), M (expense refund), N (payout clawback)
 */
function ManualEntryModal({ accounts, onClose, onCreated }) {
  const toast = useToast();
  const today = todayYMD();
  const [purpose, setPurpose]         = useState('other');
  const [entryDate, setEntryDate] = useState(today);
  const [description, setDescription] = useState('');
  const [reference, setReference]     = useState('');
  const [rows, setRows] = useState([
    { id: 1, account_id: '', debit: '', credit: '', description: '' },
    { id: 2, account_id: '', debit: '', credit: '', description: '' },
  ]);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');

  // Refund sub-flow state (Decision #28; Patterns L/M/N)
  const [refundSourceType, setRefundSourceType] = useState('invoice'); // 'invoice' | 'expense' | 'split'
  const [refundSources, setRefundSources]       = useState([]);
  const [refundSourceId, setRefundSourceId]     = useState('');
  const [refundAmount, setRefundAmount]         = useState('');
  const [refundReason, setRefundReason]         = useState('');
  const [loadingSources, setLoadingSources]     = useState(false);
  const [sourcesErr,    setSourcesErr]          = useState(null);

  const isRefund = purpose === 'refund';

  // Helpers to look up ledger account ids by code or by source pointer.
  const findAccountByCode = useCallback((code) =>
    accounts.find((a) => a.code === code), [accounts]);
  const findAccountBySource = useCallback((sourceType, sourceId, codePrefix) =>
    accounts.find((a) => a.source_type === sourceType && a.source_id === sourceId
      && (!codePrefix || (a.code || '').startsWith(codePrefix))), [accounts]);

  // Load source list when switching refund-source-type. Each option carries
  // the data we need to compute the Pattern L/M/N account pair.
  useEffect(() => {
    if (!isRefund) return;
    let alive = true;
    (async () => {
      setLoadingSources(true);
      setRefundSourceId('');
      setRefundSources([]);
      setSourcesErr(null);
      try {
        if (refundSourceType === 'invoice') {
          // Every one of the three pickers is read to exhaustion, because a row missing from
          // a picker is indistinguishable from a row that cannot be refunded, which is the
          // claim the comment in the catch below already refuses to make.
          const data = await fetchAllRows(() => supabase
            .from('invoices')
            .select('id, invoice_number, invoice_amount, amount_received, you_received_date, campaign_id, reward_entry_id')
            .order('you_received_date', { ascending: false, nullsFirst: false })
            .order('id'));
          if (alive) setRefundSources((data || []).map((r) => ({
            id: r.id,
            label: `${r.invoice_number || r.id.slice(0,8)}: ${fmtMoney(r.amount_received || r.invoice_amount || 0)}`,
            maxAmount: Number(r.amount_received || r.invoice_amount || 0),
          })));
        } else if (refundSourceType === 'expense') {
          const data = await fetchAllRows(() => supabase
            .from('expenses')
            .select('id, name, amount, category_id')
            .order('name')
            .order('id'));
          // expenses.category_id now points directly at the 6xxx ledger account.
          if (alive) setRefundSources((data || []).map((r) => ({
            id: r.id,
            label: `${r.name}: ${fmtMoney(r.amount || 0)}`,
            maxAmount: Number(r.amount || 0),
            accountId: r.category_id,
          })));
        } else if (refundSourceType === 'split') {
          const data = await fetchAllRows(() => supabase
            .from('payout_splits')
            .select('id, amount, cleared_date, payout_id, destination_id, creator_payouts!inner(profile_id, profiles!inner(creator_name, full_name))')
            .not('cleared_date', 'is', null)
            .not('destination_id', 'is', null)
            .order('cleared_date', { ascending: false })
            .order('id'));
          if (alive) setRefundSources((data || []).map((r) => ({
            id: r.id,
            label: `${r.creator_payouts?.profiles?.creator_name || r.creator_payouts?.profiles?.full_name || '?'} · ${fmtDate(r.cleared_date)} · ${fmtMoney(r.amount || 0)}`,
            maxAmount: Number(r.amount || 0),
            creatorId: r.creator_payouts?.profile_id,
          })));
        }
      } catch (e) {
        // An empty picker on a refund form reads as "nothing is refundable",
        // and the entry it builds posts a journal entry against the choice.
        if (alive) setSourcesErr(humanizeError(e));
      } finally {
        if (alive) setLoadingSources(false);
      }
    })();
    return () => { alive = false; };
  }, [isRefund, refundSourceType]);

  // Derive Pattern L/M/N rows whenever refund inputs change.
  useEffect(() => {
    if (!isRefund) return;
    const src = refundSources.find((s) => s.id === refundSourceId);
    const amt = parseFloat(refundAmount);
    if (!src || !(amt > 0)) return;
    const cash    = findAccountByCode('1000');
    const returns = findAccountByCode('4900');
    let newRows = null;
    if (refundSourceType === 'invoice' && cash && returns) {
      // Pattern L: DR 4900, CR 1000
      newRows = [
        { id: 1, account_id: returns.id, debit: amt.toFixed(2), credit: '', description: 'Sales return / chargeback' },
        { id: 2, account_id: cash.id,    debit: '', credit: amt.toFixed(2), description: 'Cash refunded to agency' },
      ];
    } else if (refundSourceType === 'expense' && cash && src.accountId) {
      // Pattern M: DR 1000, CR 6xxx (expense account is src.accountId).
      newRows = [
        { id: 1, account_id: cash.id,        debit: amt.toFixed(2), credit: '', description: 'Vendor refund received' },
        { id: 2, account_id: src.accountId, debit: '', credit: amt.toFixed(2), description: 'Reverse expense' },
      ];
    } else if (refundSourceType === 'split' && cash && src.creatorId) {
      // Pattern N: DR 1000, CR 511x (creator payout)
      const payoutAcct = findAccountBySource('creator', src.creatorId, '511');
      if (payoutAcct) newRows = [
        { id: 1, account_id: cash.id,        debit: amt.toFixed(2), credit: '', description: 'Clawback received' },
        { id: 2, account_id: payoutAcct.id,  debit: '', credit: amt.toFixed(2), description: 'Reverse creator payout' },
      ];
    }
    if (newRows) {
      setRows(newRows);
      const srcLabel = src.label.split(' — ')[0];
      setDescription(`REFUND: ${srcLabel}`);
    }
  }, [isRefund, refundSourceType, refundSourceId, refundAmount, refundSources, findAccountByCode, findAccountBySource]);

  const totals = rows.reduce(
    (acc, r) => ({ d: acc.d + (parseFloat(r.debit) || 0), c: acc.c + (parseFloat(r.credit) || 0) }),
    { d: 0, c: 0 }
  );
  const imbalance = Math.round((totals.d - totals.c) * 100) / 100;
  const balanced = imbalance === 0 && totals.d > 0;
  const allComplete = rows.every((r) => r.account_id && (parseFloat(r.debit) > 0 || parseFloat(r.credit) > 0));

  function setRow(id, key, val) {
    setRows((rs) => rs.map((r) => r.id === id ? { ...r, [key]: val } : r));
  }
  function addRow() {
    setRows((rs) => [...rs, { id: Math.max(0, ...rs.map((x) => x.id)) + 1, account_id: '', debit: '', credit: '', description: '' }]);
  }
  function removeRow(id) {
    setRows((rs) => rs.length <= 2 ? rs : rs.filter((r) => r.id !== id));
  }

  // Refund-mode extra validation: amount must be > 0 and <= source amount; reason required.
  // The four parts are listed separately in `outstanding` below rather than folded into one
  // `refundReady` flag, which is what let "Refund incomplete" be the only thing said about
  // four different mistakes.
  const refundSrc = isRefund ? refundSources.find((s) => s.id === refundSourceId) : null;
  const refundAmt = parseFloat(refundAmount) || 0;
  const refundOverMax = isRefund && refundSrc && refundAmt > refundSrc.maxAmount + 0.005;

  /**
   * What is still standing between this entry and being posted, in the order the controls
   * appear down the modal, so the first item is also the highest thing to scroll back to.
   *
   * The button's `disabled` is this list's LENGTH. Five identifiers were gating it and two of
   * them hid four more (`refundReady` is four conditions and `allComplete` is a per-row
   * `every`), so a reader who had one thing wrong out of eight was told nothing at all. The
   * only other prose was a static sentence above the table naming two of the eight, and three
   * post-click errors restating those same two.
   */
  const outstanding = [];
  if (!description.trim()) outstanding.push({ key: 'description', label: 'Write a description' });
  if (!allComplete) outstanding.push({ key: 'lines', label: 'Give every line an account and an amount' });
  if (!balanced) {
    outstanding.push({
      key: 'balance',
      label: totals.d > 0 || totals.c > 0
        ? `Balance the entry: debits and credits are ${fmtMoney(Math.abs(imbalance))} apart`
        : 'Enter the amounts: the entry is empty',
    });
  }
  if (isRefund) {
    if (!refundSrc)       outstanding.push({ key: 'refund-src',    label: 'Pick what is being refunded' });
    if (refundAmt <= 0)   outstanding.push({ key: 'refund-amt',    label: 'Enter the refund amount' });
    if (refundOverMax)    outstanding.push({ key: 'refund-max',    label: `Lower the refund: it is more than the ${fmtMoney(refundSrc.maxAmount)} that was taken` });
    if (!refundReason.trim()) outstanding.push({ key: 'refund-why', label: 'Say why it is being refunded' });
  }

  async function handleSubmit() {
    if (entryDate < DB_DATE_MIN || entryDate > DB_DATE_MAX) {
      setError({ tone: 'error', title: 'Date out of range', body: 'Dates must be between Jan 1, 2025 and Dec 31, 2032.' }); return;
    }
    if (entryDate > today) {
      setError({ tone: 'error', title: 'Date cannot be in the future', body: 'Manual entries record events that have already happened.' }); return;
    }
    setSubmitting(true); setError('');
    const { data: { user } = {} } = await supabase.auth.getUser();

    // Header UNPOSTED first, then the lines, then post it. PostgREST gives each
    // statement its own transaction, so the header and its lines cannot be one
    // atomic write from here; what CAN be controlled is which half-written state
    // is reachable. Posting last means a failure leaves an unposted draft, which
    // is representable, visible in the GL and deletable. Posting FIRST, which is
    // what this did until could leave a POSTED entry with no lines:
    // immutable by trg_prevent_posted_je_modification, invisible to the balance
    // assertion (a sum of nothing equals a sum of nothing), and dependent on a
    // compensating delete in JavaScript that the same immutability could refuse.
    //
    // Verified against production first: zero journal entries have no lines, so
    // this window has never actually opened.
    const { data: je, error: jeErr } = await supabase
      .from('ledger_journal_entries').insert({
        entry_date: entryDate,
        description: description.trim().slice(0, 500),
        reference: reference.trim().slice(0, 200) || null,
        source_type: 'manual',
        source_id: null,
        is_posted: false,
        created_by: user?.id || null,
      }).select().single();
    if (jeErr) { setError(humanizeError(jeErr)); setSubmitting(false); return; }

    const linePayload = rows.map((r) => ({
      journal_entry_id: je.id,
      account_id: r.account_id,
      debit: parseFloat(r.debit)  || 0,
      credit: parseFloat(r.credit) || 0,
      description: r.description?.trim().slice(0, 500) || null,
    }));
    const { error: lnErr } = await supabase.from('ledger_entry_lines').insert(linePayload);
    if (lnErr) {
      // The entry is still unposted, so this delete is always permitted.
      const { error } = await mutate(supabase.from('ledger_journal_entries').delete().eq('id', je.id));
      if (error) { setSubmitting(false); toast.error(error); return; }
      setError(humanizeError(lnErr));
      setSubmitting(false);
      return;
    }

    const { error: postErr } = await supabase
      .from('ledger_journal_entries').update({ is_posted: true }).eq('id', je.id);
    if (postErr) {
      // The lines are in and balanced; only the flag failed. Leave the draft
      // rather than deleting work, and say which entry it is.
      setError(humanizeError(postErr));
      setSubmitting(false);
      return;
    }
    // `entry_created` is not an event type the CHECK allows, so this row was refused 23514 on
    // every manual entry and the refusal was thrown away with the rpc's return. P176.
    const { error: auditErr } = await supabase.rpc('write_audit_log', {
      p_event_type: 'manual_entry_created',
      p_je_id: je.id,
      p_period_id: null,
      p_reason: isRefund ? refundReason.trim() : (description.trim() || null),
      p_meta: isRefund
        ? { source: 'manual_entry_modal', purpose: 'refund', refund_source_type: refundSourceType, refund_source_id: refundSourceId, refund_amount: refundAmt }
        : { source: 'manual_entry_modal', purpose },
    });
    // The entry posted, so a failed audit row is a warning and not a rollback, which is the
    // decision PartnersView already took for a non-journal-entry event.
    if (auditErr) log('manual entry audit', auditErr);
    setSubmitting(false);
    onCreated(je.id);
  }

  return (
    <Modal
      title="NEW MANUAL ENTRY"
      size="lg"
      onClose={onClose}
      closeDisabled={submitting}
    >
        <div className="modal-body">
          <div style={{ display: 'grid', gridTemplateColumns: '160px 160px 1fr 1fr', gap: 12 }}>
            <Field label="Purpose">{(id) => (<>
              <select id={id} className="form-select" value={purpose} onChange={(e) => setPurpose(e.target.value)}>
                <option value="other">Other</option>
                <option value="correction">Correction</option>
                <option value="adjustment">Adjustment</option>
                <option value="refund">Refund</option>
                <option value="opening_balance">Opening Balance</option>
              </select>
            </>)}</Field>
            <Field label="Entry date">{(id) => (<>
              <input id={id} className="form-input" type="date" min={DB_DATE_MIN} max={today} value={entryDate} onChange={(e) => setEntryDate(e.target.value)} />
            </>)}</Field>
            <Field label="Description *">{(id) => (<>
              <input id={id} className="form-input" type="text" maxLength={500} value={description} onChange={(e) => setDescription(e.target.value)} placeholder="e.g. Opening balance, vendor refund, manual adjustment" disabled={isRefund} />
            </>)}</Field>
            <Field label="Reference">{(id) => (<>
              <input id={id} className="form-input" type="text" maxLength={200} value={reference} onChange={(e) => setReference(e.target.value)} placeholder="optional" />
            </>)}</Field>
          </div>

          {isRefund ? (
            <div style={{ marginTop: 4, marginBottom: 12, padding: 12, background: 'color-mix(in oklab, var(--orange) 6%, transparent)', borderLeft: '3px solid var(--orange)', borderRadius: 4 }}>
              <div style={{ fontSize: 11, fontWeight: 700, color: 'var(--orange)', textTransform: 'uppercase', letterSpacing: 1, marginBottom: 8 }}>Refund details</div>
              <div style={{ display: 'grid', gridTemplateColumns: '180px 1fr 140px', gap: 12 }}>
                <Field label="Source type">{(id) => (<>
                  <select id={id} className="form-select" value={refundSourceType} onChange={(e) => setRefundSourceType(e.target.value)}>
                    <option value="invoice">Invoice (Pattern L)</option>
                    <option value="expense">Expense (Pattern M)</option>
                    <option value="split">Cleared payout split (Pattern N)</option>
                  </select>
                </>)}</Field>
                <Field label="Source *">{(id) => (<>
                  <select id={id} className="form-select" value={refundSourceId} onChange={(e) => setRefundSourceId(e.target.value)} disabled={loadingSources}>
                    <option value="">{loadingSources ? 'Loading…' : sourcesErr ? 'Could not load' : ': Select -'}</option>
                    {refundSources.map((s) => (
                      <option key={s.id} value={s.id}>{s.label}</option>
                    ))}
                  </select>
                </>)}</Field>
                <Field label="Refund amount *">{(id) => (<>
                  <MoneyInput id={id} min="0" value={refundAmount} onChange={(e) => setRefundAmount(e.target.value)} style={{ textAlign: 'right' }} />
                  {refundOverMax ? (
                    <div style={{ fontSize: 11, color: 'var(--red)', marginTop: 4 }}>Exceeds source amount {fmtMoney(refundSrc?.maxAmount)}</div>
                  ) : null}
                </>)}</Field>
              </div>
              <Field label={<>Reason * <span style={{ color: 'var(--muted)', fontWeight: 400 }}>(written to audit log)</span></>} style={{ marginTop: 8 }}>{(id) => (<>
                <textarea id={id} className="form-textarea" maxLength={1000} rows={2} value={refundReason} onChange={(e) => setRefundReason(e.target.value)} placeholder="Why is this refund being issued?" />
              </>)}</Field>
            </div>
          ) : null}

          <div style={{ marginTop: 8, marginBottom: 12, color: 'var(--muted)', fontSize: 12 }}>
            Build the entry line by line.
          </div>

          <div className="table-wrap" style={{ marginBottom: 12 }}>
            <table className="pinned-actions" style={{ width: '100%' }}>
              <thead>
                <tr>
                  <th scope="col">Account</th>
                  <th scope="col" style={{ width: 110, textAlign: 'right' }}>Debit ($)</th>
                  <th scope="col" style={{ width: 110, textAlign: 'right' }}>Credit ($)</th>
                  <th scope="col">Note</th>
                  <th scope="col" style={{ width: 32 }}></th>
                </tr>
              </thead>
              <tbody>
                {rows.map((r) => (
                  <tr key={r.id}>
                    <td>
                      <select className="form-select" aria-label="Account for this line" value={r.account_id} onChange={(e) => setRow(r.id, 'account_id', e.target.value)} disabled={isRefund}>
                        <option value="">Select…</option>
                        {accounts.filter((a) => a.is_active !== false).map((a) => (
                          <option key={a.id} value={a.id}>{a.code} · {a.name}</option>
                        ))}
                      </select>
                    </td>
                    <td><MoneyInput min="0" aria-label="Debit for this line"  value={r.debit}  onChange={(e) => setRow(r.id, 'debit',  e.target.value)} style={{ textAlign: 'right' }} disabled={isRefund} /></td>
                    <td><MoneyInput min="0" aria-label="Credit for this line" value={r.credit} onChange={(e) => setRow(r.id, 'credit', e.target.value)} style={{ textAlign: 'right' }} disabled={isRefund} /></td>
                    <td><input className="form-input" type="text" aria-label="Note for this line" maxLength={500} value={r.description} onChange={(e) => setRow(r.id, 'description', e.target.value)} disabled={isRefund} /></td>
                    <td><button className="btn btn-ghost btn-icon" onClick={() => removeRow(r.id)} aria-label="Remove this line" disabled={isRefund || rows.length <= 2}>✕</button></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <button className="btn btn-ghost btn-sm" onClick={addRow} disabled={isRefund}>+ Add line</button>
            <div style={{ display: 'flex', gap: 16, fontSize: 12 }}>
              <span style={{ color: 'var(--muted)' }}>Debits: <strong style={{ color: 'var(--white)', fontVariantNumeric: 'tabular-nums' }}>{fmtMoney(totals.d)}</strong></span>
              <span style={{ color: 'var(--muted)' }}>Credits: <strong style={{ color: 'var(--white)', fontVariantNumeric: 'tabular-nums' }}>{fmtMoney(totals.c)}</strong></span>
              <span style={{ color: balanced ? 'var(--green)' : 'var(--red)', fontWeight: 700 }}>
                {balanced ? 'BALANCED ✓' : `OUT OF BALANCE ${fmtMoney(Math.abs(imbalance))}`}
              </span>
            </div>
          </div>

          {error ? <Feedback value={error} /> : null}

          {/* Immediately above the footer, which is the adjacency MobilePostPage established
              and the whole reason its version reads. */}
          <OutstandingList items={outstanding} heading="Before you can post this" style={{ marginTop: 16 }} />
        </div>
        <div className="modal-footer">
          <ModalClose className="btn btn-ghost" disabled={submitting}>Cancel</ModalClose>
          <button className="btn btn-primary" onClick={handleSubmit} disabled={submitting || outstanding.length > 0}>
            {submitting ? 'Posting…' : (isRefund ? 'Post refund' : 'Post entry')}
          </button>
        </div>
    </Modal>
  );
}

/**
 * Column-header info dot with a hover/focus tooltip. Used on the Debit/Credit
 * headers to expose the plain-English Increases/Decreases convention inline.
 */
function ColHeaderInfo({ title, rows, foot }) {
  const [hover, setHover] = React.useState(false);
  return (
    <span
      style={{ position: 'relative', display: 'inline-flex' }}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
    >
      <span
        className="gl-th-info"
        role="img"
        aria-label={title}
        tabIndex={0}
        onFocus={() => setHover(true)}
        onBlur={() => setHover(false)}
        onClick={(ev) => ev.stopPropagation()}
      >?</span>
      {hover ? (
        <span role="tooltip" className="gl-th-info-tooltip">
          <span className="gl-th-info-tip-title">{title}</span>
          <span className="gl-th-info-tip-rule" aria-hidden="true" />
          {rows.map((r, i) => <span key={i} className="gl-th-info-tip-row">{r}</span>)}
          {foot ? <span className="gl-th-info-tip-foot">{foot}</span> : null}
        </span>
      ) : null}
    </span>
  );
}

/**
 * Expanded body for one GL row: line detail, balance-check footer, audit
 * history, the reversal cross-reference banner, and (admin) the Reverse button.
 *
 * @gotcha Reverse is disabled when the entry is already reversed, is itself a
 *         reversal, or sits in a locked period; posted JEs are immutable, so
 *         corrections only ever go through reverse_journal_entry.
 * @see docs/MONEY.md (reversal mechanism)
 */
function ExpandedEntry({ entry, lines, totals, audit, isAdmin, onReverse, reversingEntry, originalEntry, onJumpToEntry }) {
  const isReversed = !!entry.reversed_by_je_id;
  const isReversal = isReversalEntry(entry);
  const reverseDisabled = isReversed || isReversal || entry.is_locked;
  const balanced = totals ? Math.abs(totals.d - totals.c) < 0.005 : true;
  return (
    <div>
      {/* Reversal cross-reference banner */}
      {(reversingEntry || originalEntry) ? (
        <div style={{
          marginBottom: 12,
          padding: '8px 10px',
          fontSize: 12,
          color: 'var(--muted)',
          background: 'rgba(255,255,255,0.03)',
          border: '1px solid rgba(255,255,255,0.06)',
          borderRadius: 4,
        }}>
          {reversingEntry ? (
            <>
              Reversed by <strong style={{ color: 'var(--white)' }}>{reversingEntry.description}</strong> on {fmtDate(reversingEntry.entry_date)}
              {onJumpToEntry ? (
                <button className="gl-xref-link" onClick={() => onJumpToEntry(reversingEntry.id)}>Jump to reversal →</button>
              ) : null}
            </>
          ) : null}
          {originalEntry ? (
            <>
              This entry reverses <strong style={{ color: 'var(--white)' }}>{originalEntry.description}</strong> from {fmtDate(originalEntry.entry_date)}
              {onJumpToEntry ? (
                <button className="gl-xref-link" onClick={() => onJumpToEntry(originalEntry.id)}>Jump to original →</button>
              ) : null}
            </>
          ) : null}
        </div>
      ) : null}

      <div style={{ marginBottom: 12, fontSize: 11, color: 'var(--muted)', textTransform: 'uppercase', letterSpacing: 1 }}>Lines</div>
      <table style={{ width: '100%', fontSize: 12 }}>
        <thead>
          <tr style={{ color: 'var(--muted)' }}>
            <th scope="col">Account</th>
            <th scope="col">Note</th>
            <th scope="col" style={{ textAlign: 'right' }}>Debit</th>
            <th scope="col" style={{ textAlign: 'right' }}>Credit</th>
          </tr>
        </thead>
        <tbody>
          {lines.map((l) => (
            <tr key={l.id}>
              <td>{[l.account_code, l.account_name].filter(Boolean).join('  ')}</td>
              <td style={{ color: 'var(--muted)' }}>{l.description || ''}</td>
              <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{Number(l.debit) > 0 ? fmtMoney(l.debit) : ''}</td>
              <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{Number(l.credit) > 0 ? fmtMoney(l.credit) : ''}</td>
            </tr>
          ))}
        </tbody>
      </table>

      {/* Balance check footer. Teaches the double-entry invariant in passing. */}
      {totals ? (
        <div className="gl-balance-footer">
          <span><span className="gl-balance-label">Debit total</span>{fmtMoney(totals.d)}</span>
          <span><span className="gl-balance-label">Credit total</span>{fmtMoney(totals.c)}</span>
          <span className={balanced ? 'gl-balance-ok' : 'gl-balance-bad'}>
            {balanced ? '✓ Balanced' : `Out of balance: ${fmtMoney(Math.abs(totals.d - totals.c))}`}
          </span>
        </div>
      ) : null}

      {audit && audit.length > 0 ? (
        <div style={{ marginTop: 16 }}>
          <div style={{ marginBottom: 8, fontSize: 11, color: 'var(--muted)', textTransform: 'uppercase', letterSpacing: 1 }}>History</div>
          <ul style={{ margin: 0, paddingLeft: 16, fontSize: 12, color: 'var(--muted)' }}>
            {audit.map((a) => (
              <li key={a.id}>
                {fmtDate(a.created_at)} · <strong>{a.event_type}</strong>
                {a.reason ? `. ${a.reason}` : ''}
              </li>
            ))}
          </ul>
        </div>
      ) : null}

      {isAdmin ? (
        <div style={{ marginTop: 16, display: 'flex', justifyContent: 'flex-end', gap: 8, alignItems: 'center' }}>
          {reverseDisabled ? (
            // The reason, as text. It was a `title` on a disabled button, which most engines
            // never show and no keyboard or touch user can reach.
            <span style={{ fontSize: 11, color: 'var(--muted)' }}>
              {isReversed ? 'Already reversed' : entry.is_locked ? 'Period locked' : 'This entry is itself a reversal'}
            </span>
          ) : (
            <button className="btn btn-danger btn-sm" onClick={onReverse}>Reverse this entry</button>
          )}
        </div>
      ) : null}
    </div>
  );
}

/**
 * Chart of Accounts tab: account list grouped by type with computed balances
 * and (admin) inline CRUD for custom 6xxx expense accounts.
 *
 * @gotcha balances filter out lines whose JE was reversed, so this tab ties to
 *         Trial Balance / P&L / Balance Sheet (an unfiltered sum would disagree
 *         after a reversal).
 * @gotcha only non-system 6xxx expense accounts are editable; delete is blocked
 *         while the account is referenced by an expense or carries journal lines
 *         (deactivate instead). New codes auto-pick the next free slot below 6900
 *         (6900 is the system processing-fee account).
 */
function ChartOfAccountsTab({ accounts, isAdmin, onAccountsChanged, onNavigateToPaymentSetup }) {
  const askConfirm = useConfirm();
  const [showInactive, setShowInactive] = useState(false);
  const [balances, setBalances] = useState({});
  const [usageCounts, setUsageCounts] = useState({}); // 6xxx -> # expenses referencing
  const { loading, refreshing, begin, end } = useLoadState();
  const [readError, setReadError] = useState(null);
  // Bumped by the retry to re-run the effect on the same accounts.
  const [attempt, setAttempt] = useState(0);
  const [editingId, setEditingId] = useState(null);
  const [editName, setEditName] = useState('');
  const [saving, setSaving] = useState(false);
  const [adding, setAdding] = useState(false);
  const [newName, setNewName] = useState('');
  const [error, setError] = useState('');

  // Every write here calls `onAccountsChanged`, which hands down a new `accounts` array and
  // re-runs this, so it is a refetch after a write like any other and may not blank the tab.
  useEffect(() => {
    let alive = true;
    (async () => {
      begin();
      setReadError(null);
      const [linesRes, expRes] = await Promise.all([
        // Filter out lines whose JE was reversed so COA balances match Trial Balance / P&L / BS.
        // Schema agent flagged this: unfiltered COA could disagree with TB after a reversal.
        // Paged, not limited: PostgREST caps a response at 1,000 rows, so this
        // summed 1,000 of the 1,289 live lines and the balance column disagreed
        // with the Trial Balance (which reads through useAllLines and was
        // complete) with nothing on either screen saying so. @see utils/fetchAllRows.js
        fetchAllRows(() => supabase.from('ledger_entry_lines').select('id, account_id, debit, credit, journal_entry_id, journal_entry:ledger_journal_entries!inner(reversed_by_je_id)').is('journal_entry.reversed_by_je_id', null).order('id'))
          .then((data) => ({ data, error: null }), (error) => ({ data: null, error })),
        // Paged for the same reason the lines read above is: this count is half the Delete
        // gate, so an account whose references all fall past the 1,000-row cap reads as
        // unused and offers the control. @see utils/fetchAllRows.js
        fetchAllRows(() => supabase.from('expenses').select('category_id').order('id'))
          .then((data) => ({ data, error: null }), (error) => ({ data: null, error })),
      ]);
      if (!alive) return;
      // @gotcha BOTH halves of the Delete gate are read here, and a refusal opens both at
      //         once: `balances[a.id] || 0` is 0 when the lines read failed and
      //         `usageCounts[a.id] || 0` is 0 when the expenses read failed, so an account
      //         carrying journal lines and in use by expenses offers Delete and reads
      //         $0.00. A failed probe must lock, never unlock, so either error fails the
      //         tab. @see components/shared/ReadError.js
      const readErr = linesRes.error || expRes.error;
      if (readErr) {
        log('lines for COA', readErr);
        setBalances({});
        setUsageCounts({});
        setReadError(readErr);
        end();
        return;
      }
      const map = new Map();
      for (const l of linesRes.data || []) {
        const a = accounts.find((x) => x.id === l.account_id);
        if (!a) continue;
        const cur = map.get(l.account_id) || { d: 0, c: 0, normal: a.normal_balance };
        cur.d += Number(l.debit  || 0);
        cur.c += Number(l.credit || 0);
        map.set(l.account_id, cur);
      }
      const out = {};
      for (const [id, v] of map.entries()) {
        out[id] = v.normal === 'credit' ? v.c - v.d : v.d - v.c;
      }
      setBalances(out);
      const uc = {};
      for (const e of expRes.data || []) {
        if (!e.category_id) continue;
        uc[e.category_id] = (uc[e.category_id] || 0) + 1;
      }
      setUsageCounts(uc);
      end();
    })();
    return () => { alive = false; };
  }, [accounts, attempt, begin, end]);

  const visible = useMemo(() => accounts.filter((a) => showInactive || a.is_active !== false), [accounts, showInactive]);

  function handleExportCsv() {
    downloadString(`chart-of-accounts-${todayYMD()}.csv`, formatChartOfAccountsCsv(accounts));
  }

  // Editable when admin, non-system, expense (6xxx) account.
  const canEdit = (a) => isAdmin && !a.is_system && a.type === 'expense';

  const handleSaveName = async (a) => {
    const n = editName.trim();
    if (!n || n === a.name) { setEditingId(null); return; }
    setSaving(true);
    setError('');
    const { error: e } = await supabase.from('ledger_accounts').update({ name: n }).eq('id', a.id);
    setSaving(false);
    if (e) { setError(humanizeError(e)); return; }
    setEditingId(null);
    onAccountsChanged?.();
  };

  const handleToggleActive = async (a) => {
    setError('');
    const { error: e } = await supabase.from('ledger_accounts').update({ is_active: !a.is_active }).eq('id', a.id);
    if (e) { setError(humanizeError(e)); return; }
    onAccountsChanged?.();
  };

  const handleDelete = async (a) => {
    if (!(await askConfirm({ title: `Delete "${a.code} ${a.name}"?`, body: 'This cannot be undone.', danger: true }))) return;
    setError('');
    const { error: e } = await supabase.from('ledger_accounts').delete().eq('id', a.id);
    if (e) { setError(humanizeError(e)); return; }
    onAccountsChanged?.();
  };

  // Next 6xxx code: largest existing 6xxx (excluding system 6900) plus 10.
  const nextExpenseCode = () => {
    const codes = accounts
      .filter((a) => a.type === 'expense' && /^6\d{3}$/.test(a.code) && !a.is_system)
      .map((a) => parseInt(a.code, 10))
      .filter((n) => !Number.isNaN(n));
    const max = codes.length ? Math.max(...codes) : 6000;
    let next = max + 10;
    // Keep below 6900 (system) and unique
    const all = new Set(accounts.map((a) => a.code));
    while (next >= 6900 || all.has(String(next))) {
      next += 10;
      if (next > 6890) break;
    }
    return String(next);
  };

  const handleAddExpense = async () => {
    const n = newName.trim();
    if (!n) return;
    const code = nextExpenseCode();
    if (parseInt(code, 10) >= 6900) {
      setError('No available expense account code below 6900. Reuse an inactive code or pick a different range.');
      return;
    }
    setError('');
    const { error: e } = await supabase.from('ledger_accounts').insert({
      code, name: n, type: 'expense', normal_balance: 'debit', is_system: false, is_active: true,
    });
    if (e) { setError(humanizeError(e)); return; }
    setNewName('');
    setAdding(false);
    onAccountsChanged?.();
  };

  return (
    <>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16, flexWrap: 'wrap', gap: 8 }}>
        <label style={{ display: 'flex', gap: 6, alignItems: 'center', minHeight: 24, fontSize: 12, color: 'var(--muted)' }}>
          <input type="checkbox" checked={showInactive} onChange={(e) => setShowInactive(e.target.checked)} />
          Show inactive accounts
        </label>
        <button className="btn btn-ghost btn-sm" onClick={handleExportCsv}>Export CSV</button>
      </div>

      {error ? <Feedback value={error} style={{ marginBottom: 12 }} /> : null}

      <Refreshing on={refreshing} />
      {loading ? <Loading>Loading balances…</Loading> : readError ? (
        <ReadError error={readError} onRetry={() => setAttempt((n) => n + 1)} />
      ) : (
        Object.keys(ACCOUNT_TYPE_LABEL).map((type) => {
          const rows = visible.filter((a) => a.type === type);
          if (rows.length === 0 && type !== 'expense') return null;
          return (
            <div key={type} style={{ marginBottom: 24 }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '6px 0', borderBottom: '1px solid var(--border)', marginBottom: 6 }}>
                <div style={{ fontSize: 11, color: 'var(--orange)', textTransform: 'uppercase', letterSpacing: 1.5 }}>{ACCOUNT_TYPE_LABEL[type]}</div>
                {type === 'expense' && isAdmin ? (
                  adding ? (
                    <div style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
                      <input className="form-input" autoFocus value={newName} onChange={(e) => setNewName(e.target.value)}
                        onKeyDown={(e) => e.key === 'Enter' && handleAddExpense()}
                        aria-label="New expense account name"
                        placeholder="Account name" maxLength={120}
                        style={{ width: 220, padding: '4px 8px', fontSize: 12 }} />
                      <button className="btn btn-primary btn-sm" onClick={handleAddExpense} disabled={!newName.trim()}>Add</button>
                      <button className="btn btn-ghost btn-sm" onClick={() => { setAdding(false); setNewName(''); }}>Cancel</button>
                    </div>
                  ) : (
                    <button className="btn btn-ghost btn-sm" onClick={() => setAdding(true)}>+ New expense account</button>
                  )
                ) : null}
              </div>
              <table className="pinned-actions" style={{ width: '100%' }}>
                <thead>
                  <tr>
                    <th scope="col" style={{ width: 80 }}>Code</th>
                    <th scope="col">Name</th>
                    <th scope="col" style={{ width: 140, textAlign: 'right' }}>Balance</th>
                    <th scope="col" style={{ width: 160, whiteSpace: 'nowrap' }}>Source</th>
                    {type === 'expense' && isAdmin ? <th scope="col" style={{ width: 220, textAlign: 'right' }}></th> : null}
                  </tr>
                </thead>
                <tbody>
                  {rows.map((a) => {
                    const editable = canEdit(a);
                    const isEditing = editingId === a.id;
                    const refs = usageCounts[a.id] || 0;
                    const balanceNonZero = Number(balances[a.id] || 0) !== 0;
                    // Named once and used as both the tooltip and the accessible name: the
                    // button's only child is an aria-hidden lock glyph, so without the name
                    // the reason it is dead exists nowhere a reader can reach.
                    const deleteReason = refs > 0
                      ? `In use by ${refs} expense${refs === 1 ? '' : 's'}: deactivate instead`
                      : balanceNonZero
                      ? 'Has journal lines: deactivate instead'
                      : `Delete ${a.code} ${a.name}`;
                    return (
                      <tr key={a.id} style={{ opacity: a.is_active === false ? 0.55 : 1 }}>
                        <td style={{ fontVariantNumeric: 'tabular-nums' }}>{a.code}</td>
                        <td>
                          {isEditing ? (
                            <input
                              className="form-input" autoFocus value={editName}
                              aria-label={`Rename account ${a.code} ${a.name}`}
                              onChange={(e) => setEditName(e.target.value)}
                              onKeyDown={(e) => {
                                if (e.key === 'Enter') handleSaveName(a);
                                if (e.key === 'Escape') setEditingId(null);
                              }}
                              maxLength={120}
                              style={{ width: '100%', padding: '4px 8px', fontSize: 12 }}
                            />
                          ) : (
                            <>
                              {a.name}
                              {type === 'expense' && refs > 0 ? (
                                <span style={{ marginLeft: 8, fontSize: 11, color: 'var(--muted)' }}>· {refs} active</span>
                              ) : null}
                              {a.is_active === false ? <span style={{ marginLeft: 8, fontSize: 11, color: 'var(--dim)' }}>inactive</span> : null}
                            </>
                          )}
                        </td>
                        <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{fmtMoney(balances[a.id] || 0)}</td>
                        <td style={{ whiteSpace: 'nowrap' }}>
                          <span style={{ fontSize: 11, color: 'var(--muted)', display: 'inline-flex', alignItems: 'center', gap: 4 }}>
                            {a.is_system ? <><LockIcon size={11} /> System</> : (a.source_type || 'custom')}
                            {a.source_type === 'destination' && onNavigateToPaymentSetup ? (
                              <>
                                {' · '}
                                <button
                                  type="button"
                                  onClick={onNavigateToPaymentSetup}
                                  title="Open this destination in Payment Setup"
                                  style={{
                                    background: 'none', border: 'none', padding: 0, cursor: 'pointer',
                                    color: 'var(--blue)', fontSize: 11, fontFamily: 'inherit',
                                  }}
                                >→ Setup</button>
                              </>
                            ) : null}
                          </span>
                        </td>
                        {type === 'expense' && isAdmin ? (
                          <td style={{ textAlign: 'right' }}>
                            {isEditing ? (
                              <div style={{ display: 'flex', gap: 6, justifyContent: 'flex-end' }}>
                                <button className="btn btn-primary btn-sm" onClick={() => handleSaveName(a)} disabled={saving}>Save</button>
                                <button className="btn btn-ghost btn-sm" onClick={() => setEditingId(null)}>Cancel</button>
                              </div>
                            ) : editable ? (
                              <div style={{ display: 'flex', gap: 6, justifyContent: 'flex-end' }}>
                                <button className="btn btn-ghost btn-sm" onClick={() => { setEditingId(a.id); setEditName(a.name); }}>Rename</button>
                                <button className="btn btn-ghost btn-sm" onClick={() => handleToggleActive(a)}>
                                  {a.is_active === false ? 'Activate' : 'Deactivate'}
                                </button>
                                <button
                                  onClick={() => handleDelete(a)}
                                  disabled={refs > 0 || balanceNonZero}
                                  aria-label={deleteReason}
                                  title={deleteReason}
                                  style={{
                                    background: 'none', border: 'none',
                                    cursor: (refs > 0 || balanceNonZero) ? 'not-allowed' : 'pointer',
                                    color: (refs > 0 || balanceNonZero) ? 'var(--dim)' : 'var(--red)',
                                    fontSize: 13, padding: '3px 6px', fontFamily: 'inherit',
                                  }}
                                >
                                  {(refs > 0 || balanceNonZero) ? <LockIcon size={12} /> : '✕'}
                                </button>
                              </div>
                            ) : null}
                          </td>
                        ) : null}
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          );
        })
      )}
    </>
  );
}

/**
 * Read-friendly labels for ledger_audit_log.event_type values (History tab).
 * @invariant these keys ARE the values `ledger_audit_log_event_type_check` allows, and a test
 *            reads that CHECK to hold them there. A key outside it is a filter option nothing
 *            can match; a value with no key renders raw and cannot be filtered for.
 *            @see schemas/SCHEMA.sql
 */
const EVENT_LABELS = {
  manual_entry_created: 'Manual Entry',
  entry_reversed: 'Reversal',
  period_closed: 'Period Close',
  period_relocked: 'Period Re-lock',
  period_unlocked: 'Period Unlock',
  partner_allocation_changed: 'Allocation Change',
  reconciliation_completed: 'Reconciliation',
  system_backfill: 'Backfill',
  campaign_cancelled: 'Campaign Cancelled',
  filing_status_changed: 'Tax Filing',
};

/** History tab: read-only filterable view of the append-only ledger_audit_log. */
function HistoryTab() {
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo,   setDateTo]   = useState('');
  const [eventType, setEventType] = useState('all');
  const [rows, setRows] = useState([]);
  const [loading, setLoading] = useState(true);
  const [readError, setReadError] = useState(null);
  const [pageCount, setPageCount] = useState(1);
  const filtersDirty = !!dateFrom || !!dateTo || eventType !== 'all';
  // @invariant a reversed range is named, never answered. Same shape as the General Ledger
  //            filter above, and it matters more here: an audit log emptied by its own range
  //            reads as proof that no reversal, close or reconciliation ever happened.
  const rangeReversed = !!dateFrom && !!dateTo && dateTo < dateFrom;
  function clearAllFilters() { setDateFrom(''); setDateTo(''); setEventType('all'); }

  const fetchAll = useCallback(async () => {
    setLoading(true);
    setReadError(null);
    // Paged, not capped. `.limit(500)` on an append-only log ended the tab whose whole
    // purpose is completeness, with nothing on screen saying it had. The tiebreak is
    // mandatory: created_at is not unique. @see .claude/rules/hub-data.md
    let q = supabase.from('ledger_audit_log').select('*')
      .order('created_at', { ascending: false }).order('id')
      .limit(PAGE_SIZE * pageCount);
    if (dateFrom) q = q.gte('created_at', dateFrom);
    if (dateTo)   q = q.lte('created_at', `${dateTo}T23:59:59`);
    if (eventType !== 'all') q = q.eq('event_type', eventType);
    const { data, error } = await q;
    // A period unlock, a reversal or a reconciliation that IS recorded read as never having
    // happened, on the one screen whose job is to prove it did.
    if (error) { log('history', error); setReadError(error); setRows([]); setLoading(false); return; }
    setRows(data || []);
    setLoading(false);
  }, [dateFrom, dateTo, eventType, pageCount]);

  useEffect(() => { fetchAll(); }, [fetchAll]);
  // A filter change starts the paging over; without this a narrowed filter keeps the wider
  // page size and the Load more control counts against the wrong set.
  useEffect(() => { setPageCount(1); }, [dateFrom, dateTo, eventType]);

  return (
    <>
      <div className="card" style={{ marginBottom: 16, padding: 16 }}>
        <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap', alignItems: 'flex-end' }}>
          <Field label="From" style={{ marginBottom: 0 }}>{(id) => (<>
            <input id={id} className="form-input" type="date" min={DB_DATE_MIN} max={DB_DATE_MAX} value={dateFrom} onChange={(e) => setDateFrom(e.target.value)} style={{ width: 150 }} />
          </>)}</Field>
          <Field label="To" style={{ marginBottom: 0 }}>{(id) => (<>
            <input id={id} className="form-input" type="date" min={dateFrom || DB_DATE_MIN} max={DB_DATE_MAX} value={dateTo} onChange={(e) => setDateTo(e.target.value)} style={{ width: 150 }} />
          </>)}</Field>
          <Field label="Event type" style={{ marginBottom: 0, flex: 1, minWidth: 180 }}>{(id) => (<>
            <select id={id} className="form-select" value={eventType} onChange={(e) => setEventType(e.target.value)}>
              <option value="all">All</option>
              {Object.entries(EVENT_LABELS).map(([k, v]) => <option key={k} value={k}>{v}</option>)}
            </select>
          </>)}</Field>
        </div>
      </div>

      {loading ? <Loading /> : readError ? (
        <ReadError error={readError} onRetry={fetchAll} />
      ) : (
        rangeReversed ? (
          <EmptyState
            title="The To date is before the From date."
            text={`Set To on or after ${fmtDate(dateFrom)} to see what was recorded in that range.`}
            action={<button className="btn btn-ghost btn-sm" onClick={clearAllFilters}>Clear filters</button>} />
        ) : rows.length === 0 ? (
          <EmptyState
            title={filtersDirty ? 'No audit-log entries match these filters.' : 'Nothing has been recorded yet. Reversals, period closes and reconciliations appear here as they happen.'}
            action={filtersDirty
              ? <button className="btn btn-ghost btn-sm" onClick={clearAllFilters}>Clear filters</button>
              : null} />
        ) : (
          <div className="table-wrap">
            <table style={{ width: '100%' }}>
              <thead>
                <tr>
                  <th scope="col" style={{ width: 170 }}>Timestamp</th>
                  <th scope="col" style={{ width: 140 }}>Event</th>
                  <th scope="col">Reason / Context</th>
                  <th scope="col" style={{ width: 230 }}>Reference</th>
                </tr>
              </thead>
              <tbody>
                {rows.map((r) => (
                  <tr key={r.id}>
                    <td style={{ fontVariantNumeric: 'tabular-nums', fontSize: 11 }}>{new Date(r.created_at).toLocaleString()}</td>
                    <td><span className="badge" style={{ background: 'var(--orange-glow)', color: 'var(--orange)' }}>{EVENT_LABELS[r.event_type] || r.event_type}</span></td>
                    <td style={{ color: r.reason ? undefined : 'var(--muted)' }}>{r.reason || '—'}</td>
                    <td style={{ fontSize: 11, color: 'var(--muted)' }}>
                      {r.journal_entry_id ? `JE ${r.journal_entry_id.slice(0, 8)}…` : ''}
                      {r.period_id ? ` · period ${r.period_id.slice(0, 8)}…` : ''}
                      {r.meta && Object.keys(r.meta).length ? ` · ${Object.entries(r.meta).map(([k, v]) => `${k}=${typeof v === 'object' ? JSON.stringify(v) : v}`).join(', ')}` : ''}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
            {rows.length === PAGE_SIZE * pageCount ? (
              <div style={{ textAlign: 'center', padding: 12 }}>
                <button className="btn btn-secondary btn-sm" onClick={() => setPageCount((n) => n + 1)}>Load more</button>
              </div>
            ) : null}
          </div>
        )
      )}
    </>
  );
}

/**
 * Trial Balance tab: per-account debit/credit columns as of a date, grouped by
 * type, flagging abnormal-side balances. Totals must tie (debits == credits).
 * Lines come pre-filtered via useAllLines.
 */
function TrialBalanceTab({ accounts }) {
  // todayYMD, never toISOString: the UTC date is tomorrow after 8pm in New York, and an
  // as-of date one day out silently includes tomorrow's entries.
  const [asOf, setAsOf] = useState(todayYMD);
  const [includeZero, setIncludeZero] = useState(false);
  const { lines, loading, error, reload } = useAllLines(asOf);
  const tb = useMemo(() => buildTrialBalance(accounts, lines, asOf, { includeZero }), [accounts, lines, asOf, includeZero]);

  if (loading) return <Loading />;
  if (error) return <ReadError error={error} onRetry={reload} />;

  return (
    <>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', flexWrap: 'wrap', gap: 12, marginBottom: 16 }}>
        <div style={{ display: 'flex', gap: 12, alignItems: 'flex-end' }}>
          <Field label="As of" style={{ marginBottom: 0 }}>{(id) => (<>
            <input id={id} className="form-input" type="date" min={DB_DATE_MIN} max={DB_DATE_MAX} value={asOf} onChange={(e) => setAsOf(e.target.value)} style={{ width: 160 }} />
          </>)}</Field>
          <label style={{ display: 'flex', gap: 6, alignItems: 'center', minHeight: 24, fontSize: 12, color: 'var(--muted)', paddingBottom: 8 }}>
            <input type="checkbox" checked={includeZero} onChange={(e) => setIncludeZero(e.target.checked)} />
            Show $0 accounts
          </label>
        </div>
        <button className="btn btn-ghost btn-sm" onClick={async () => {
          const m = await import('../../utils/ledgerPdf');
          await m.downloadTrialBalancePdf(tb, asOf, null, `trial-balance-${asOf}.pdf`);
        }}>Export PDF</button>
      </div>

      <div className="table-wrap">
        <table style={{ width: '100%' }}>
          <thead>
            <tr>
              <th scope="col" style={{ width: 80 }}>Code</th>
              <th scope="col">Name</th>
              <th scope="col" style={{ width: 130, textAlign: 'right' }}>Debit</th>
              <th scope="col" style={{ width: 130, textAlign: 'right' }}>Credit</th>
            </tr>
          </thead>
          <tbody>
            {tb.groups.map((g) => (
              <React.Fragment key={g.type}>
                <tr><td colSpan={4} style={{ background: 'var(--surface2)', color: 'var(--orange)', fontSize: 11, textTransform: 'uppercase', letterSpacing: 1.5, padding: '8px 16px' }}>{ACCOUNT_TYPE_LABEL[g.type] || g.type}</td></tr>
                {g.rows.map((r) => (
                  <tr key={r.account.id}>
                    <td style={{ fontVariantNumeric: 'tabular-nums' }}>{r.account.code}</td>
                    <td>
                      {r.account.name}
                      {r.isAbnormal ? <span style={{ marginLeft: 6, color: 'var(--orange)', display: 'inline-flex', verticalAlign: 'middle' }} title="Abnormal balance"><WarningIcon size={12} title="Abnormal balance" /></span> : null}
                    </td>
                    <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', color: r.isAbnormal && r.account.normal_balance === 'credit' ? 'var(--orange)' : undefined }}>
                      {r.debit > 0 ? fmtMoney(r.debit) : ''}
                    </td>
                    <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums', color: r.isAbnormal && r.account.normal_balance === 'debit' ? 'var(--orange)' : undefined }}>
                      {r.credit > 0 ? fmtMoney(r.credit) : ''}
                    </td>
                  </tr>
                ))}
              </React.Fragment>
            ))}
            <tr style={{ borderTop: '2px solid var(--border)', fontWeight: 700 }}>
              <td colSpan={2}>TOTALS</td>
              <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{fmtMoney(tb.totalDebit)}</td>
              <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{fmtMoney(tb.totalCredit)}</td>
            </tr>
          </tbody>
        </table>
      </div>

      <div style={{ marginTop: 18, textAlign: 'center', fontFamily: 'var(--font-display)', fontSize: 18, color: tb.isBalanced ? 'var(--green)' : 'var(--red)' }}>
        {tb.isBalanced ? 'BALANCED ✓' : `OUT OF BALANCE: ${fmtMoney(Math.abs(tb.imbalance))}`}
      </div>
    </>
  );
}

/**
 * P&L Report tab: revenue, cost of revenue, gross profit, operating expenses,
 * net income over a date range, plus (admin) the fiscal-year lifecycle controls.
 *
 * @gotcha Close / Lock / Unlock FY only surface for a full prior-year range (Jan 1
 *         to Dec 31 of a year before the current one). Close posts the year-end
 *         allocation entry and cannot be undone without an admin unlock.
 * @gotcha that close entry is dropped HERE and not in useAllLines: the Trial
 *         Balance and Balance Sheet share that hook and both want it kept.
 *         @see excludeYearEndCloseLines in utils/ledger.js
 * @see docs/MONEY.md Pattern K (fiscal year close)
 */
function PLReportTab({ accounts, isAdmin }) {
  const askConfirm = useConfirm();
  const toast = useToast();
  const today = new Date();
  const [yearStart, setYearStart] = useState(`${today.getFullYear()}-01-01`);
  // todayYMD, never toISOString: the latter is the UTC date, which after 8pm in New York is
  // tomorrow, so the P&L quietly reported a year that has not ended yet.
  const [yearEnd,   setYearEnd]   = useState(todayYMD());
  const [customOpen, setCustomOpen] = useState(false);
  const { entries, lines, loading, error, reload } = useAllLines(yearEnd || '');

  const filteredLines = useMemo(
    () => excludeYearEndCloseLines(entries, lines)
      .filter((l) => l.entry_date && (!yearStart || l.entry_date >= yearStart)),
    [entries, lines, yearStart],
  );
  const pl = useMemo(() => buildPLReport(accounts, filteredLines), [accounts, filteredLines]);
  // Counted off the lines the report was computed from, never off the raw
  // entry list: that list is everything up to yearEnd, so it ignores yearStart
  // entirely and still holds the close entry the figures above exclude.
  const entryCount = useMemo(
    () => new Set(filteredLines.map((l) => l.journal_entry_id)).size,
    [filteredLines],
  );
  const periodLabel = (yearStart && yearEnd)
    ? `${fmtDate(yearStart)} to ${fmtDate(yearEnd)}`
    : fmtRangeLabel(yearStart, yearEnd);

  // @invariant end >= start, as the campaign and expense forms already do it. ISO YYYY-MM-DD
  //            sorts lexically, so a string compare is safe. The `min` on the To field is
  //            advisory and a typed or pasted date walks past it: the read caps the set at
  //            yearEnd and `filteredLines` then keeps only what is on or after a LATER
  //            yearStart, so the statement is every account at $0.00 over a ledger that is not
  //            empty, correctly labelled with the reversed period and exportable to PDF. Only
  //            the Custom inputs can produce one; no preset can.
  //            @see components/shared/ExpensesPage.js saveExpense
  const rangeReversed = !!yearStart && !!yearEnd && yearEnd < yearStart;

  // Close-year affordance only enabled for prior complete years.
  const fyToClose = parseInt(yearStart.slice(0, 4), 10);
  const isFullYearRange = yearStart === `${fyToClose}-01-01` && yearEnd === `${fyToClose}-12-31`;
  const canClose = isAdmin && fyToClose < today.getFullYear() && isFullYearRange;
  const [closing, setClosing] = useState(false);
  const [showUnlock, setShowUnlock] = useState(false);
  const [showLock,   setShowLock]   = useState(false);
  const [periodRow,  setPeriodRow]  = useState(null);  // { id, fiscal_year, status, ... }
  const [periodError, setPeriodError] = useState(null);
  const periodReq = React.useRef(0);

  /**
   * Read the period row for the selected fiscal year, on load and after each of the three
   * writes. The one home for writing this state.
   *
   * @gotcha a refusal is not "no row exists" and it is not the previous status either. Every
   *         control beside this row opens a one-way door, so `periodError` set always comes
   *         with `periodRow` nulled: that is what withholds Close, Lock and Unlock through
   *         the guards they already carry, and the badge says so in place of a status.
   */
  const loadPeriod = useCallback(async () => {
    if (!isFullYearRange) { setPeriodRow(null); setPeriodError(null); return; }
    // Only the newest read may write, or switching year mid flight lands one year's status
    // under another year's buttons.
    const req = periodReq.current + 1;
    periodReq.current = req;
    const { data, error } = await supabase.from('ledger_periods').select('*').eq('fiscal_year', fyToClose).maybeSingle();
    if (periodReq.current !== req) return;
    if (error) { log('period lookup', error); setPeriodRow(null); setPeriodError(error); return; }
    setPeriodRow(data || null);
    setPeriodError(null);
  }, [fyToClose, isFullYearRange]);

  useEffect(() => { loadPeriod(); }, [loadPeriod]);

  async function handleCloseYear() {
    if (!(await askConfirm({ title: `Close fiscal year ${fyToClose}?`, body: 'Posts the year-end allocation entry. Cannot be undone without an admin override.', confirmLabel: 'Close year', requireTyped: String(fyToClose) }))) return;
    setClosing(true);
    const { error } = await supabase.rpc('close_fiscal_year', { p_fiscal_year: fyToClose });
    if (error) {
      toast.error({ title: 'Close failed', body: humanizeError(error)?.body });
    } else {
      toast.success({ title: `FY ${fyToClose} closed`, body: 'Year-end allocation entry posted.' });
    }
    setClosing(false);
    // The read decides the row, not the rpc's return, so it runs after a failed close too.
    loadPeriod();
  }

  if (loading) return <Loading />;
  if (error) return <ReadError error={error} onRetry={reload} />;

  const RenderRows = ({ rows }) => rows.length === 0 ? (
    <tr><td colSpan={2} style={{ color: 'var(--muted)', fontSize: 12 }}>No activity</td></tr>
  ) : rows.map((r) => (
    <tr key={r.account.id}>
      <td style={{ paddingLeft: 16 }}>{r.account.code}  {r.account.name}</td>
      <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{fmtMoney(r.balance)}</td>
    </tr>
  ));

  return (
    <>
      <div className="card" style={{ marginBottom: 16, padding: '18px 20px' }}>
        <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', gap: 24, flexWrap: 'wrap' }}>
          <div style={{
            fontFamily: 'var(--font-body)', fontSize: 14, fontWeight: 600,
            color: 'var(--white)', letterSpacing: '1.4px', textTransform: 'uppercase',
            fontVariantNumeric: 'tabular-nums',
          }}>
            {fmtRangeLabel(yearStart, yearEnd)}
          </div>
          <div style={{ display: 'flex', alignItems: 'baseline', fontSize: 11, letterSpacing: '1px', textTransform: 'uppercase', fontWeight: 500 }}>
            {DATE_PRESETS.map((p, i) => {
              const r = p.range();
              const active = (yearStart || '') === r.from && (yearEnd || '') === r.to;
              return (
                <React.Fragment key={p.id}>
                  {i > 0 ? <span style={{ color: 'var(--dim)', padding: '0 10px' }}>·</span> : null}
                  <button
                    onClick={() => { setYearStart(r.from); setYearEnd(r.to); setCustomOpen(false); }}
                    className="ledger-date-preset"
                    style={{
                      background: 'transparent', border: 0, padding: '2px 0', cursor: 'pointer',
                      color: active ? 'var(--orange)' : 'var(--muted)',
                      fontFamily: 'inherit', fontSize: 'inherit',
                      fontWeight: active ? 600 : 500,
                      letterSpacing: 'inherit', textTransform: 'inherit',
                      transition: 'color 120ms ease',
                    }}
                  >{p.label}</button>
                </React.Fragment>
              );
            })}
            <span style={{ color: 'var(--dim)', padding: '0 10px' }}>·</span>
            {(() => {
              const noPresetMatches = !DATE_PRESETS.some((p) => {
                const r = p.range();
                return (yearStart || '') === r.from && (yearEnd || '') === r.to;
              });
              const active = customOpen || noPresetMatches;
              return (
                <button
                  onClick={() => setCustomOpen((v) => !v)}
                  className="ledger-date-preset"
                  style={{
                    background: 'transparent', border: 0, padding: '2px 0', cursor: 'pointer',
                    color: active ? 'var(--orange)' : 'var(--muted)',
                    fontFamily: 'inherit', fontSize: 'inherit',
                    fontWeight: active ? 600 : 500,
                    letterSpacing: 'inherit', textTransform: 'inherit',
                    transition: 'color 120ms ease',
                  }}
                >Custom</button>
              );
            })()}
          </div>
        </div>

        {customOpen ? (
          <div style={{ display: 'flex', gap: 12, marginTop: 12, alignItems: 'flex-end', paddingTop: 12, borderTop: '1px solid var(--border)' }}>
            <Field label="From" style={{ marginBottom: 0 }}>{(id) => (<>
              <input id={id} className="form-input" type="date" min={DB_DATE_MIN} max={DB_DATE_MAX} value={yearStart} onChange={(e) => setYearStart(e.target.value)} style={{ width: 160 }} />
            </>)}</Field>
            <Field label="To" style={{ marginBottom: 0 }}>{(id) => (<>
              <input id={id} className="form-input" type="date" min={yearStart || DB_DATE_MIN} max={DB_DATE_MAX} value={yearEnd} onChange={(e) => setYearEnd(e.target.value)} style={{ width: 160 }} />
            </>)}</Field>
            {(yearStart || yearEnd) ? (
              <button
                onClick={() => { setYearStart(''); setYearEnd(''); }}
                style={{
                  background: 'transparent', border: 0, padding: '8px 0', cursor: 'pointer',
                  color: 'var(--muted)', fontSize: 11, letterSpacing: '1px',
                  textTransform: 'uppercase', fontWeight: 500, marginBottom: 4,
                }}
              >Clear dates</button>
            ) : null}
          </div>
        ) : null}
      </div>

      {/* A reversed range is refused HERE rather than in a third early return above, because
          the range inputs are how the person corrects what they just typed. Withholding the
          whole block and not only the table is what removes Export PDF, which is the way the
          zeroed statement left the building. */}
      {rangeReversed ? (
        <Feedback value={{
          tone: 'error',
          title: 'End date cannot be before the start date.',
          body: 'No profit and loss is drawn for a period that ends before it starts. Set the To date on or after the From date.',
        }} />
      ) : (
        <>
        <div style={{ display: 'flex', justifyContent: 'flex-end', flexWrap: 'wrap', gap: 12, marginBottom: 16 }}>
          <div style={{ display: 'flex', gap: 8 }}>
            <button className="btn btn-ghost btn-sm" onClick={async () => {
              const m = await import('../../utils/ledgerPdf');
              await m.downloadPLPdf(pl, periodLabel, null, `pl-${yearStart}-${yearEnd}.pdf`);
            }}>Export PDF</button>
            {isAdmin && isFullYearRange && periodRow && periodRow.status === 'open' && fyToClose < today.getFullYear() ? (
              <>
                <button className="btn btn-primary btn-sm" onClick={handleCloseYear} disabled={closing}>{closing ? 'Closing…' : `Close FY ${fyToClose}`}</button>
                <HelpIcon slug="year-end-close" />
              </>
            ) : null}
            {isAdmin && isFullYearRange && periodRow && periodRow.status === 'closed' ? (
              <>
                <button className="btn btn-secondary btn-sm" onClick={() => setShowLock(true)}>{`Lock FY ${fyToClose}`}</button>
                <HelpIcon slug="locking" />
              </>
            ) : null}
            {isAdmin && isFullYearRange && periodRow && (periodRow.status === 'closed' || periodRow.status === 'locked') ? (
              <>
                <button className="btn btn-ghost btn-sm" onClick={() => setShowUnlock(true)}>{`Unlock FY ${fyToClose}…`}</button>
                <HelpIcon slug="locking" />
              </>
            ) : null}
            {isAdmin && isFullYearRange && periodRow ? (
              <span className="badge" style={{ alignSelf: 'center', textTransform: 'uppercase', letterSpacing: 1 }}>{periodRow.status}</span>
            ) : null}
            {/* The badge answers rather than disappearing. The four guards above key off
                `periodRow`, which a refusal nulls, so they withhold themselves; this is the one
                place that has to say WHY the year has no status. */}
            {isAdmin && isFullYearRange && periodError ? (
              <span className="badge" style={{ alignSelf: 'center', textTransform: 'uppercase', letterSpacing: 1, color: 'var(--muted)' }}>Status unknown</span>
            ) : null}
            {/* When no row exists for the year (never closed) and not eligible to close,
                fall back to the original Close button visibility. This one is derived from an
                ABSENCE, so unlike the four above it has to exclude a refusal by hand. */}
            {isAdmin && !periodRow && !periodError && canClose ? (
              <button className="btn btn-primary btn-sm" onClick={handleCloseYear} disabled={closing}>{closing ? 'Closing…' : `Close FY ${fyToClose}`}</button>
            ) : null}
          </div>
        </div>

        {/* The three buttons above withhold themselves when the row is unknown, so this is
            where the reason goes. Same decision as CancelCampaignDialog's readFailed block:
            a one-way door is not offered against a ledger state nobody could read. */}
        {isAdmin && isFullYearRange && periodError ? (
          <div style={{ background: 'var(--surface2)', borderRadius: 6, padding: 14, marginBottom: 16 }}>
            <div style={{ fontWeight: 700, fontSize: 13, marginBottom: 6 }}>{`The status of FY ${fyToClose} could not be read.`}</div>
            <div style={{ fontSize: 12, color: 'var(--muted)' }}>
              There is no way to tell whether this year is open, closed or locked, so closing,
              locking and unlocking are all withheld until it reads.
            </div>
            <div style={{ marginTop: 12 }}><ReadError error={periodError} onRetry={loadPeriod} /></div>
          </div>
        ) : null}

        {showUnlock && periodRow ? (
          <PeriodUnlockModal period={periodRow} onClose={() => setShowUnlock(false)} onDone={() => { setShowUnlock(false); loadPeriod(); }} />
        ) : null}
        {showLock && periodRow ? (
          <PeriodLockModal period={periodRow} onClose={() => setShowLock(false)} onDone={() => { setShowLock(false); loadPeriod(); }} />
        ) : null}

        <div className="table-wrap">
          <table style={{ width: '100%' }}>
            <tbody>
              <tr><td style={{ color: 'var(--orange)', fontSize: 11, textTransform: 'uppercase', letterSpacing: 1.5 }}>Revenue</td><td></td></tr>
              <RenderRows rows={pl.revenue} />
              <tr style={{ borderTop: '1px solid var(--border)', fontWeight: 600 }}>
                <td>Total Revenue</td>
                <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{fmtMoney(pl.totalRevenue)}</td>
              </tr>

              <tr><td colSpan={2} style={{ height: 12 }}></td></tr>
              <tr><td style={{ color: 'var(--orange)', fontSize: 11, textTransform: 'uppercase', letterSpacing: 1.5 }}>Cost of Revenue</td><td></td></tr>
              <RenderRows rows={pl.costOfRevenue} />
              <tr style={{ borderTop: '1px solid var(--border)', fontWeight: 600 }}>
                <td>Total Cost of Revenue</td>
                <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{fmtMoney(pl.totalCostOfRevenue)}</td>
              </tr>

              <tr style={{ borderTop: '1px solid var(--border)', fontWeight: 700 }}>
                <td>Gross Profit</td>
                <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{fmtMoney(pl.grossProfit)}</td>
              </tr>

              <tr><td colSpan={2} style={{ height: 12 }}></td></tr>
              <tr><td style={{ color: 'var(--orange)', fontSize: 11, textTransform: 'uppercase', letterSpacing: 1.5 }}>Operating Expenses</td><td></td></tr>
              <RenderRows rows={pl.operatingExpenses} />
              <tr style={{ borderTop: '1px solid var(--border)', fontWeight: 600 }}>
                <td>Total Operating Expenses</td>
                <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{fmtMoney(pl.totalOperatingExpenses)}</td>
              </tr>
            </tbody>
          </table>
        </div>

        <div style={{ marginTop: 24, textAlign: 'right', fontFamily: 'var(--font-display)', fontSize: 28, color: pl.netIncome > 0 ? 'var(--orange)' : pl.netIncome < 0 ? 'var(--red)' : 'var(--muted)' }}>
          NET INCOME  {fmtMoney(pl.netIncome)}
        </div>

        <div style={{ marginTop: 4, textAlign: 'right', fontSize: 11, color: 'var(--muted)' }}>{entryCount} posted {entryCount === 1 ? 'entry' : 'entries'} · {periodLabel}</div>
        </>
      )}
    </>
  );
}

/**
 * Flips a fiscal year from closed to locked. Locked-period JEs are immutable to
 * every role including admin; unlock (with a written reason) is the only way back.
 */
function PeriodLockModal({ period, onClose, onDone }) {
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  async function handleLock() {
    setBusy(true); setError('');
    const { error: upErr } = await supabase
      .from('ledger_periods')
      .update({ status: 'locked', locked_at: new Date().toISOString() })
      .eq('id', period.id);
    if (upErr) { setError(humanizeError(upErr)); setBusy(false); return; }
    await supabase.rpc('write_audit_log', {
      p_event_type: 'period_relocked',
      p_je_id: null,
      p_period_id: period.id,
      p_reason: `Locked FY ${period.fiscal_year} for additional protection.`,
      p_meta: { fiscal_year: period.fiscal_year, previous_status: period.status },
    });
    setBusy(false);
    onDone();
  }
  return (
    <Modal
      title={`LOCK FY ${period.fiscal_year}`}
      size="sm"
      onClose={onClose}
      closeDisabled={busy}
    >
        <div className="modal-body">
          <p style={{ fontSize: 13, marginBottom: 12 }}>
            Locking flips the period status from <strong>closed</strong> to <strong>locked</strong>. JEs in a locked period are immutable to every role, including admin. You can still unlock with a written reason.
          </p>
          {error ? <Feedback value={error} /> : null}
        </div>
        <div className="modal-footer">
          <ModalClose className="btn btn-ghost" disabled={busy}>Cancel</ModalClose>
          <button className="btn btn-primary" onClick={handleLock} disabled={busy}>{busy ? 'Locking…' : `Lock FY ${period.fiscal_year}`}</button>
        </div>
    </Modal>
  );
}

/**
 * Reopens a closed/locked fiscal year for backdated edits, reversals, and
 * re-running the year-end close.
 *
 * @invariant a reason is required and persisted to ledger_audit_log; if the
 *            period unlocks but the audit write fails, the user is told.
 */
function PeriodUnlockModal({ period, onClose, onDone }) {
  const [reason, setReason] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  async function handleUnlock() {
    if (!reason.trim()) { setError('Reason is required for the audit log.'); return; }
    setBusy(true); setError('');
    const { error: upErr } = await supabase
      .from('ledger_periods')
      .update({ status: 'open', locked_at: null })
      .eq('id', period.id);
    if (upErr) { setError(humanizeError(upErr)); setBusy(false); return; }
    const { error: auErr } = await supabase.rpc('write_audit_log', {
      p_event_type: 'period_unlocked',
      p_je_id: null,
      p_period_id: period.id,
      p_reason: reason.trim().slice(0, 1000),
      p_meta: { fiscal_year: period.fiscal_year, previous_status: period.status },
    });
    if (auErr) { setError('Period was unlocked but the audit log write failed: ' + auErr.message); setBusy(false); return; }
    setBusy(false);
    onDone();
  }
  return (
    <Modal
      title={`UNLOCK FY ${period.fiscal_year}`}
      size="md"
      onClose={onClose}
      closeDisabled={busy}
    >
        <div className="modal-body">
          <p style={{ fontSize: 13, marginBottom: 12 }}>
            Unlocking flips the period status to <strong>open</strong>. Backdated edits, reversals, and re running [year-end close] become possible again. If a 1065 has already been filed for this year, talk to the tax accountant before unlocking.
          </p>
          <Field label="Reason (required)">{(id) => (<>
            <textarea id={id} className="form-textarea" rows={4} maxLength={1000} value={reason} onChange={(e) => setReason(e.target.value)} placeholder="Recorded in the audit log permanently." />
          </>)}</Field>
          {error ? <Feedback value={error} /> : null}
        </div>
        <div className="modal-footer">
          <ModalClose className="btn btn-ghost" disabled={busy}>Cancel</ModalClose>
          <button className="btn btn-danger" onClick={handleUnlock} disabled={busy || !reason.trim()}>{busy ? 'Unlocking…' : `Unlock FY ${period.fiscal_year}`}</button>
        </div>
    </Modal>
  );
}

