/** |off_by| at or below this auto-plugs the variance to 6950 Reconciliation Adjustments. */
const ROUNDING_TOLERANCE = 0.05;

/**
 * What one tick box in the reconciliation table is FOR, per row.
 *
 * The column is the primary control on this screen and every box in it is the same shape, so
 * a constant name announces the column and says nothing about the line the reader is about to
 * clear. This is the date, the description and the signed amount, which is what the three
 * columns beside it print.
 */
function reconLineLabel(l) {
  const debit = Number(l.debit || 0);
  const amount = debit > 0 ? fmtMoney(debit) : fmtMoney(Number(l.credit || 0));
  const side = debit > 0 ? 'in' : 'out';
  return `Reconcile ${fmtDate(l.entry.entry_date)}, ${l.entry.description || 'no description'}, ${amount} ${side}`;
}

/**
 * Reconcile Bank tab: tick cleared cash-account (1000) lines against a statement balance, save
 * the reconciliation, and review or unwind past ones. Auto-ticks lines dated on or before the
 * as-of date; CSV import auto-matches by amount within a 7-day window.
 *
 * @invariant difference = (priorCleared + this-session ticked) - bankBalance. The bank balance
 *   is absolute, so the cleared-ledger side must be cumulative: it adds back every line stamped
 *   by earlier reconciliations, not just the lines ticked now. Comparing this-session net
 *   against the full bank balance is off by the entire prior cleared balance from the second
 *   reconciliation on. @see docs/MONEY.md and hub-src/src/docs/manual/periodic/bank-reconciliation.md
 * @gotcha when |difference| <= ROUNDING_TOLERANCE the save posts a balanced 2-line JE plugging
 *         the variance to 6950 and stamps that cash leg with the reconciliation_id, so the
 *         recon's lines sum to the bank balance exactly.
 * @gotcha the open pool AND priorCleared exclude reversed JEs and REVERSAL: counter-entries via
 *         one shared filter, so a reversed pair nets to zero across the whole universe.
 * @security submit is admin-only (isAdmin gate on canSubmit).
 */
function ReconcileBankTab({ accounts, isAdmin }) {
  const cashAccount = useMemo(() => accounts.find((a) => a.code === '1000'), [accounts]);
  const roundingAccount = useMemo(() => accounts.find((a) => a.code === '6950'), [accounts]);
  const toast = useToast();
  const askConfirm = useConfirm();

  const [past, setPast] = useState([]);
  // todayYMD, never toISOString. statement_date is a `date` column, so an evening
  // reconciliation in New York was stamped with tomorrow.
  const [statementDate, setStatementDate] = useState(todayYMD);
  const [statementBalance, setStatementBalance] = useState('');
  const [unreconciled, setUnreconciled] = useState([]);
  // Net cash (debit - credit) on 1000 already stamped by prior reconciliations.
  // The running difference is measured against the bank's ABSOLUTE balance, so it
  // must include this cumulative base, not just the lines ticked this session.
  const [priorCleared, setPriorCleared] = useState(0);
  const [unrecLoading, setUnrecLoading] = useState(true);
  const [poolError, setPoolError] = useState(null);
  // Explicit overrides on top of the auto-tick rule (entry_date ≤ statementDate).
  const [userTicked, setUserTicked] = useState(() => new Set());
  const [userUnticked, setUserUnticked] = useState(() => new Set());
  const [search, setSearch] = useState('');
  const [notes, setNotes] = useState('');
  const [saving, setSaving] = useState(false);
  const [refreshTick, setRefreshTick] = useState(0);
  const [pastOpen, setPastOpen] = useState(false);
  const [pastError, setPastError] = useState(null);
  const [reviewing, setReviewing] = useState(null); // {rec, lines}
  const [csvOpen, setCsvOpen] = useState(false);
  // Text selected in a description cell. Other rows whose description contains
  // the same substring (case-insensitive) get a highlight. Visual only, no state change.
  const [highlightToken, setHighlightToken] = useState('');
  const renderWithHighlight = (text, token) => {
    const s = String(text || '');
    if (!token) return s;
    const lower = s.toLowerCase();
    const t = token.toLowerCase();
    const out = [];
    let i = 0;
    let k = 0;
    while (i < s.length) {
      const idx = lower.indexOf(t, i);
      if (idx === -1) { out.push(s.slice(i)); break; }
      if (idx > i) out.push(s.slice(i, idx));
      out.push(<mark key={k++} className="recon-mark">{s.slice(idx, idx + token.length)}</mark>);
      i = idx + token.length;
    }
    return out;
  };
  const onDescSelect = useCallback(() => {
    const sel = typeof window !== 'undefined' ? window.getSelection() : null;
    const text = sel ? sel.toString().trim() : '';
    setHighlightToken(text.length >= 3 ? text : '');
  }, []);

  // Refetch past on save. Read to exhaustion rather than `.limit(50)`: the control beside it
  // states `Past (N)` off this array, so a cap made the count a claim about a prefix. One row
  // per reconciliation, roughly monthly, so 50 was about four years.
  // @see utils/fetchAllRows.js
  useEffect(() => {
    let alive = true;
    (async () => {
      try {
        const data = await fetchAllRows(() => supabase
          .from('bank_reconciliations')
          .select('id, statement_date, statement_balance, ledger_balance, difference, status, notes, completed_at')
          .order('statement_date', { ascending: false }).order('id'));
        if (!alive) return;
        setPast(data);
        setPastError(null);
      } catch (e) {
        if (!alive) return;
        // A count nobody could read is not a count of 0: "Past (0)" over a year of monthly
        // reconciliations takes the review and Unwind path with it.
        log('past', e);
        setPast([]);
        setPastError(e);
      }
    })();
    return () => { alive = false; };
  }, [refreshTick]);

  // A cash read that did not complete is not an empty pool. Both figures the bar is built
  // from are cleared with it, so nothing downstream can be computed from a stale half.
  // @see components/shared/ReadError.js
  const failPool = useCallback((error) => {
    setPoolError(error);
    setUnreconciled([]);
    setPriorCleared(0);
    setUnrecLoading(false);
  }, []);

  // Fetch every 1000 line, then partition into the open pool (not yet stamped)
  // and the cumulative prior-cleared base (stamped by earlier reconciliations).
  // BOTH sides apply the identical "reconciliation universe" filter: posted JE,
  // not itself reversed, and not a REVERSAL: counter-entry.
  // @invariant the two sides MUST share one filter. A reversed+stamped line whose
  //   REVERSAL counter-entry is (correctly) hidden from the pool would otherwise
  //   leave its cash effect counted in priorCleared with no offset, silently
  //   skewing every future reconciliation by that amount. Excluding reversed lines
  //   from priorCleared keeps the pair netting to zero across the whole universe.
  // @gotcha reversed pairs net to zero, so dropping both is balance-preserving;
  //   the asymmetry only bites when one half (the stamped original) survives.
  useEffect(() => {
    let alive = true;
    if (!cashAccount) { setUnrecLoading(false); return; }
    (async () => {
      setUnrecLoading(true);
      setPoolError(null);
      // 322 cash lines today, under PostgREST's 1,000-row response cap, so this
      // was not yet truncating. Paged anyway: reconciliation is cumulative, so a
      // dropped line would not merely hide a row, it would shift the running
      // cleared balance and every difference computed from it. @see utils/fetchAllRows.js
      let data;
      try {
        data = await fetchAllRows(() => supabase
          .from('ledger_entry_lines')
          .select('id, debit, credit, journal_entry_id, reconciliation_id')
          .eq('account_id', cashAccount.id)
          .order('id'));
      } catch (error) {
        if (!alive) return;
        log('unrec', error); failPool(error); return;
      }
      if (!alive) return;
      // Deduplicated and chunked for the same two bounds useAllLines respects: `in` limits
      // how many IDS fit in the request URL, and PostgREST caps how many ROWS come back at
      // 1,000 whatever the list asked for.
      // @gotcha an entry that did not come back drops its line out of `universe` with no
      //         trace, and `universe` is what BOTH sides of the sum are built from, so the
      //         loss lands on the open pool and on the cumulative prior-cleared base at
      //         once. A reconciliation carries into every later one, so a line dropped here
      //         shifts the difference for good. @see utils/fetchAllRows.js
      const ids = [...new Set((data || []).map((l) => l.journal_entry_id))];
      const ents = [];
      try {
        for (let i = 0; i < ids.length; i += 500) {
          const page = await fetchAllRows(() => supabase
            .from('ledger_journal_entries')
            .select('id, entry_date, description, source_type, source_id, is_posted, reversed_by_je_id')
            .in('id', ids.slice(i, i + 500))
            .order('id'));
          for (const e of page) ents.push(e);
        }
      } catch (eErr) {
        if (!alive) return;
        log('unrec', eErr); failPool(eErr); return;
      }
      if (!alive) return;
      // Two terms, not two definitions of one word. `isReversalEntry` is what "is a reversal"
      // MEANS (utils/journalEntry.js); this set is the separate fact that another entry in
      // this very pool names it as its counter-entry. The local predicate that stood here
      // dropped the `source_type === 'manual'` half, so an invoice or payout entry whose
      // description merely opened with `REVERSAL:` was hidden from the pool by one answer and
      // kept by the shared one three hundred lines above, on the same screen.
      const reversalJeIds = new Set(ents.map((e) => e.reversed_by_je_id).filter(Boolean));
      const eMap = new Map(
        ents
          .filter((e) => e.is_posted && !e.reversed_by_je_id
            && !reversalJeIds.has(e.id) && !isReversalEntry(e))
          .map((e) => [e.id, e])
      );
      // Lines inside the reconciliation universe (valid JE), decorated with entry.
      const universe = (data || []).map((l) => ({ ...l, entry: eMap.get(l.journal_entry_id) })).filter((l) => l.entry);
      const prior = universe
        .filter((l) => l.reconciliation_id != null)
        .reduce((s, l) => s + Number(l.debit || 0) - Number(l.credit || 0), 0);
      const decorated = universe
        .filter((l) => l.reconciliation_id == null)
        .sort((a, b) => (a.entry.entry_date < b.entry.entry_date ? -1 : 1));
      if (alive) {
        setPriorCleared(Math.round(prior * 100) / 100);
        setUnreconciled(decorated);
        setUnrecLoading(false);
      }
    })();
    return () => { alive = false; };
  }, [cashAccount, refreshTick, failPool]);

  // Auto-tick: line is checked if (entry_date ≤ statementDate or userTicked) and not userUnticked.
  const isChecked = useCallback((line) => {
    if (userUnticked.has(line.id)) return false;
    if (userTicked.has(line.id)) return true;
    return line.entry.entry_date <= statementDate;
  }, [userTicked, userUnticked, statementDate]);

  const filteredLines = useMemo(() => {
    if (!search.trim()) return unreconciled;
    const q = search.trim().toLowerCase();
    return unreconciled.filter((l) =>
      (l.entry.description || '').toLowerCase().includes(q)
      || String(l.debit || '').includes(q)
      || String(l.credit || '').includes(q)
    );
  }, [unreconciled, search]);

  const checkedTotal = useMemo(() =>
    unreconciled.reduce((s, l) => isChecked(l) ? s + Number(l.debit || 0) - Number(l.credit || 0) : s, 0),
  [unreconciled, isChecked]);
  const checkedCount = useMemo(() => unreconciled.filter(isChecked).length, [unreconciled, isChecked]);
  const keptOpenCount = unreconciled.length - checkedCount;
  const oldestKept = useMemo(() => {
    for (const l of unreconciled) if (!isChecked(l)) return l.entry.entry_date;
    return null;
  }, [unreconciled, isChecked]);

  const stmtBal = parseFloat(statementBalance) || 0;
  // Cleared ledger cash = what prior reconciliations already matched + what we
  // tick now. Compared against the bank's absolute balance so the difference is
  // meaningful across successive monthly reconciliations (not just the first).
  const clearedBalance = Math.round((priorCleared + checkedTotal) * 100) / 100;
  const diff = Math.round((clearedBalance - stmtBal) * 100) / 100;
  const balanceEntered = statementBalance !== '';
  const balanced = balanceEntered && diff === 0;
  const withinTolerance = balanceEntered && !balanced && Math.abs(diff) <= ROUNDING_TOLERANCE && !!roundingAccount;
  const canSubmit = isAdmin && balanceEntered && checkedCount > 0 && (balanced || withinTolerance);

  /**
   * The reconcile bar's four states, resolved ONCE. The heading, the tone, the
   * value and the button each derived this independently in three different test orders;
   * they agree today only because `balanced` and `withinTolerance` already require
   * `balanceEntered`. A reconciliation display that disagrees with itself about which
   * state it is in is money-facing, which is the reason, not the 3 points of complexity.
   * @invariant one order: not entered, balanced, within tolerance, off. Never re-derive it.
   */
  const view = !balanceEntered ? { key: 'not-entered', label: 'MARKED CLEARED', tone: 'recon-diff-muted' }
    : balanced ? { key: 'balanced', label: 'BALANCED', tone: 'recon-diff-ok' }
      : withinTolerance ? { key: 'tolerance', label: 'OFF BY', tone: 'recon-diff-tolerance' }
        : { key: 'off', label: 'OFF BY', tone: 'recon-diff-off' };

  function toggleLine(line) {
    const currentlyChecked = isChecked(line);
    const want = !currentlyChecked;
    const defaultIs = line.entry.entry_date <= statementDate;
    setUserTicked((prev) => {
      const next = new Set(prev); next.delete(line.id);
      if (want && !defaultIs) next.add(line.id);
      return next;
    });
    setUserUnticked((prev) => {
      const next = new Set(prev); next.delete(line.id);
      if (!want && defaultIs) next.add(line.id);
      return next;
    });
  }

  function setAll(state) {
    if (state === 'all') {
      setUserTicked(new Set(unreconciled.map((l) => l.id)));
      setUserUnticked(new Set());
    } else if (state === 'none') {
      setUserTicked(new Set());
      setUserUnticked(new Set(unreconciled.map((l) => l.id)));
    } else if (state === 'through') {
      setUserTicked(new Set());
      setUserUnticked(new Set());
    }
  }

  function tickToHere(line) {
    setStatementDate(line.entry.entry_date);
    setUserTicked(new Set());
    setUserUnticked(new Set());
  }

  function applyCsvAutoMatch(matched) {
    setUserTicked((prev) => {
      const next = new Set(prev);
      for (const id of matched) next.add(id);
      return next;
    });
    setUserUnticked((prev) => {
      const next = new Set(prev);
      for (const id of matched) next.delete(id);
      return next;
    });
    setCsvOpen(false);
    toast.success(`Matched ${matched.length} line${matched.length === 1 ? '' : 's'} from CSV`);
  }

  async function handleSubmit() {
    if (!canSubmit) return;
    setSaving(true);
    const checkedIds = unreconciled.filter(isChecked).map((l) => l.id);
    // Final ledger_balance/difference reported on the reconciliation reflect the post-adjustment state.
    const willPlug = withinTolerance && Math.abs(diff) > 0;
    // Store the cumulative cleared balance (not just this session's net), so the
    // saved record's ledger_balance ties to the bank statement it was matched to.
    const finalLedger = willPlug ? stmtBal : clearedBalance;
    const finalDiff = willPlug ? 0 : diff;
    const insertPayload = {
      statement_date: statementDate,
      statement_balance: stmtBal,
      ledger_balance: finalLedger,
      difference: finalDiff,
      status: 'complete',
      completed_at: new Date().toISOString(),
      notes: notes.trim() || null,
    };
    const { data: { user } = {} } = await supabase.auth.getUser();
    if (user) insertPayload.completed_by = user.id;

    const { data: rec, error: insErr } = await supabase
      .from('bank_reconciliations').insert(insertPayload).select().single();
    if (insErr) { toast.error({ title: 'Save failed', body: humanizeError(insErr)?.body }); setSaving(false); return; }

    // If within rounding tolerance, post a balanced 2-line manual JE plugging the
    // variance to 6950. The 1000 leg gets stamped with reconciliation_id alongside
    // the ticked lines so the recon's lines sum to the bank balance exactly.
    let roundingJeId = null;
    if (willPlug) {
      const adjAmt = Math.round(Math.abs(diff) * 100) / 100;
      const ledgerHigher = diff > 0; // ledger above bank . need to credit Cash
      // Unposted first, lines, then post. Same reasoning as the Manual Entry
      // modal above: PostgREST cannot make the pair atomic from here, so the
      // reachable half-written state is an unposted draft rather than a posted
      // entry with no lines.
      const { data: rjE, error: rjErr } = await supabase
        .from('ledger_journal_entries').insert({
          entry_date: statementDate,
          description: `Bank rounding adjustment, ${statementDate}`,
          reference: `recon:${rec.id.slice(0, 8)}`,
          source_type: 'manual',
          source_id: null,
          is_posted: false,
          created_by: user?.id || null,
        }).select().single();
      if (rjErr) { toast.error({ title: 'Rounding entry failed', body: humanizeError(rjErr)?.body }); setSaving(false); return; }
      const cashLine = {
        journal_entry_id: rjE.id,
        account_id: cashAccount.id,
        debit:  ledgerHigher ? 0 : adjAmt,
        credit: ledgerHigher ? adjAmt : 0,
        description: 'Bank rounding adjustment',
      };
      const adjLine = {
        journal_entry_id: rjE.id,
        account_id: roundingAccount.id,
        debit:  ledgerHigher ? adjAmt : 0,
        credit: ledgerHigher ? 0 : adjAmt,
        description: 'Bank rounding adjustment',
      };
      const { data: insertedLines, error: rlErr } = await supabase
        .from('ledger_entry_lines').insert([cashLine, adjLine]).select('id, account_id');
      if (rlErr) {
        // Still unposted, so this delete is always permitted.
        const { error } = await mutate(supabase.from('ledger_journal_entries').delete().eq('id', rjE.id));
        if (error) { setSaving(false); toast.error(error); return; }
        toast.error({ title: 'Rounding lines failed', body: humanizeError(rlErr)?.body });
        setSaving(false); return;
      }
      const { error: rpErr } = await supabase
        .from('ledger_journal_entries').update({ is_posted: true }).eq('id', rjE.id);
      if (rpErr) {
        toast.error({ title: 'Rounding entry not posted', body: humanizeError(rpErr)?.body });
        setSaving(false); return;
      }
      roundingJeId = rjE.id;
      const cashLineId = (insertedLines || []).find((l) => l.account_id === cashAccount.id)?.id;
      if (cashLineId) checkedIds.push(cashLineId);
    }

    const { error: upErr } = await supabase
      .from('ledger_entry_lines').update({ reconciliation_id: rec.id }).in('id', checkedIds);
    if (upErr) { toast.error({ title: 'Lines update failed', body: humanizeError(upErr)?.body }); setSaving(false); return; }

    await supabase.rpc('write_audit_log', {
      p_event_type: 'reconciliation_completed',
      p_je_id: null,
      p_period_id: null,
      p_reason: notes.trim() || null,
      p_meta: {
        reconciliation_id: rec.id,
        lines_cleared: checkedIds.length,
        statement_balance: stmtBal,
        ...(roundingJeId ? { rounding_je_id: roundingJeId, rounding_amount: Math.round(diff * 100) / 100 } : {}),
      },
    });

    setUserTicked(new Set()); setUserUnticked(new Set());
    setNotes(''); setStatementBalance(''); setSaving(false);
    setRefreshTick((t) => t + 1);
    const adjSuffix = roundingJeId ? `, ${fmtMoney(Math.abs(diff))} posted to 6950` : '';
    toast.success(`Reconciled through ${fmtDate(statementDate)}, ${checkedIds.length} line${checkedIds.length === 1 ? '' : 's'} cleared${adjSuffix}`);
  }

  async function enterReviewMode(rec) {
    setPastOpen(false);
    // Both bounds the open pool respects 250 lines above, for a stronger reason. This list is
    // what Unwind releases and what `lines_released` writes into the audit log, so a prefix
    // here understates a permanent record of a money event. `.filter((l) => l.entry)` below
    // makes the loss silent: a line whose entry did not come back leaves no trace at all.
    // @see utils/fetchAllRows.js
    let lines;
    const ents = [];
    try {
      lines = await fetchAllRows(() => supabase
        .from('ledger_entry_lines')
        .select('id, debit, credit, journal_entry_id')
        .eq('reconciliation_id', rec.id)
        .order('id'));
      const ids = [...new Set(lines.map((l) => l.journal_entry_id))];
      for (let i = 0; i < ids.length; i += 500) {
        const page = await fetchAllRows(() => supabase
          .from('ledger_journal_entries')
          .select('id, entry_date, description, source_type, source_id')
          .in('id', ids.slice(i, i + 500))
          .order('id'));
        for (const e of page) ents.push(e);
      }
    } catch (error) {
      toast.error({ title: 'Could not load reconciliation', body: humanizeError(error)?.body });
      return;
    }
    const eMap = new Map(ents.map((e) => [e.id, e]));
    const decorated = lines.map((l) => ({ ...l, entry: eMap.get(l.journal_entry_id) })).filter((l) => l.entry)
      .sort((a, b) => (a.entry.entry_date < b.entry.entry_date ? -1 : 1));
    setReviewing({ rec, lines: decorated });
  }

  async function unwindReconciliation() {
    if (!reviewing) return;
    const rec = reviewing.rec;
    const ok = await askConfirm({
      title: `Unwind reconciliation from ${fmtDate(rec.statement_date)}?`,
      body: `${reviewing.lines.length} line${reviewing.lines.length === 1 ? '' : 's'} will be released back to the unreconciled list. The reconciliation record will be deleted. Audit log keeps the original event.`,
      danger: true,
      confirmLabel: 'Unwind',
    });
    if (!ok) return;
    const lineIds = reviewing.lines.map((l) => l.id);
    if (lineIds.length) {
      const { error: upErr } = await supabase
        .from('ledger_entry_lines').update({ reconciliation_id: null }).in('id', lineIds);
      if (upErr) { toast.error({ title: 'Release failed', body: humanizeError(upErr)?.body }); return; }
    }
    const { error: delErr } = await supabase.from('bank_reconciliations').delete().eq('id', rec.id);
    if (delErr) { toast.error({ title: 'Delete failed', body: humanizeError(delErr)?.body }); return; }
    await supabase.rpc('write_audit_log', {
      p_event_type: 'reconciliation_completed',
      p_je_id: null,
      p_period_id: null,
      p_reason: `Unwound reconciliation ${rec.id.slice(0, 8)} from ${rec.statement_date}.`,
      p_meta: { unwound_reconciliation_id: rec.id, lines_released: lineIds.length, original_statement_balance: rec.statement_balance },
    });
    setReviewing(null);
    setRefreshTick((t) => t + 1);
    toast.success(`Unwound reconciliation, ${lineIds.length} line${lineIds.length === 1 ? '' : 's'} released`);
  }

  if (!cashAccount) {
    // The code stays: four SECURITY DEFINER functions look 1000 up by it. What was missing
    // was the cause and the screen that fixes it.
    return <EmptyState
      title="No cash account to reconcile against"
      text="Reconcile compares the ledger against a bank statement for account 1000, and the chart of accounts has no such row. Add it on the Chart of Accounts tab, then come back." />;
  }

  // ── REVIEW MODE ────────────────────────────────────────────────
  if (reviewing) {
    return (
      <div className="recon">
        <div className="recon-bar recon-bar-review">
          <div className="recon-bar-grid">
            <div>
              <div className="recon-stat-label">REVIEWING</div>
              <div className="recon-stat-value">{fmtDate(reviewing.rec.statement_date)}</div>
            </div>
            <div>
              <div className="recon-stat-label">BANK BALANCE</div>
              <div className="recon-stat-value" style={{ fontVariantNumeric: 'tabular-nums' }}>{fmtMoney(reviewing.rec.statement_balance)}</div>
            </div>
            <div>
              <div className="recon-stat-label">LEDGER</div>
              <div className="recon-diff recon-diff-muted">{fmtMoney(reviewing.rec.ledger_balance)}</div>
            </div>
            <div className="recon-bar-actions">
              <button className="btn btn-ghost" onClick={() => setReviewing(null)}>← Back to live</button>
              {isAdmin && <button className="btn btn-danger" onClick={unwindReconciliation}>Unwind…</button>}
            </div>
          </div>
        </div>
        <div className="recon-status-strip">
          {reviewing.lines.length} line{reviewing.lines.length === 1 ? '' : 's'} reconciled · diff {fmtMoney(reviewing.rec.difference)}
          {reviewing.rec.notes ? <span> · {reviewing.rec.notes}</span> : null}
        </div>
        <div className="recon-table-wrap">
          <table className="recon-table">
            <thead><tr><th scope="col" style={{ width: 110 }}>Date</th><th scope="col">Description</th><th scope="col" style={{ textAlign: 'right', width: 110 }}>Debit</th><th scope="col" style={{ textAlign: 'right', width: 110 }}>Credit</th></tr></thead>
            <tbody>
              {reviewing.lines.map((l) => (
                <tr key={l.id}>
                  <td style={{ fontVariantNumeric: 'tabular-nums', fontSize: 12 }}>{fmtDate(l.entry.entry_date)}</td>
                  <td style={{ fontSize: 12 }}>
                    <LedgerSourceLink sourceType={l.entry.source_type} sourceId={l.entry.source_id} toast={toast}>
                      {l.entry.description}
                    </LedgerSourceLink>
                  </td>
                  <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{Number(l.debit) > 0 ? fmtMoney(l.debit) : ''}</td>
                  <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{Number(l.credit) > 0 ? fmtMoney(l.credit) : ''}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    );
  }

  // A refused cash read leaves priorCleared at 0 and the pool empty, which reads as
  // "The books match the bank." under a bar whose difference is measured against nothing.
  if (poolError) {
    return <ReadError error={poolError} onRetry={() => setRefreshTick((t) => t + 1)} />;
  }

  // ── LIVE MODE ──────────────────────────────────────────────────
  return (
    <div className="recon">
      {/* Sticky action bar */}
      <div className="recon-bar">
        <div className="recon-bar-grid">
          <div>
            <label className="recon-stat-label" htmlFor="recon-asof">AS OF</label>
            <input
              id="recon-asof"
              className="recon-input"
              type="date" min={DB_DATE_MIN} max={DB_DATE_MAX}
              value={statementDate}
              onChange={(e) => setStatementDate(e.target.value)}
            />
          </div>
          <div>
            <label className="recon-stat-label" htmlFor="recon-bal">BANK BALANCE</label>
            <MoneyInput
              id="recon-bal"
              className="recon-input"
              placeholder="0.00"
              value={statementBalance}
              onChange={(e) => setStatementBalance(e.target.value)}
            />
          </div>
          <div>
            <div className="recon-stat-label">{view.label}</div>
            <div className={`recon-diff ${view.tone}`}>
              {view.key === 'not-entered'
                ? fmtMoney(checkedTotal)
                : view.key === 'balanced'
                  ? <>$0.00<span className="recon-diff-check" aria-hidden="true"> ✓</span></>
                  : (diff > 0 ? '+' : '') + fmtMoney(Math.abs(diff) > 0 ? diff : 0)}
              {view.key === 'tolerance' && <span className="recon-diff-suffix">within tolerance</span>}
            </div>
          </div>
          <div className="recon-bar-actions">
            <SubmitButton saving={saving} className="btn btn-primary recon-save" onClick={handleSubmit} disabled={!canSubmit || saving} title={
                !isAdmin ? 'Admin only.'
                  : view.key === 'not-entered' ? 'Enter the bank balance to start.'
                  : view.key === 'off' ? `Off by ${fmtMoney(Math.abs(diff))}. Untick lines that have not cleared yet, or check the bank balance.`
                  : checkedCount === 0 ? 'Tick at least one line to reconcile.'
                  : view.key === 'tolerance' ? `Posts a ${fmtMoney(Math.abs(diff))} adjustment to 6950 Reconciliation Adjustments and saves.`
                  : ''
              }>{view.key === 'tolerance' ? `Save & post ${fmtMoney(Math.abs(diff))}` : 'Save'}</SubmitButton>
          </div>
        </div>
      </div>

      {/* Status strip */}
      <div className="recon-status-strip">
        {!balanceEntered ? (
          <span className="text-muted">Pick a date and bank balance to start. Lines on or before the as-of date are auto-ticked.</span>
        ) : (
          <>
            <strong>{checkedCount}</strong> line{checkedCount === 1 ? '' : 's'} cleared · <span style={{ fontVariantNumeric: 'tabular-nums' }}>{fmtMoney(checkedTotal)}</span>
            {keptOpenCount > 0 && (
              <> · <strong>{keptOpenCount}</strong> kept open{oldestKept ? <> · oldest {fmtDate(oldestKept)}</> : null}</>
            )}
          </>
        )}
      </div>

      {/* Controls row */}
      <div className="recon-controls-row">
        <div className="recon-segment" role="group" aria-label="Bulk select">
          <button className="recon-segment-btn" onClick={() => setAll('all')} title="Tick every line">All</button>
          <button className="recon-segment-btn" onClick={() => setAll('none')} title="Untick every line">None</button>
          <button className="recon-segment-btn" onClick={() => setAll('through')} title="Reset to auto-tick (≤ as-of date)">Through date</button>
        </div>
        <input
          className="recon-input recon-search"
          type="search" aria-label="Search bank lines by description or amount"
          placeholder="Search description or amount…"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
        <button className="btn btn-ghost btn-sm" onClick={() => setCsvOpen(true)}>Import CSV</button>
        <div className="recon-past">
          <button className="btn btn-ghost btn-sm" onClick={() => setPastOpen((o) => !o)}>
            Past ({pastError ? '?' : past.length}) {pastOpen ? '▴' : '▾'}
          </button>
          {pastOpen && (
            <div className="recon-past-menu">
              {pastError ? (
                /* No retry to offer: the read is an effect keyed on `refreshTick`, and there
                   is no loader a button could re-invoke. `TaxEstimate` is the same shape. */
                <div style={{ padding: 14 }}><ReadError error={pastError} /></div>
              ) : past.length === 0 ? (
                <EmptyState style={{ padding: 14 }} text="No reconciliations yet." />
              ) : past.map((r) => (
                <button key={r.id} className="recon-past-item" onClick={() => enterReviewMode(r)}>
                  <div className="recon-past-item-top">
                    <strong>{fmtDate(r.statement_date)}</strong>
                    <span style={{ fontVariantNumeric: 'tabular-nums' }}>{fmtMoney(r.statement_balance)}</span>
                  </div>
                  <div className="recon-past-item-sub">
                    diff {fmtMoney(r.difference)}{r.notes ? ` · ${r.notes.slice(0, 60)}` : ''}
                  </div>
                </button>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Lines list */}
      {unrecLoading ? (
        <Loading style={{ padding: 16 }}>Loading lines…</Loading>
      ) : unreconciled.length === 0 ? (
        <EmptyState style={{ marginTop: 24 }}
          title="The books match the bank."
          text="Nothing left to reconcile." />
      ) : (
        <div className="recon-table-wrap">
          <table className="recon-table">
            <thead>
              <tr>
                <th scope="col" style={{ width: 36 }}></th>
                <th scope="col" style={{ width: 110 }}>Date</th>
                <th scope="col">Description</th>
                <th scope="col" style={{ width: 100, textAlign: 'right' }}>Debit</th>
                <th scope="col" style={{ width: 100, textAlign: 'right' }}>Credit</th>
                <th scope="col" style={{ width: 110 }}></th>
              </tr>
            </thead>
            <tbody>
              {filteredLines.map((l) => {
                const ticked = isChecked(l);
                const matched = highlightToken
                  && (l.entry.description || '').toLowerCase().includes(highlightToken.toLowerCase());
                return (
                  <tr
                    key={l.id}
                    className={`recon-row${ticked ? ' recon-row-ticked' : ''}${matched ? ' recon-row-highlight' : ''}`}
                    onClick={() => toggleLine(l)}
                  >
                    <td onClick={(e) => { e.stopPropagation(); if (e.target === e.currentTarget) toggleLine(l); }}>
                      <input
                        type="checkbox"
                        className="recon-checkbox"
                        aria-label={reconLineLabel(l)}
                        checked={ticked}
                        onChange={() => toggleLine(l)}
                      />
                    </td>
                    <td style={{ fontVariantNumeric: 'tabular-nums', fontSize: 12 }}>{fmtDate(l.entry.entry_date)}</td>
                    <td style={{ fontSize: 12 }} onMouseUp={onDescSelect}>
                      <LedgerSourceLink sourceType={l.entry.source_type} sourceId={l.entry.source_id} toast={toast}>
                        {renderWithHighlight(l.entry.description, highlightToken)}
                      </LedgerSourceLink>
                    </td>
                    <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{Number(l.debit) > 0 ? fmtMoney(l.debit) : ''}</td>
                    <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{Number(l.credit) > 0 ? fmtMoney(l.credit) : ''}</td>
                    <td onClick={(e) => e.stopPropagation()} style={{ textAlign: 'right' }}>
                      <button className="recon-tickto" onClick={() => tickToHere(l)} title="Set as-of to this date and auto-tick through here">Tick to here</button>
                    </td>
                  </tr>
                );
              })}
              {filteredLines.length === 0 && (
                <tr><td colSpan={6} className="text-muted" style={{ padding: 16, textAlign: 'center' }}>No lines match "{search}".</td></tr>
              )}
            </tbody>
          </table>
        </div>
      )}

      {/* Notes */}
      {unreconciled.length > 0 && (
        <Field label="Notes (optional)" style={{ marginTop: 16, marginBottom: 80 }}>{(id) => (<>
          <textarea id={id} className="form-textarea" rows={2} maxLength={1000} value={notes} onChange={(e) => setNotes(e.target.value)} />
        </>)}</Field>
      )}

      {csvOpen && (
        <CsvImportModal
          unreconciled={unreconciled}
          onClose={() => setCsvOpen(false)}
          onApply={applyCsvAutoMatch}
        />
      )}
    </div>
  );
}

/**
 * Read a bank CSV and sort every one of its rows into a bucket: matched, ambiguous,
 * unmatched or skipped. Returns `{ error }` for a file with no rows or without both a Date
 * and an Amount column. Pure, so the modal renders this and computes nothing of its own.
 *
 * A row matches a ledger line when the CSV amount equals the line's net (debit minus credit)
 * and the two dates are within seven days. One candidate is a match, several is ambiguous,
 * none is unmatched, and a line is claimed at most once across the whole file.
 *
 * @invariant matched + ambiguous + unmatched + skipped === dataRowCount. Every row of
 *            the file lands in exactly one bucket, so the tiles add up to what was
 *            imported.
 * @gotcha parseCsv drops entirely blank lines, so dataRowCount is the number of rows a person
 *         would count in the file rather than a count of newlines.
 */
export function summariseBankCsv(text, unreconciled) {
  const rows = parseCsv(text);
  if (!rows.length) return { error: 'No rows found.' };
  const headers = rows[0].map((h) => h.trim());
  const lower = headers.map((h) => h.toLowerCase());
  const dateCol = lower.findIndex((h) => /date/.test(h));
  const amountCol = lower.findIndex((h) => /amount/.test(h));
  if (dateCol < 0 || amountCol < 0) {
    return { error: 'Need columns named "Date" and "Amount" (case-insensitive).' };
  }

  // Every row is either read or skipped with a reason. Nothing may leave this loop
  // uncounted, or the tiles describe a smaller file than the one on disk.
  const dataRows = [];
  const skipped = [];
  rows.slice(1).forEach((r, i) => {
    // Row 1 is the header, so the first data row is row 2: the number the person sees in the
    // spreadsheet, which is the only number that helps them find it.
    const rowNumber = i + 2;
    const rawDate = String(r[dateCol] ?? '').trim();
    const rawAmount = String(r[amountCol] ?? '').trim();
    if (!rawDate) { skipped.push({ rowNumber, reason: 'No date', raw: r }); return; }
    if (!rawAmount) { skipped.push({ rowNumber, reason: 'No amount', raw: r }); return; }
    const date = parseFlexibleDate(rawDate);
    if (!date) { skipped.push({ rowNumber, reason: `Date not recognised: "${rawDate}"`, raw: r }); return; }
    // Finiteness is tested BEFORE round2, which by contract never returns NaN: rounding
    // first turns an unreadable amount into a clean 0.00 that can then match a zero line.
    // @see round2 in utils/format.js
    const parsedAmount = parseFloat(rawAmount.replace(/[,$]/g, ''));
    if (!Number.isFinite(parsedAmount)) { skipped.push({ rowNumber, reason: `Amount not recognised: "${rawAmount}"`, raw: r }); return; }
    dataRows.push({ rowNumber, date, amount: round2(parsedAmount), raw: r });
  });
  const dataRowCount = rows.length - 1;

  const used = new Set();
  const matched = [];
  const ambiguous = [];
  const unmatched = [];
  for (const csv of dataRows) {
    const candidates = unreconciled.filter((l) => {
      if (used.has(l.id)) return false;
      const net = round2(Number(l.debit || 0) - Number(l.credit || 0));
      if (Math.abs(net - csv.amount) > 0.005) return false;
      const dDiff = Math.abs(dayDiff(csv.date, l.entry.entry_date));
      return dDiff <= 7;
    });
    if (candidates.length === 1) {
      matched.push({ csv, line: candidates[0] });
      used.add(candidates[0].id);
    } else if (candidates.length > 1) {
      ambiguous.push({ csv, candidates });
    } else {
      unmatched.push(csv);
    }
  }
  return { headers, dateCol, amountCol, dataRowCount, rows: dataRows, skipped, matched, ambiguous, unmatched };
}

/**
 * Bank-CSV import modal for reconciliation. Pastes or uploads a CSV, hands it to
 * summariseBankCsv and reports the four buckets against the file's own row count.
 *
 * @gotcha only one-to-one matches auto-apply; a row matching several ledger lines is
 *         Ambiguous and is ticked by hand. "Skipped" means something else and always carries
 *         a reason: a row the parser could not read at all.
 */
function CsvImportModal({ unreconciled, onClose, onApply }) {
  const [text, setText] = useState('');
  // The refusal reason for a file that yields nothing usable: the browser could not read it
  // off disk at all, or the text has no rows or no Date/Amount column. Everything else the
  // modal shows lives on `results`.
  const [parseError, setParseError] = useState('');
  const [results, setResults] = useState(null); // summariseBankCsv's return
  const [busy, setBusy] = useState(false);

  function parse() {
    setBusy(true);
    const summary = summariseBankCsv(text, unreconciled);
    if (summary.error) { setParseError(summary.error); setResults(null); }
    else { setParseError(''); setResults(summary); }
    setBusy(false);
  }

  function apply() {
    const ids = [];
    for (const m of results.matched) ids.push(m.line.id);
    onApply(ids);
  }

  function onFile(e) {
    const f = e.target.files?.[0];
    if (!f) return;
    const reader = new FileReader();
    // Both endings are bound. With only `onload`, a file the browser cannot open left the
    // textarea empty, which left Parse disabled, so there was not even a refused click: the
    // person retried the same file believing they had mis-clicked.
    reader.onload = () => { setParseError(''); setText(String(reader.result || '')); };
    reader.onerror = () => setParseError(`Could not read "${f.name}". Try saving it again as CSV, or paste the rows below.`);
    reader.readAsText(f);
  }

  return (
    <Modal
      title="Import bank CSV"
      size="lg"
      onClose={onClose}
      closeLabel="Close"
    >
        <div className="modal-body">
          {!results && (
            <>
              <div className="text-muted" style={{ fontSize: 12, marginBottom: 12 }}>
                Paste or upload a CSV with at least <code>Date</code> and <code>Amount</code> columns. We will match each row to an unreconciled line by exact amount within ±7 days.
              </div>
              <div style={{ marginBottom: 12 }}>
                <input type="file" aria-label="Choose a bank CSV file" accept=".csv,text/csv" onChange={onFile} />
              </div>
              <textarea
                className="form-textarea"
                rows={10}
                aria-label="Paste bank CSV rows"
                placeholder="Date,Description,Amount
2025-07-15,Reward payout,926.65
…"
                value={text}
                onChange={(e) => setText(e.target.value)}
                style={{ fontFamily: 'var(--font-mono)', fontSize: 12 }}
              />
              {parseError && <Feedback value={parseError} style={{ marginTop: 8 }} />}
            </>
          )}

          {results && (
            <>
              {/* Four tiles, and the fourth is what P54 bought: rows the importer could not
                  read used to vanish between the file and the count. All four show even at
                  zero, because the caption below claims they add up to the file and a sum with
                  a term missing proves nothing. A zero steps back rather than shouting. The
                  shared `.stats-row` carries the phone rule, two columns and never four
                  crushed ones. */}
              <div className="stats-row" style={{ gridTemplateColumns: 'repeat(4, 1fr)', gap: 8, marginBottom: 8 }}>
                <StatTile label="MATCHED" value={results.matched.length} color={results.matched.length > 0 ? 'stat-green' : 'stat-muted'} />
                <StatTile label="AMBIGUOUS" value={results.ambiguous.length} color={results.ambiguous.length > 0 ? 'stat-orange' : 'stat-muted'} />
                <StatTile label="UNMATCHED" value={results.unmatched.length} color="stat-muted" />
                <StatTile label="SKIPPED" value={results.skipped.length} color={results.skipped.length > 0 ? 'stat-red' : 'stat-muted'} />
              </div>
              <div className="text-muted" style={{ fontSize: 12, marginBottom: 16 }}>
                {results.dataRowCount === 0
                  ? 'The file has a header row and no data rows.'
                  : `Read from ${results.dataRowCount} row${results.dataRowCount === 1 ? '' : 's'} in the file. Every one of them is counted above.`}
              </div>
              {/* The lists run in order of what each ASKS of the reader, not in tile order:
                  leave and fix the file, tick by hand here, nothing to do, audit trail last.
                  Skipped was already open for that reason and sat under two other lists,
                  where open bought it nothing. Colour rather than position links a list to
                  its tile, since the two now run in opposite orders. */}
              {results.skipped.length > 0 && (
                <details style={{ marginBottom: 12 }} open>
                  <summary style={{ cursor: 'pointer', fontSize: 12 }}>{results.skipped.length} skipped row{results.skipped.length === 1 ? '' : 's'}, not imported</summary>
                  <ul style={{ margin: '6px 0 0 16px', fontSize: 12, color: 'var(--muted)' }}>
                    {results.skipped.slice(0, 20).map((s) => (
                      <li key={s.rowNumber}>Row {s.rowNumber} · {s.reason}</li>
                    ))}
                    {results.skipped.length > 20 && <li>… and {results.skipped.length - 20} more</li>}
                  </ul>
                </details>
              )}
              {results.ambiguous.length > 0 && (
                <div className="text-muted" style={{ fontSize: 12, marginBottom: 8 }}>
                  Ambiguous rows match more than one ledger line, so none of them is applied: tick those by hand in the main list.
                </div>
              )}
              {results.unmatched.length > 0 && (
                <details style={{ marginBottom: 12 }}>
                  <summary style={{ cursor: 'pointer', fontSize: 12 }}>{results.unmatched.length} unmatched row{results.unmatched.length === 1 ? '' : 's'}</summary>
                  <ul style={{ margin: '6px 0 0 16px', fontSize: 12, color: 'var(--muted)' }}>
                    {results.unmatched.slice(0, 20).map((u) => (
                      <li key={u.rowNumber}>Row {u.rowNumber} · read as {fmtDate(u.date)} · {fmtMoney(u.amount)}</li>
                    ))}
                    {results.unmatched.length > 20 && <li>… and {results.unmatched.length - 20} more</li>}
                  </ul>
                </details>
              )}
              {results.matched.length > 0 && (
                <details style={{ marginBottom: 12 }}>
                  {/* The parsed date, not the raw cell: a bank that writes d/m/y is read as
                      m/d/y here, and this list is the only place that shows it. */}
                  <summary style={{ cursor: 'pointer', fontSize: 12 }}>{results.matched.length} matched row{results.matched.length === 1 ? '' : 's'}</summary>
                  <ul style={{ margin: '6px 0 0 16px', fontSize: 12, color: 'var(--muted)' }}>
                    {results.matched.slice(0, 20).map((m) => (
                      <li key={m.csv.rowNumber}>
                        Row {m.csv.rowNumber} · read as {fmtDate(m.csv.date)} · {fmtMoney(m.csv.amount)} &rarr; {fmtDate(m.line.entry.entry_date)} {m.line.entry.description}
                      </li>
                    ))}
                    {results.matched.length > 20 && <li>… and {results.matched.length - 20} more</li>}
                  </ul>
                </details>
              )}
            </>
          )}
        </div>
        <div className="modal-footer">
          {!results ? (
            <button className="btn btn-primary" disabled={!text.trim() || busy} onClick={parse}>{busy ? 'Parsing…' : 'Parse'}</button>
          ) : (
            <>
              <button className="btn btn-ghost" onClick={() => { setResults(null); setParseError(''); }}>Back</button>
              <button className="btn btn-primary" onClick={apply} disabled={results.matched.length === 0}>
                Apply {results.matched.length} match{results.matched.length === 1 ? '' : 'es'}
              </button>
            </>
          )}
        </div>
    </Modal>
  );
}

/** Tolerant CSV parser: handles quoted fields with embedded commas, quotes, and newlines. */
function parseCsv(text) {
  const rows = []; let row = []; let cur = ''; let inQ = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (inQ) {
      if (ch === '"' && text[i + 1] === '"') { cur += '"'; i++; }
      else if (ch === '"') inQ = false;
      else cur += ch;
    } else {
      if (ch === '"') inQ = true;
      else if (ch === ',') { row.push(cur); cur = ''; }
      else if (ch === '\r') { /* skip */ }
      else if (ch === '\n') { row.push(cur); rows.push(row); row = []; cur = ''; }
      else cur += ch;
    }
  }
  if (cur.length || row.length) { row.push(cur); rows.push(row); }
  return rows.filter((r) => r.some((c) => c && c.trim()));
}

/** Normalise an ISO (yyyy-mm-dd) or US (m/d/yy[yy]) date string to yyyy-mm-dd, or null. */
function parseFlexibleDate(s) {
  const t = String(s).trim();
  // ISO yyyy-mm-dd
  let m = t.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) return `${m[1]}-${m[2].padStart(2, '0')}-${m[3].padStart(2, '0')}`;
  // US m/d/yyyy or m/d/yy
  m = t.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})/);
  if (m) {
    const yy = m[3].length === 2 ? `20${m[3]}` : m[3];
    return `${yy}-${m[1].padStart(2, '0')}-${m[2].padStart(2, '0')}`;
  }
  return null;
}

function dayDiff(a, b) {
  const da = new Date(a + 'T00:00:00').getTime();
  const db = new Date(b + 'T00:00:00').getTime();
  return Math.round((da - db) / 86400000);
}
