// ── Institution logos ──────────────────────────────────────────────────────────
const INSTITUTION_MAP = [
  { matches: n => n.includes('chase'),                                        Logo: ChaseLogo },
  { matches: n => n.includes('vanguard'),                                     Logo: VanguardLogo },
  { matches: n => n.includes('fidelity'),                                     Logo: FidelityLogo },
  { matches: n => n.includes('schwab'),                                       Logo: SchwabLogo },
  { matches: n => n.includes('bofa') || n.includes('bank of america'),        Logo: BofALogo },
];

export function InstitutionLogo({ institution, size = 24 }) {
  if (!institution) return <GenericInstitutionLogo size={size} />;
  const n = institution.toLowerCase();
  const entry = INSTITUTION_MAP.find(p => p.matches(n));
  if (entry) return <entry.Logo size={size} />;
  return <GenericInstitutionLogo size={size} label={institution.slice(0, 2).toUpperCase()} />;
}

