/**
 * components/admin/PlatformSetupView.js: admin Config view for platforms, creator
 * platform accounts, their payment addresses, and deliverable types.
 *
 * Manages the platform catalog plus per-creator account handles (with reward and
 * payment-address sub-modals). Substantial view.
 *
 * @see schemas/SCHEMA.sql (platform_accounts, platform_payment_addresses)
 */
import React, { useState, useEffect } from 'react';
import { supabase } from '../../lib/supabase';
import { PlatformLogo, GenericPlatformLogo } from '../shared/PlatformLogo';
import HelpIcon from '../shared/HelpIcon';
import { humanizeError } from '../../utils/errors';
import Feedback from '../shared/Feedback';
import { useConfirm } from '../shared/ConfirmDialog';
import { useCreators } from '../../hooks/useCreators';
import { mutate } from '../../utils/mutate';
import { useToast } from '../shared/Toast';
import ReadError from '../shared/ReadError';
import EmptyState from '../shared/EmptyState';
import Modal, { ModalClose } from '../shared/Modal';
import Field from '../shared/Field';
import Loading from '../shared/Loading';
import SubmitButton from '../shared/SubmitButton';
import { useLoadState } from '../../hooks/useLoadState';
import Refreshing from '../shared/Refreshing';

/** Build a public profile URL for a known platform; null for unrecognized ones. */
function accountUrl(platform, username) {
  const map = {
    tiktok:    u => `https://www.tiktok.com/@${u}`,
    instagram: u => `https://www.instagram.com/${u}`,
    youtube:   u => `https://www.youtube.com/@${u}`,
    x:         u => `https://x.com/${u}`,
    twitter:   u => `https://x.com/${u}`,
    snapchat:  u => `https://www.snapchat.com/add/${u}`,
    pinterest: u => `https://www.pinterest.com/${u}`,
    facebook:  u => `https://www.facebook.com/${u}`,
    linkedin:  u => `https://www.linkedin.com/in/${u}`,
    twitch:    u => `https://www.twitch.tv/${u}`,
  };
  const fn = map[platform];
  return fn ? fn(username) : null;
}

// ── Main view ──────────────────────────────────────────────────────────────────
export default function PlatformSetupView() {
  const toast = useToast();
  const askConfirm = useConfirm();
  const [platforms, setPlatforms]     = useState([]);
  const [usageCounts, setUsageCounts] = useState({});
  const [accounts, setAccounts]       = useState([]);
  const { creators }                  = useCreators();
  const [delivTypes, setDelivTypes]   = useState([]);
  const [delivUsage, setDelivUsage]   = useState({});
  const { loading, refreshing, begin, end } = useLoadState();
  // The third state. Three of the six reads below are usage counts, and a usage count is what
  // decides whether Delete is offered: a refused one reads as "nothing uses this" on a
  // platform every deliverable is filed under.
  const [loadError, setLoadError] = useState(null);

  const [showPlatformModal, setShowPlatformModal] = useState(false);
  const [showAccountModal, setShowAccountModal]   = useState(false);
  const [editingAccount, setEditingAccount]       = useState(null);
  const [defaultPlatform, setDefaultPlatform]     = useState('');
  const [showTypeModal, setShowTypeModal]         = useState(false);
  const [editingType, setEditingType]             = useState(null);

  const [paymentAccount, setPaymentAccount] = useState(null);
  const [paymentCounts, setPaymentCounts]   = useState({});

  useEffect(() => { fetchAll(); }, []);

  async function fetchAll() {
    begin();
    setLoadError(null);
    const [pRes, dRes, aRes, tRes, tuRes, ppRes] = await Promise.all([
      supabase.from('platforms').select('*').order('name'),
      supabase.from('campaign_deliverables').select('platform_id').not('platform_id', 'is', null),
      supabase.from('platform_accounts').select('*, profile:profiles(full_name, creator_name)').order('platform').order('created_at'),
      supabase.from('deliverable_types').select('*').order('name'),
      supabase.from('campaign_deliverables').select('deliverable_type_id').not('deliverable_type_id', 'is', null),
      supabase.from('platform_payment_addresses').select('platform_account_id'),
    ]);
    const readError = pRes.error || dRes.error || aRes.error || tRes.error || tuRes.error || ppRes.error;
    if (readError) {
      setLoadError(readError);
      setPlatforms([]);
      setAccounts([]);
      setDelivTypes([]);
      setUsageCounts({});
      setDelivUsage({});
      setPaymentCounts({});
      end();
      return;
    }
    setPlatforms(pRes.data || []);
    const counts = {};
    for (const d of (dRes.data || [])) counts[d.platform_id] = (counts[d.platform_id] || 0) + 1;
    setUsageCounts(counts);
    setAccounts(aRes.data || []);
    setDelivTypes(tRes.data || []);
    const typeCounts = {};
    for (const d of (tuRes.data || [])) typeCounts[d.deliverable_type_id] = (typeCounts[d.deliverable_type_id] || 0) + 1;
    setDelivUsage(typeCounts);
    const pCounts = {};
    for (const p of (ppRes.data || [])) pCounts[p.platform_account_id] = (pCounts[p.platform_account_id] || 0) + 1;
    setPaymentCounts(pCounts);
    end();
  }

  async function togglePlatform(p) {
    const { error } = await mutate(supabase.from('platforms').update({ is_active: !p.is_active }).eq('id', p.id));
    if (error) { toast.error(error); return; }
    fetchAll();
  }

  async function deletePlatform(p) {
    if (!(await askConfirm({ title: `Delete "${p.name}"?`, body: 'This cannot be undone.', danger: true }))) return;
    const { error } = await mutate(supabase.from('platforms').delete().eq('id', p.id));
    if (error) { toast.error(error); return; }
    fetchAll();
  }

  async function toggleAccount(a) {
    const { error } = await mutate(supabase.from('platform_accounts').update({ is_active: !a.is_active }).eq('id', a.id));
    if (error) { toast.error(error); return; }
    fetchAll();
  }

  function openLinkAccount(platformName) {
    setDefaultPlatform(platformName.toLowerCase());
    setEditingAccount(null);
    setShowAccountModal(true);
  }

  function openEditAccount(a) {
    setDefaultPlatform(a.platform);
    setEditingAccount(a);
    setShowAccountModal(true);
  }

  async function toggleType(t) {
    const { error } = await mutate(supabase.from('deliverable_types').update({ is_active: !t.is_active }).eq('id', t.id));
    if (error) { toast.error(error); return; }
    fetchAll();
  }

  async function deleteType(t) {
    if (!(await askConfirm({ title: `Delete "${t.name}"?`, body: 'This cannot be undone.', danger: true }))) return;
    const { error } = await mutate(supabase.from('deliverable_types').delete().eq('id', t.id));
    if (error) { toast.error(error); return; }
    fetchAll();
  }

  if (loading) return <div className="page"><Loading /></div>;
  if (loadError) return <div className="page"><ReadError error={loadError} onRetry={fetchAll} /></div>;

  // Group accounts by platform name (platform_accounts.platform is lowercase)
  const accountsByPlatform = {};
  const orphanAccounts = [];
  for (const a of accounts) {
    const match = platforms.find(p => p.name.toLowerCase() === a.platform);
    if (match) {
      if (!accountsByPlatform[match.id]) accountsByPlatform[match.id] = [];
      accountsByPlatform[match.id].push(a);
    } else {
      orphanAccounts.push(a);
    }
  }

  return (
    <div className="page">
      <div className="page-header">
        <div>
          <h1 className="page-title">PLATFORM SETUP<HelpIcon slug="platform-setup" /></h1>
          <div className="page-subtitle">Platforms, account links, and deliverable types<Refreshing on={refreshing} /></div>
        </div>
        <div className="flex gap-8">
          <button className="btn btn-ghost" onClick={() => { setEditingType(null); setShowTypeModal(true); }}>+ Add Type</button>
          <button className="btn btn-ghost" onClick={() => setShowPlatformModal(true)}>+ Add Platform</button>
          <button className="btn btn-primary" onClick={() => { setDefaultPlatform(''); setEditingAccount(null); setShowAccountModal(true); }}>+ Link Account</button>
        </div>
      </div>

      {platforms.length === 0 ? (
        <EmptyState icon="◻"
          title="No platforms yet"
          text="Add platforms like TikTok, Instagram, YouTube…" />
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>
          {platforms.map(p => {
            const pAccounts = accountsByPlatform[p.id] || [];
            const delivCount = usageCounts[p.id] || 0;
            return (
              <div key={p.id}>
                {/* Platform header */}
                <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '10px 0', borderBottom: '2px solid var(--surface2)', opacity: p.is_active ? 1 : 0.6 }}>
                  <PlatformLogo name={p.name} size={22} />
                  <span style={{ fontWeight: 700, fontSize: 13, letterSpacing: '0.04em' }}>{p.name.toUpperCase()}</span>
                  <span className={`badge ${p.is_active ? 'badge-orange' : 'badge-red-soft'}`}>
                    {p.is_active ? 'Active' : 'Inactive'}
                  </span>
                  {delivCount > 0 && (
                    <span style={{ color: 'var(--muted)', fontSize: 12 }}>
                      {delivCount} deliverable{delivCount !== 1 ? 's' : ''}
                    </span>
                  )}
                  <div style={{ marginLeft: 'auto', display: 'flex', gap: 8 }}>
                    <button className="btn btn-ghost btn-sm" onClick={() => togglePlatform(p)}>
                      {p.is_active ? 'Deactivate' : 'Activate'}
                    </button>
                    {delivCount === 0 && pAccounts.length === 0 && (
                      <button className="btn btn-ghost btn-sm" style={{ color: 'var(--red)' }} onClick={() => deletePlatform(p)}>
                        Delete
                      </button>
                    )}
                    <button className="btn btn-ghost btn-sm" style={{ color: 'var(--blue)' }} onClick={() => openLinkAccount(p.name)}>
                      + Link Account
                    </button>
                  </div>
                </div>

                {/* Accounts table */}
                <div className="table-wrap" style={{ marginTop: 0, borderTopLeftRadius: 0, borderTopRightRadius: 0 }}>
                  <table className="pinned-actions" style={{ width: '100%' }}>
                    <thead>
                      <tr>
                        <th scope="col">Creator</th>
                        <th scope="col">Account</th>
                        <th scope="col"></th>
                        <th scope="col">Status</th>
                        <th scope="col"></th>
                      </tr>
                    </thead>
                    <tbody>
                      {pAccounts.length === 0 ? (
                        <tr>
                          <td colSpan={5} style={{ fontSize: 12, color: 'var(--muted)' }}>No accounts linked</td>
                        </tr>
                      ) : (
                        pAccounts.map(a => {
                          const url = accountUrl(a.platform, a.username);
                          return (
                            <tr key={a.id} style={{ opacity: a.is_active ? 1 : 0.5 }}>
                              <td style={{ fontSize: 13 }}>{a.profile?.creator_name || a.profile?.full_name}</td>
                              <td>
                                {url ? (
                                  <a href={url} target="_blank" rel="noreferrer" className="link" onClick={e => e.stopPropagation()}>
                                    @{a.username}
                                  </a>
                                ) : (
                                  <span>@{a.username}</span>
                                )}
                                {a.display_name && (
                                  <span style={{ color: 'var(--muted)', fontSize: 11, marginLeft: 8 }}>{a.display_name}</span>
                                )}
                              </td>
                              <td>
                                {a.zernio_profile_id && (
                                  <span className="badge badge-sky" title={`Zernio ID: ${a.zernio_profile_id}`}>◷ Scheduling</span>
                                )}
                              </td>
                              <td>
                                <span className={`badge ${a.is_active ? 'badge-orange' : 'badge-red-soft'}`}>
                                  {a.is_active ? 'Active' : 'Inactive'}
                                </span>
                              </td>
                              <td>
                                <div className="flex gap-8">
                                  <button className="btn btn-ghost btn-sm" onClick={() => openEditAccount(a)}>Edit</button>
                                  <button className="btn btn-ghost btn-sm" onClick={() => toggleAccount(a)}>
                                    {a.is_active ? 'Deactivate' : 'Activate'}
                                  </button>
                                  <button className="btn btn-ghost btn-sm" style={{ color: paymentCounts[a.id] ? 'var(--blue)' : 'var(--muted)' }} onClick={() => setPaymentAccount(a)}>
                                    {paymentCounts[a.id] ? `Payment (${paymentCounts[a.id]})` : 'Payment'}
                                  </button>
                                </div>
                              </td>
                            </tr>
                          );
                        })
                      )}
                    </tbody>
                  </table>
                </div>
              </div>
            );
          })}

          {/* Orphaned accounts */}
          {orphanAccounts.length > 0 && (
            <div>
              <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '10px 0', borderBottom: '2px solid var(--surface2)' }}>
                <GenericPlatformLogo size={22} label="?" />
                <span style={{ fontWeight: 700, fontSize: 13, letterSpacing: '0.04em', color: 'var(--muted)' }}>OTHER</span>
                <span style={{ fontSize: 12, color: 'var(--muted)' }}>Platform not defined above</span>
              </div>
              <div className="table-wrap" style={{ marginTop: 0, borderTopLeftRadius: 0, borderTopRightRadius: 0 }}>
                <table className="pinned-actions" style={{ width: '100%' }}>
                  <thead>
                    <tr>
                      <th scope="col">Creator</th>
                      <th scope="col">Account</th>
                      <th scope="col"></th>
                      <th scope="col">Status</th>
                      <th scope="col"></th>
                    </tr>
                  </thead>
                  <tbody>
                    {orphanAccounts.map(a => {
                      const url = accountUrl(a.platform, a.username);
                      return (
                        <tr key={a.id} style={{ opacity: a.is_active ? 1 : 0.5 }}>
                          <td style={{ fontSize: 13 }}>
                            {a.profile?.creator_name || a.profile?.full_name}
                            <span style={{ marginLeft: 8, fontSize: 11, color: 'var(--muted)' }}>({a.platform})</span>
                          </td>
                          <td>
                            {url ? (
                              <a href={url} target="_blank" rel="noreferrer" className="link">@{a.username}</a>
                            ) : (
                              <span>@{a.username}</span>
                            )}
                          </td>
                          <td />
                          <td>
                            <span className={`badge ${a.is_active ? 'badge-orange' : 'badge-red-soft'}`}>
                              {a.is_active ? 'Active' : 'Inactive'}
                            </span>
                          </td>
                          <td>
                            <div className="flex gap-8">
                              <button className="btn btn-ghost btn-sm" onClick={() => openEditAccount(a)}>Edit</button>
                              <button className="btn btn-ghost btn-sm" onClick={() => toggleAccount(a)}>
                                {a.is_active ? 'Deactivate' : 'Activate'}
                              </button>
                              <button className="btn btn-ghost btn-sm" style={{ color: 'var(--blue)' }} onClick={() => setPaymentAccount(a)}>
                                Payment
                              </button>
                            </div>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>
      )}

      {/* ── Deliverable Types ── */}
      <div style={{ marginTop: 56, paddingTop: 32, borderTop: '2px solid var(--border)' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 16 }}>
          <div style={{ width: 3, height: 18, background: 'var(--blue)', borderRadius: 2, flexShrink: 0 }} />
          <span style={{ fontSize: 13, fontWeight: 700, letterSpacing: '0.06em', textTransform: 'uppercase' }}>Deliverable Types</span>
          <span style={{ fontSize: 12, color: 'var(--muted)' }}>Platform-independent content formats</span>
        </div>
        {delivTypes.length === 0 ? (
          <EmptyState
            title="No deliverable types yet"
            text="Add types like Video, Reel, Story, Carousel…" />
        ) : (
          <div className="table-wrap">
            <table className="pinned-actions" style={{ width: '100%' }}>
              <thead>
                <tr><th scope="col">Type</th><th scope="col">Description</th><th scope="col">Usage</th><th scope="col">Status</th><th scope="col"></th></tr>
              </thead>
              <tbody>
                {delivTypes.map(t => {
                  const count = delivUsage[t.id] || 0;
                  return (
                    <tr key={t.id} style={{ opacity: t.is_active ? 1 : 0.5 }}>
                      <td style={{ fontWeight: 500 }}>{t.name}</td>
                      <td style={{ fontSize: 12, color: 'var(--muted)' }}>{t.description || <span className="text-muted">—</span>}</td>
                      <td style={{ fontSize: 12, color: 'var(--muted)' }}>
                        {count > 0 ? `${count} deliverable${count !== 1 ? 's' : ''}` : <span className="text-muted">—</span>}
                      </td>
                      <td>
                        <span className={`badge ${t.is_active ? 'badge-orange' : 'badge-red-soft'}`}>
                          {t.is_active ? 'Active' : 'Inactive'}
                        </span>
                      </td>
                      <td>
                        <div className="flex gap-8">
                          <button className="btn btn-ghost btn-sm" onClick={() => { setEditingType(t); setShowTypeModal(true); }}>Edit</button>
                          <button className="btn btn-ghost btn-sm" onClick={() => toggleType(t)}>
                            {t.is_active ? 'Deactivate' : 'Activate'}
                          </button>
                          {count === 0 && (
                            <button className="btn btn-ghost btn-sm" style={{ color: 'var(--red)' }} onClick={() => deleteType(t)}>Delete</button>
                          )}
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {paymentAccount && (
        <PaymentAddressModal
          account={paymentAccount}
          onClose={() => { setPaymentAccount(null); fetchAll(); }}
        />
      )}

      {showPlatformModal && (
        <AddPlatformModal
          currentPlatforms={platforms}
          onClose={() => setShowPlatformModal(false)}
          onSaved={() => { setShowPlatformModal(false); fetchAll(); }}
        />
      )}

      {showAccountModal && (
        <PlatformAccountModal
          account={editingAccount}
          creators={creators}
          existingAccounts={accounts}
          platforms={platforms.filter(p => p.is_active)}
          defaultPlatform={defaultPlatform}
          onClose={() => setShowAccountModal(false)}
          onSaved={() => { setShowAccountModal(false); fetchAll(); }}
        />
      )}

      {showTypeModal && (
        <DeliverableTypeModal
          type={editingType}
          onClose={() => setShowTypeModal(false)}
          onSaved={() => { setShowTypeModal(false); fetchAll(); }}
        />
      )}
    </div>
  );
}

// ── Add platform modal ─────────────────────────────────────────────────────────
function AddPlatformModal({ onClose, onSaved, currentPlatforms }) {
  const toast = useToast();
  const [name, setName]     = useState('');
  const [saving, setSaving] = useState(false);
  const [error, setError]   = useState('');

  async function save() {
    const trimmed = name.trim();
    if (!trimmed) { setError('Name is required.'); return; }
    if (currentPlatforms.some(p => p.name.toLowerCase() === trimmed.toLowerCase())) {
      setError('A platform with this name already exists.'); return;
    }
    setSaving(true);
    const { error: err } = await supabase.from('platforms').insert({ name: trimmed });
    if (err) { setError(humanizeError(err)); setSaving(false); return; }
    toast.success('Platform added');
    onSaved();
  }

  return (
    <Modal
      title="ADD PLATFORM"
      size="sm"
      onClose={onClose}
    >
        <div className="modal-body">
          {error && <Feedback value={error} style={{ marginBottom: 16 }} />}
          {name.trim() && (
            <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 16, padding: '10px 14px', background: 'var(--surface2)', borderRadius: 8 }}>
              <PlatformLogo name={name.trim()} size={36} />
              <span style={{ fontSize: 12, color: 'var(--muted)' }}>Logo preview</span>
            </div>
          )}
          <Field label="Platform Name *">{(id) => (<>
            <input id={id}
              className="form-input"
              value={name}
              autoFocus
              onChange={e => { setName(e.target.value); setError(''); }}
              onKeyDown={e => e.key === 'Enter' && save()}
              placeholder="TikTok, Instagram, YouTube…"
            />
            <div style={{ fontSize: 11, color: 'var(--dim)', marginTop: 6 }}>
              Logos auto-match for TikTok, Instagram, YouTube, X, Snapchat, Pinterest, Facebook, LinkedIn, Twitch, Spotify
            </div>
          </>)}</Field>
        </div>
        <div className="modal-footer">
          <ModalClose className="btn btn-ghost">Cancel</ModalClose>
          <button className="btn btn-primary" onClick={save} disabled={saving || !name.trim()}>
            {saving ? 'Adding…' : 'Add Platform'}
          </button>
        </div>
    </Modal>
  );
}

// ── Link / edit account modal ──────────────────────────────────────────────────
function PlatformAccountModal({ account, creators, existingAccounts, platforms, defaultPlatform, onClose, onSaved }) {
  const toast = useToast();
  const platformOptions = platforms.map(p => ({ value: p.name.toLowerCase(), label: p.name }));
  const [form, setForm] = useState({
    profile_id:        account?.profile_id        || '',
    platform:          account?.platform          || defaultPlatform || 'tiktok',
    username:          account?.username          || '',
    display_name:      account?.display_name      || '',
    zernio_profile_id: account?.zernio_profile_id || '',
  });
  const [saving, setSaving] = useState(false);
  const [error, setError]   = useState('');

  const linkedPlatforms = existingAccounts
    .filter(a => a.profile_id === form.profile_id && a.id !== account?.id)
    .map(a => a.platform);

  const availableOptions = platformOptions.filter(p => !linkedPlatforms.includes(p.value));

  async function save() {
    if (!form.profile_id || !form.platform || !form.username.trim()) {
      setError('Creator, platform, and username are required.');
      return;
    }
    setSaving(true);
    setError('');
    const payload = {
      profile_id:        form.profile_id,
      platform:          form.platform,
      username:          form.username.trim().replace(/^@/, ''),
      display_name:      form.display_name.trim() || null,
      zernio_profile_id: form.zernio_profile_id.trim() || null,
    };
    let err;
    if (account) {
      ({ error: err } = await supabase.from('platform_accounts').update(payload).eq('id', account.id));
    } else {
      ({ error: err } = await supabase.from('platform_accounts').insert(payload));
    }
    if (err) {
      setError(err.code === '23505'
        ? `This creator already has a ${form.platform} account linked.`
        : err.message);
      setSaving(false);
      return;
    }
    toast.success(account ? 'Account updated' : 'Account added');
    onSaved();
  }

  return (
    <Modal
      title={account ? 'EDIT ACCOUNT' : 'LINK PLATFORM ACCOUNT'}
      size="sm"
      onClose={onClose}
    >
        <div className="modal-body">
          {error && <Feedback value={error} style={{ marginBottom: 16 }} />}
          <Field label="Creator *">{(id) => (<>
            <select id={id} className="form-select" value={form.profile_id}
              onChange={e => {
                const newProfileId = e.target.value;
                const taken = existingAccounts
                  .filter(a => a.profile_id === newProfileId && a.id !== account?.id)
                  .map(a => a.platform);
                const available = platformOptions.filter(p => !taken.includes(p.value));
                setForm(f => ({
                  ...f,
                  profile_id: newProfileId,
                  platform: taken.includes(f.platform)
                    ? (available[0]?.value || f.platform)
                    : f.platform,
                }));
              }}
              disabled={!!account}>
              <option value="">Select creator…</option>
              {creators.map(c => <option key={c.id} value={c.id}>{c.creator_name || c.full_name}</option>)}
            </select>
          </>)}</Field>
          <Field label="Platform *">{(id) => (<>
            <select id={id} className="form-select" value={form.platform}
              onChange={e => setForm(f => ({ ...f, platform: e.target.value }))}
              disabled={!!account}>
              {availableOptions.map(p => <option key={p.value} value={p.value}>{p.label}</option>)}
            </select>
          </>)}</Field>
          <Field label="Username * (without @)">{(id) => (<>
            <input id={id} className="form-input" value={form.username}
              onChange={e => setForm(f => ({ ...f, username: e.target.value.replace(/^@/, '') }))}
              placeholder="mysthegreat" />
          </>)}</Field>
          <Field label="Display Name (optional)">{(id) => (<>
            <input id={id} className="form-input" value={form.display_name}
              onChange={e => setForm(f => ({ ...f, display_name: e.target.value }))}
              placeholder="Mys The Great" />
          </>)}</Field>
          <Field label="Zernio Profile ID (optional)">{(id) => (<>
            <input id={id} className="form-input" value={form.zernio_profile_id}
              onChange={e => setForm(f => ({ ...f, zernio_profile_id: e.target.value }))}
              placeholder="From Zernio web UI → Profiles"
              maxLength={200} />
            <div style={{ fontSize: 11, color: 'var(--muted)', marginTop: 4 }}>
              Required for scheduled posting. Connect the account in Zernio first, then paste the profile ID here.
            </div>
          </>)}</Field>
        </div>
        <div className="modal-footer">
          <ModalClose className="btn btn-ghost">Cancel</ModalClose>
          <SubmitButton saving={saving} className="btn btn-primary" onClick={save} disabled={saving}>{account ? 'Save' : 'Link Account'}</SubmitButton>
        </div>
    </Modal>
  );
}

// ── Payment address modal ──────────────────────────────────────────────────────

function PaymentAddressModal({ account, onClose }) {
  const toast = useToast();
  const askConfirm = useConfirm();
  const [addresses, setAddresses] = useState([]);
  const [methods, setMethods]     = useState([]);
  const { loading: addrLoading, refreshing: addrRefreshing, begin: addrBegin, end: addrEnd } = useLoadState();
  const [editing, setEditing]     = useState(null); // id of row being edited, or 'new'
  const [form, setForm]           = useState({ method: '', address: '', label: '', fields: {} });
  const [saving, setSaving]       = useState(false);
  const [error, setError]         = useState('');
  /* Two read-error states, not one, because the two reads answer for different things:
   * hub-ui.md scopes the state to what the read feeds. Both hold the RAW supabase error,
   * since ReadError humanizes internally and a second pass collapses the reason.
   * */
  const [addrError, setAddrError]       = useState(null);
  const [methodsError, setMethodsError] = useState(null);

  useEffect(() => { fetchAddresses(); }, []);

  async function fetchAddresses() {
    addrBegin();
    const [{ data: methodRows, error: methodsErr }, { data: addrRows, error: addrErr }] = await Promise.all([
      supabase.from('payment_methods').select('name, fields_schema').eq('is_active', true).order('sort_order').order('name'),
      supabase.from('platform_payment_addresses').select('*').eq('platform_account_id', account.id).order('sort_order').order('created_at'),
    ]);
    setMethodsError(methodsErr || null);
    setAddrError(addrErr || null);
    const activeMethods = (methodRows || []).map(m => ({ name: m.name, fields_schema: m.fields_schema || [] }));
    const activeNames   = activeMethods.map(m => m.name);
    // Guarded rather than left to luck: with no methods `toNormalize` is empty today, so the
    // round is inert on a refusal by accident, and inert by accident is how it comes back the
    // next time somebody edits the filter. Rewriting a stored method against a catalog that
    // did not answer is a write on a guess.
    if (!methodsErr && !addrErr) {
      const toNormalize = (addrRows || []).filter(a => {
        if (activeNames.includes(a.method)) return false;
        return activeNames.some(n => n.toLowerCase() === a.method?.toLowerCase());
      });
      await Promise.all(toNormalize.map(a => {
        const canonical = activeNames.find(n => n.toLowerCase() === a.method.toLowerCase());
        return supabase.from('platform_payment_addresses').update({ method: canonical }).eq('id', a.id);
      }));
    }
    const normalized = (addrRows || []).map(a => {
      const canonical = activeNames.find(n => n.toLowerCase() === a.method?.toLowerCase());
      return canonical ? { ...a, method: canonical } : a;
    });
    setMethods(activeMethods);
    setAddresses(addrErr ? [] : normalized);
    addrEnd();
  }

  function schemaFor(methodName) {
    return methods.find(m => m.name === methodName)?.fields_schema || [];
  }

  function openAdd() {
    setForm({ method: methods[0]?.name || '', address: '', label: '', fields: {} });
    setEditing('new');
    setError('');
  }

  function openEdit(addr) {
    setForm({ method: addr.method, address: addr.address || '', label: addr.label || '', fields: addr.fields || {} });
    setEditing(addr.id);
    setError('');
  }

  function cancelEdit() { setEditing(null); setError(''); }

  async function save() {
    const schema = schemaFor(form.method);
    if (schema.length > 0) {
      const missing = schema.find(f => f.required && !form.fields[f.key]?.trim());
      if (missing) { setError(`${missing.label} is required.`); return; }
    } else {
      if (!form.address.trim()) { setError('Address is required.'); return; }
    }
    setSaving(true); setError('');
    const payload = {
      platform_account_id: account.id,
      method:  form.method,
      address: schema.length > 0 ? null : form.address.trim().slice(0, 500),
      fields:  schema.length > 0
        ? Object.fromEntries(schema.map(f => [f.key, form.fields[f.key]?.trim().slice(0, 500) || null]))
        : null,
      label:   form.label.trim().slice(0, 120) || null,
    };
    if (editing === 'new') {
      const { error: err } = await supabase.from('platform_payment_addresses').insert(payload);
      if (err) { setError(humanizeError(err)); setSaving(false); return; }
    } else {
      const { error: err } = await supabase.from('platform_payment_addresses').update(payload).eq('id', editing);
      if (err) { setError(humanizeError(err)); setSaving(false); return; }
    }
    setSaving(false);
    setEditing(null);
    fetchAddresses();
  }

  async function setPreferred(id) {
    await supabase.from('platform_payment_addresses')
      .update({ is_preferred: false })
      .eq('platform_account_id', account.id);
    await supabase.from('platform_payment_addresses')
      .update({ is_preferred: true })
      .eq('id', id);
    fetchAddresses();
  }

  /**
   * Delete one payment address, after naming it the way the row on screen does.
   *
   * @param {object} addr the address row, NOT its id. An account can hold several and the
   *        rows differ only by a value the confirm was hiding.
   */
  async function remove(addr) {
    // Same order the row renders in: the schema's own fields first, then the flat address.
    const shown = schemaFor(addr.method).map(f => addr.fields?.[f.key]).find(Boolean) || addr.address;
    const named = shown ? `${addr.method} ${shown}` : addr.method;
    if (!(await askConfirm({
      title: `Remove ${named}?`,
      body: 'The address is deleted from this account. This cannot be undone.',
      danger: true,
    }))) return;
    const { error } = await mutate(supabase.from('platform_payment_addresses').delete().eq('id', addr.id));
    if (error) { toast.error(error); return; }
    fetchAddresses();
  }

  const title = `${account.platform.charAt(0).toUpperCase() + account.platform.slice(1)} · @${account.username}`;

  return (
    <Modal
      title="PAYMENT ADDRESSES"
      subtitle={title}
      size="md"
      onClose={onClose}
    >
        <div className="modal-body">
          <Refreshing on={addrRefreshing} />
          {addrLoading ? (
            <Loading />
          ) : addrError ? (
            /* The list read IS this surface, so its refusal takes everything that acts on a
             * row with it: Add, Edit, remove and the preferred toggle all lose their subject.
             * Add most of all, since Save is a bare insert against a table with no unique
             * key, and both remit-to consumers print every row they find. */
            <ReadError error={addrError} onRetry={fetchAddresses} />
          ) : (
            <>
              {addresses.length === 0 && editing !== 'new' && (
                <div style={{ fontSize: 13, color: 'var(--muted)', marginBottom: 16 }}>
                  No payment addresses configured yet.
                </div>
              )}
              {addresses.length > 0 && (
                <div style={{ marginBottom: 16 }}>
                  {addresses.map(addr => {
                    const addrSchema = schemaFor(addr.method);
                    return (
                      <div key={addr.id} style={{
                        display: 'flex', alignItems: 'flex-start', gap: 12,
                        padding: '12px 10px', marginBottom: 2, borderRadius: 6,
                        background: addr.is_preferred ? 'rgba(255,92,0,0.05)' : 'transparent',
                        transition: 'background 0.15s',
                      }}>
                        {/* Preferred dot toggle */}
                        <button
                          onClick={() => !addr.is_preferred && setPreferred(addr.id)}
                          title={addr.is_preferred ? 'Preferred' : 'Set as preferred'}
                          aria-label={addr.is_preferred ? 'Preferred payment address' : 'Set as preferred payment address'}
                          style={{
                            background: 'none', border: 'none', padding: 0, marginTop: 3,
                            flexShrink: 0, cursor: addr.is_preferred ? 'default' : 'pointer',
                            display: 'flex', alignItems: 'center', justifyContent: 'center',
                            width: 16, height: 16,
                          }}
                        >
                          <span style={{
                            display: 'block', width: 8, height: 8, borderRadius: '50%',
                            background: addr.is_preferred ? 'var(--orange)' : 'transparent',
                            border: `1.5px solid ${addr.is_preferred ? 'var(--orange)' : 'var(--dim)'}`,
                            transition: 'background 0.15s, border-color 0.15s',
                          }} />
                        </button>

                        {/* Content */}
                        <div style={{ flex: 1, minWidth: 0 }}>
                          <div style={{
                            fontSize: 10, fontWeight: 700, textTransform: 'uppercase',
                            letterSpacing: '0.1em', color: addr.is_preferred ? 'var(--orange)' : 'var(--muted)',
                            marginBottom: 6, transition: 'color 0.15s',
                          }}>
                            {addr.method}
                          </div>
                          {addr.fields && addrSchema.length > 0 ? (
                            addrSchema.map(f => addr.fields[f.key] ? (
                              <div key={f.key} style={{ display: 'flex', gap: 12, marginBottom: 3, alignItems: 'baseline' }}>
                                <span style={{ fontSize: 11, color: 'var(--muted)', minWidth: 100, flexShrink: 0 }}>{f.label}</span>
                                <span title={addr.fields[f.key]} style={{ fontSize: 13, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{addr.fields[f.key]}</span>
                              </div>
                            ) : null)
                          ) : (
                            <div title={addr.address} style={{ fontSize: 13, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                              {addr.address}
                            </div>
                          )}
                          {addr.label && (
                            <div style={{ fontSize: 11, color: 'var(--muted)', marginTop: 4 }}>
                              Agency label: {addr.label}
                            </div>
                          )}
                        </div>

                        {/* Actions */}
                        <div style={{ display: 'flex', gap: 4, flexShrink: 0, alignSelf: 'flex-start', marginTop: 1 }}>
                          {/* Edit is the one route to the form that Add does not guard, and
                              without a method schema `save` writes `fields: null` over a
                              structured payout address. Remove stays: it needs no schema. */}
                          {!methodsError && (
                            <button className="btn btn-ghost btn-sm" onClick={() => openEdit(addr)}
                              style={{ fontSize: 11, padding: '2px 8px', color: 'var(--muted)' }}>
                              Edit
                            </button>
                          )}
                          <button className="btn btn-ghost btn-sm" onClick={() => remove(addr)}
                            aria-label="Remove this address"
                            style={{ fontSize: 13, padding: '2px 6px', color: 'var(--dim)', lineHeight: 1 }}>
                            ×
                          </button>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}

              {editing ? (
                <div style={{ background: 'var(--surface2)', borderRadius: 6, padding: 16 }}>
                  <div style={{ fontSize: 11, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.06em', color: 'var(--muted)', marginBottom: 12 }}>
                    {editing === 'new' ? 'Add Address' : 'Edit Address'}
                  </div>
                  {error && <Feedback value={error} style={{ marginBottom: 12 }} />}
                  {(() => {
                    const schema = schemaFor(form.method);
                    return schema.length > 0 ? (
                      <>
                        <Field label="Method" style={{ margin: 0, marginBottom: 10 }}>{(id) => (<>
                          <select id={id} className="form-select" value={form.method} onChange={e => { setForm(f => ({ ...f, method: e.target.value, address: '', fields: {} })); setError(''); }}>
                            {methods.map(m => <option key={m.name} value={m.name}>{m.name}</option>)}
                          </select>
                        </>)}</Field>
                        {schema.map(field => (
                          <Field label={<>{field.label}{field.required ? ' *' : ' (optional)'}</>} style={{ margin: 0, marginBottom: 10 }}>{(id) => (<>
                            <input id={id} className="form-input" value={form.fields[field.key] || ''} maxLength={500}
                              onChange={e => { setForm(f => ({ ...f, fields: { ...f.fields, [field.key]: e.target.value } })); setError(''); }} />
                          </>)}</Field>
                        ))}
                      </>
                    ) : (
                      <div style={{ display: 'grid', gridTemplateColumns: '1fr 2fr', gap: 10, marginBottom: 10 }}>
                        <Field label="Method" style={{ margin: 0 }}>{(id) => (<>
                          <select id={id} className="form-select" value={form.method} onChange={e => { setForm(f => ({ ...f, method: e.target.value, address: '', fields: {} })); setError(''); }}>
                            {methods.map(m => <option key={m.name} value={m.name}>{m.name}</option>)}
                          </select>
                        </>)}</Field>
                        <Field label="Address *" style={{ margin: 0 }}>{(id) => (<>
                          <input id={id} className="form-input" value={form.address} maxLength={500}
                            placeholder="email, URL, or handle"
                            onChange={e => { setForm(f => ({ ...f, address: e.target.value })); setError(''); }} />
                        </>)}</Field>
                      </div>
                    );
                  })()}
                  <Field label={<>Label <span style={{ color: 'var(--muted)' }}>(optional, overrides method name in agency view)</span></>} style={{ margin: 0 }}>{(id) => (<>
                    <input id={id} className="form-input" value={form.label} maxLength={120}
                      placeholder="e.g. Business PayPal"
                      onChange={e => setForm(f => ({ ...f, label: e.target.value }))} />
                  </>)}</Field>
                  <div className="flex gap-8" style={{ marginTop: 12 }}>
                    <SubmitButton saving={saving} className="btn btn-primary btn-sm" onClick={save} disabled={saving}>Save</SubmitButton>
                    <button className="btn btn-ghost btn-sm" onClick={cancelEdit}>Cancel</button>
                    {editing !== 'new' && !addresses.find(a => a.id === editing)?.is_preferred && (
                      <button className="btn btn-ghost btn-sm" onClick={() => setPreferred(editing)}
                        style={{ marginLeft: 4, color: 'var(--orange)' }}>
                        Set as Preferred
                      </button>
                    )}
                  </div>
                </div>
              ) : methodsError ? (
                /* Reported inside the control it fills, not over the whole modal: the
                   addresses that loaded still render above. Standing in the Add slot
                   withholds Add for free, which it must: the picker feeds `fields_schema`,
                   and a form with no schema writes the wrong columns. */
                <ReadError error={methodsError} onRetry={fetchAddresses} />
              ) : methods.length === 0 ? (
                <EmptyState variant="note"
                  text="No active payment methods. Add them in Payment Setup first." />
              ) : (
                <button className="btn btn-ghost btn-sm" onClick={openAdd}>+ Add Address</button>
              )}
            </>
          )}
        </div>
        <div className="modal-footer">
          <button className="btn btn-secondary" onClick={onClose}>Done</button>
        </div>
    </Modal>
  );
}

// ── Deliverable type modal ─────────────────────────────────────────────────────
function DeliverableTypeModal({ type, onClose, onSaved }) {
  const toast = useToast();
  const [form, setForm] = useState({
    name:        type?.name        || '',
    description: type?.description || '',
  });
  const [saving, setSaving] = useState(false);
  const [error, setError]   = useState('');

  async function save() {
    const name = form.name.trim();
    if (!name) { setError('Name is required.'); return; }
    setSaving(true); setError('');
    const payload = { name, description: form.description.trim() || null };
    if (type) {
      const { error: err } = await supabase.from('deliverable_types').update(payload).eq('id', type.id);
      if (err) { setError(humanizeError(err)); setSaving(false); return; }
    } else {
      const { error: err } = await supabase.from('deliverable_types').insert(payload);
      if (err) { setError(humanizeError(err)); setSaving(false); return; }
    }
    toast.success(type ? 'Deliverable type updated' : 'Deliverable type added');
    onSaved();
  }

  return (
    <Modal
      title={type ? 'EDIT DELIVERABLE TYPE' : 'ADD DELIVERABLE TYPE'}
      size="sm"
      onClose={onClose}
    >
        <div className="modal-body">
          {error && <Feedback value={error} style={{ marginBottom: 16 }} />}
          <Field label="Name *">{(id) => (<>
            <input id={id} className="form-input" value={form.name} autoFocus
              onChange={e => { setForm(f => ({ ...f, name: e.target.value })); setError(''); }}
              onKeyDown={e => e.key === 'Enter' && save()}
              placeholder="Video, Reel, Story, Carousel…" />
          </>)}</Field>
          <Field label="Description">{(id) => (<>
            <input id={id} className="form-input" value={form.description}
              onChange={e => setForm(f => ({ ...f, description: e.target.value }))}
              placeholder="Optional description" />
          </>)}</Field>
        </div>
        <div className="modal-footer">
          <ModalClose className="btn btn-ghost">Cancel</ModalClose>
          <SubmitButton saving={saving} className="btn btn-primary" onClick={save} disabled={saving || !form.name.trim()}>{type ? 'Save' : 'Add Type'}</SubmitButton>
        </div>
    </Modal>
  );
}
