/**
 * utils/ledger-activity.js - pure activity-feed aggregation.
 *
 * Groups posted ledger journal entries into plain-language "business event"
 * cards (invoice / payout / partner txn / manual) with lifecycle pills and
 * Money-In / Money-Out columns derived purely from cash-account (1000)
 * movements. Powers LedgerPage's default Activity tab.
 *
 * @invariant Money-In/Out always come from the 1000 cash lines of each JE, never
 *            from a source row's stored total, so reversals and edits stay
 *            self-consistent. The caller supplies enrichment lookup maps; this
 *            file does no I/O.
 * @see docs/MONEY.md (JE patterns), schemas/SCHEMA.sql (source_type values)
 */
import { fmtMonth, round2 } from './format';
import { campaignLabelParts } from './campaignLabel';

const num = (v) => {
  const n = typeof v === 'number' ? v : parseFloat(v);
  return Number.isFinite(n) ? n : 0;
};

const truncate = (s, n) => {
  const t = String(s || '').trim();
  return t.length > n ? t.slice(0, n - 1) + '…' : t;
};

function formatDestination(dest) {
  if (!dest) return null;
  if (dest.last4) return `${dest.name} ••••${dest.last4}`;
  return dest.name;
}

function campaignContext(campaign) {
  if (!campaign) return null;
  const { label, month } = campaignLabelParts(campaign);
  if (campaign.brand_name) {
    return month ? `${campaign.brand_name} · ${month}` : campaign.brand_name;
  }
  return label || null;
}

function rewardContext(rewardEntry, programsById) {
  if (!rewardEntry) return null;
  const program = programsById?.get(rewardEntry.program_id) || rewardEntry.program;
  const ym = (rewardEntry.period_month || '').slice(0, 7);
  const monthLabel = ym ? fmtMonth(ym) : null;
  if (program?.name) {
    return monthLabel ? `${program.name} · ${monthLabel}` : program.name;
  }
  return monthLabel;
}

function creatorName(profile) {
  if (!profile) return 'creator';
  return profile.creator_name || profile.full_name || 'creator';
}

function agencyName(agency) {
  if (!agency) return 'an agency';
  return agency.name || 'an agency';
}

// ── Money-on-cash helpers ─────────────────────────────────────

/**
 * Cash movement for one JE: { in, out } from its 1000-account lines.
 * @gotcha Money In = SUM of debits on 1000 (cash up); Money Out = SUM of credits
 *         on 1000 (cash down). Lines on any other account are ignored.
 */
function cashImpactForJe(jeLines, cashAccountId) {
  let inn = 0, out = 0;
  for (const ln of jeLines || []) {
    if (ln.account_id !== cashAccountId) continue;
    inn += num(ln.debit);
    out += num(ln.credit);
  }
  return { in: inn, out };
}

// ── Card builders ─────────────────────────────────────────────

/** One card per invoice: AR ("Invoiced") + cash-receipt ("Received") lifecycle. */
function buildInvoiceCard({ invoice, jes, linesByJe, cashAccountId, ctx }) {
  const {
    campaignsById, agenciesById, profilesById, rewardEntriesById, programsById,
  } = ctx;
  const campaign = invoice?.campaign_id ? (campaignsById?.get(invoice.campaign_id) || null) : null;
  const reward   = invoice?.reward_entry_id ? (rewardEntriesById?.get(invoice.reward_entry_id) || null) : null;
  const agency  = campaign?.agency_id ? (agenciesById?.get(campaign.agency_id) || null) : null;
  const creatorId = campaign?.creator_profile_id || reward?.profile_id || null;
  const creator = creatorId ? profilesById?.get(creatorId) : null;

  const contextStr = campaign
    ? campaignContext(campaign)
    : rewardContext(reward, programsById);

  const isInKind = !!invoice?.is_in_kind;
  const gross = num(isInKind
    ? (invoice?.in_kind_value || invoice?.invoice_amount)
    : (invoice?.invoice_amount || invoice?.gross_amount));

  // Reward invoices have no agency - they come from a platform program.
  const sourceLabel = reward && !campaign
    ? (rewardContext(reward, programsById) || 'platform reward')
    : agencyName(agency);

  const headline = isInKind
    ? `In-kind: ${sourceLabel} sent ${creatorName(creator)} ${gross ? `$${gross.toFixed(2)} value` : 'product'}${campaign && contextStr ? ` (${contextStr})` : ''}`
    : `Invoiced ${sourceLabel} $${gross.toFixed(2)} for ${creatorName(creator)}${campaign && contextStr ? ` (${contextStr})` : ''}`;

  // Lifecycle: every invoice has an AR JE by definition (it's why we're here).
  // "Received" lights up when the cash-receipt JE exists for this invoice
  // (Pattern B/D - it's the JE whose lines touch cash 1000 with a debit, OR
  // for in-kind, the second JE recorded). Easiest signal: whether any JE in
  // this invoice's group has cash-debit > 0, OR invoice.you_received=true.
  let cashIn = 0, cashOut = 0;
  for (const je of jes) {
    const c = cashImpactForJe(linesByJe.get(je.id) || [], cashAccountId);
    cashIn += c.in; cashOut += c.out;
  }
  const received = cashIn > 0 || invoice?.you_received === true;

  const pills = isInKind
    ? [
        { label: 'In-kind recorded', state: 'done' },
      ]
    : [
        { label: 'Invoiced', state: 'done' },
        { label: 'Received', state: received ? 'done' : 'pending' },
      ];

  const dates = jes.map((j) => (j.entry_date || '').slice(0, 10)).filter(Boolean).sort();
  const reversed = jes.some((j) => !!j.reversed_by_je_id);

  return {
    key: `invoice:${invoice?.id}`,
    type: 'invoice',
    headline,
    contextLine: invoice?.invoice_number ? invoice.invoice_number : null,
    date: dates[dates.length - 1] || '',
    startedDate: dates[0] || '',
    pills,
    moneyIn:  round2(cashIn),
    moneyOut: round2(cashOut),
    jeIds: jes.map((j) => j.id),
    isReversed: reversed,
  };
}

/**
 * One card per payout: "Authorised" (Pattern E) + a "Cleared (n/total)" pill
 * counting destination splits that have a clearance JE.
 * @gotcha the authorised total is the JE debit total (DR 511x), not a sum of
 *         per-destination credits (that would double-count the balanced sides).
 */
function buildPayoutCard({ payout, jes, splitJesByPayout, linesByJe, cashAccountId, ctx }) {
  const {
    profilesById, campaignsById, rewardEntriesById, programsById, splitsById, destinationsById,
  } = ctx;
  const creator = profilesById?.get(payout?.profile_id) || null;
  const campaign = payout?.campaign_id ? (campaignsById?.get(payout.campaign_id) || null) : null;
  const reward   = payout?.reward_entry_id ? (rewardEntriesById?.get(payout.reward_entry_id) || null) : null;
  const contextStr = campaign ? campaignContext(campaign) : rewardContext(reward, programsById);

  const splitJes = splitJesByPayout.get(payout?.id) || [];
  const allJes = [...jes, ...splitJes];
  // Compute totals from JE lines - independent of the source row's total field
  // so reversals/edits stay consistent.
  let totalAuthorised = 0, cashIn = 0, cashOut = 0;
  for (const je of jes) {
    const c = cashImpactForJe(linesByJe.get(je.id) || [], cashAccountId);
    cashIn += c.in; cashOut += c.out;
    // Pattern E credits 21xx liability per destination; total = SUM of those credits.
    for (const ln of linesByJe.get(je.id) || []) {
      totalAuthorised += num(ln.credit);
    }
  }
  // For Pattern E we double-count: each line's credit is one side of a JE that
  // has matching debits totalling the same. The simplest authorised number is
  // the JE's debit total (DR 511x), so use that instead.
  totalAuthorised = 0;
  for (const je of jes) {
    let dr = 0;
    for (const ln of linesByJe.get(je.id) || []) dr += num(ln.debit);
    totalAuthorised += dr;
  }
  for (const je of splitJes) {
    const c = cashImpactForJe(linesByJe.get(je.id) || [], cashAccountId);
    cashIn += c.in; cashOut += c.out;
  }

  // Cleared pill: count splits with a clearance JE vs total destination
  // splits attached to the payout. We can derive the denominator from
  // splitsById iteration.
  const allSplitsForPayout = [...(splitsById?.values() || [])].filter((s) => s.payout_id === payout?.id);
  const destSplits = allSplitsForPayout.filter((s) => s.destination_id);
  const clearedDest = destSplits.filter((s) => splitJes.some((j) => j.source_id === s.id)).length;

  const totalDest = destSplits.length;
  const clearedState = totalDest === 0 ? 'pending'
    : clearedDest >= totalDest ? 'done'
    : clearedDest > 0 ? 'partial'
    : 'pending';

  // Build destination list for context line: top 2 destination names cleared.
  const clearedDestSplits = destSplits
    .filter((s) => splitJes.some((j) => j.source_id === s.id))
    .map((s) => formatDestination(destinationsById?.get(s.destination_id)))
    .filter(Boolean);
  const ctxLine = clearedDestSplits.length
    ? `→ ${clearedDestSplits.slice(0, 2).join(' · ')}${clearedDestSplits.length > 2 ? ` · +${clearedDestSplits.length - 2}` : ''}`
    : null;

  const headline = `Paid out $${totalAuthorised.toFixed(2)} to ${creatorName(creator)}${contextStr ? ` (${contextStr})` : ''}`;

  const pills = [
    { label: 'Authorised', state: jes.length ? 'done' : 'pending' },
    {
      label: totalDest === 0
        ? 'Cleared'
        : clearedState === 'done' ? `Cleared (${totalDest}/${totalDest})`
        : clearedState === 'partial' ? `Cleared (${clearedDest}/${totalDest})`
        : `Cleared (0/${totalDest})`,
      state: clearedState,
    },
  ];

  const dates = allJes.map((j) => (j.entry_date || '').slice(0, 10)).filter(Boolean).sort();
  const reversed = allJes.some((j) => !!j.reversed_by_je_id);

  return {
    key: `payout:${payout?.id}`,
    type: 'payout',
    headline,
    contextLine: ctxLine,
    date: dates[dates.length - 1] || '',
    startedDate: dates[0] || '',
    pills,
    moneyIn:  round2(cashIn),
    moneyOut: round2(cashOut),
    jeIds: allJes.map((j) => j.id),
    isReversed: reversed,
  };
}

/** One card per partner capital contribution (Pattern I) or distribution (J). */
function buildPartnerTxnCard({ txn, je, lines, cashAccountId, ctx }) {
  const profile = ctx.profilesById?.get(txn?.profile_id);
  const amount = num(txn?.amount);
  const headline = txn?.txn_type === 'contribution'
    ? `${profile?.full_name || 'Partner'} contributed $${amount.toFixed(2)} of capital`
    : `${profile?.full_name || 'Partner'} took a $${amount.toFixed(2)} distribution`;

  const c = cashImpactForJe(lines, cashAccountId);
  return {
    key: `partner_txn:${txn?.id}`,
    type: 'partner_txn',
    headline,
    contextLine: txn?.notes ? truncate(txn.notes, 80) : null,
    date: (je?.entry_date || txn?.txn_date || '').slice(0, 10),
    startedDate: (je?.entry_date || txn?.txn_date || '').slice(0, 10),
    pills: [{ label: txn?.txn_type === 'contribution' ? 'Contribution' : 'Distribution', state: 'done' }],
    moneyIn:  round2(c.in),
    moneyOut: round2(c.out),
    jeIds: je ? [je.id] : [],
    isReversed: !!je?.reversed_by_je_id,
  };
}

/** Fallback card for any JE with no recognised source_type (manual / orphan). */
function buildManualCard({ je, lines, cashAccountId }) {
  const c = cashImpactForJe(lines, cashAccountId);
  const headline = truncate(je?.description || 'Manual entry', 120);
  return {
    key: `manual:${je?.id}`,
    type: 'manual',
    headline,
    contextLine: je?.reference ? `Ref: ${truncate(je.reference, 80)}` : null,
    date: (je?.entry_date || '').slice(0, 10),
    startedDate: (je?.entry_date || '').slice(0, 10),
    pills: [{ label: je?.reversed_by_je_id ? 'Reversed' : 'Posted', state: je?.reversed_by_je_id ? 'reversed' : 'done' }],
    moneyIn:  round2(c.in),
    moneyOut: round2(c.out),
    jeIds: [je?.id].filter(Boolean),
    isReversed: !!je?.reversed_by_je_id,
  };
}

// ── Public API ────────────────────────────────────────────────

/**
 * Group ledger entries into business-event cards.
 *
 * `entries` and `lines` should already be filtered to posted JEs by the caller
 * (any reversed entries that should be excluded from totals can also be pre-
 * filtered, though we keep them here so the user can still see reversed cards
 * for traceability).
 */
export function buildActivityCards({
  entries, lines, cashAccountId,
  invoicesById, campaignsById, rewardEntriesById, programsById, agenciesById,
  payoutsById, splitsById, destinationsById, profilesById, partnerTxnsById,
}) {
  const linesByJe = new Map();
  for (const ln of lines || []) {
    if (!linesByJe.has(ln.journal_entry_id)) linesByJe.set(ln.journal_entry_id, []);
    linesByJe.get(ln.journal_entry_id).push(ln);
  }
  const ctx = {
    invoicesById, campaignsById, rewardEntriesById, programsById, agenciesById,
    payoutsById, splitsById, destinationsById, profilesById, partnerTxnsById,
  };

  // Bucket entries by event key.
  const invoiceJes = new Map();        // invoice_id -> [je, ...]
  const payoutJes  = new Map();        // payout_id  -> [je, ...]   (Pattern E)
  const splitJesByPayout = new Map();  // payout_id  -> [je, ...]   (Pattern F/G)
  const partnerTxnJes = new Map();     // partner_txn_id -> je
  const manualJes = [];

  for (const e of entries || []) {
    if (e.source_type === 'invoice' && e.source_id) {
      if (!invoiceJes.has(e.source_id)) invoiceJes.set(e.source_id, []);
      invoiceJes.get(e.source_id).push(e);
    } else if (e.source_type === 'payout' && e.source_id) {
      if (!payoutJes.has(e.source_id)) payoutJes.set(e.source_id, []);
      payoutJes.get(e.source_id).push(e);
    } else if (e.source_type === 'split' && e.source_id) {
      const split = splitsById?.get(e.source_id);
      const payoutId = split?.payout_id;
      if (payoutId) {
        if (!splitJesByPayout.has(payoutId)) splitJesByPayout.set(payoutId, []);
        splitJesByPayout.get(payoutId).push(e);
      } else {
        manualJes.push(e); // orphan split JE: surface as manual rather than swallow
      }
    } else if (e.source_type === 'partner_txn' && e.source_id) {
      partnerTxnJes.set(e.source_id, e);
    } else {
      manualJes.push(e);
    }
  }

  const cards = [];

  for (const [invoiceId, jes] of invoiceJes) {
    const invoice = invoicesById?.get(invoiceId) || { id: invoiceId };
    cards.push(buildInvoiceCard({ invoice, jes, linesByJe, cashAccountId, ctx }));
  }

  // Payouts: each payout gets a card if it has either an authorisation JE or
  // any split clearance JE.
  const payoutKeys = new Set([...payoutJes.keys(), ...splitJesByPayout.keys()]);
  for (const payoutId of payoutKeys) {
    const payout = payoutsById?.get(payoutId) || { id: payoutId };
    cards.push(buildPayoutCard({
      payout,
      jes: payoutJes.get(payoutId) || [],
      splitJesByPayout,
      linesByJe,
      cashAccountId,
      ctx,
    }));
  }

  for (const [txnId, je] of partnerTxnJes) {
    const txn = partnerTxnsById?.get(txnId) || { id: txnId };
    cards.push(buildPartnerTxnCard({ txn, je, lines: linesByJe.get(je.id) || [], cashAccountId, ctx }));
  }

  for (const je of manualJes) {
    cards.push(buildManualCard({ je, lines: linesByJe.get(je.id) || [], cashAccountId }));
  }

  // Sort: latest activity first, ties broken by event type for stability.
  cards.sort((a, b) => {
    if (a.date !== b.date) return a.date < b.date ? 1 : -1;
    return a.key.localeCompare(b.key);
  });

  return cards;
}

/**
 * Match a card against a free-text search and event-type filter.
 * Returns true if the card should be visible.
 */
export function matchActivityCard(card, { search, eventType } = {}) {
  if (eventType && eventType !== 'all' && card.type !== eventType) return false;
  if (search) {
    const needle = String(search).toLowerCase();
    const hay = [card.headline, card.contextLine].filter(Boolean).join(' ').toLowerCase();
    if (!hay.includes(needle)) return false;
  }
  return true;
}
