/**
 * components/shared/CompBasisPanel.js: one creator's compensation basis, its whole history, and
 * the only place either is changed.
 *
 * Whether a creator is a 1099 contractor or a W-2 employee is effective-dated: one row per
 * change, the next row ending the previous one. The rows ARE the history, so the list is both
 * the current answer and the log of how it got there, and nothing has to be kept in step.
 *
 * It sits with her payout accounts because it decides whether they are a paycheck at all: a
 * creator on a 1099 has no split, and reading "W-2 since January" directly above 50/25/25 is
 * what makes those percentages mean something.
 *
 * @security a change here is RETROACTIVE. It restates the tax character of money already paid:
 *           dollars move between Form 1065 line 2 and line 9, a 1099-NEC starts or stops being
 *           issued, and a creator's self-employment tax appears or disappears. A closed fiscal
 *           year is therefore refused outright, the same rule a posted entry gets, and the way
 *           out is to unlock that year in Financials, which already demands a reason and writes
 *           an audit row.
 * @gotcha a change dated anything but the first of a month leaves that month half wages, and a
 *         paycheck settles a whole month in one immutable entry, so payroll refuses to settle
 *         it. That is a warning rather than a refusal: the date may genuinely be a birthday,
 *         and those invoices can still be settled one at a time.
 * @see utils/compBasis.js; schemas/SCHEMA.sql (creator_comp_basis); docs/MONEY.md section 10.0b
 */
import React, { useState } from 'react';
import { supabase } from '../../lib/supabase';
import { mutate } from '../../utils/mutate';
import { fmtDate, fmtMonth } from '../../utils/format';
import { DB_DATE_MAX, DB_DATE_MIN } from '../../utils/dbLimits';
import { compBasisOn } from '../../utils/compBasis';
import { useConfirm } from './ConfirmDialog';
import { useToast } from './Toast';
import { ChevronIcon, WarningIcon } from './Icon';
import Feedback from './Feedback';
import EmptyState from './EmptyState';
import Field from './Field';
import SubmitButton from './SubmitButton';

/** What each basis is called on screen. The stored values are '1099' and 'w2'. */
const LABEL = { 1099: '1099 contractor', w2: 'W-2 employee' };
const SHORT = { 1099: '1099', w2: 'W-2' };

const yearOf = (ymd) => parseInt(String(ymd || '').slice(0, 4), 10);

/** Whether this row has been changed since it was written. The trigger keeps `updated_at`, and
 *  an insert leaves the two a few microseconds apart, so the DAY is what is compared. */
const wasEdited = (row) =>
  !!row.updated_at && String(row.updated_at).slice(0, 10) !== String(row.created_at).slice(0, 10);
const firstOfMonth = (ymd) => `${String(ymd || '').slice(0, 7)}-01`;

/**
 * One creator's basis today, said the way a reader would say it.
 * @returns {string} e.g. "W-2 since Jan 1, 2026", or the resting state before any row exists
 */
export function currentBasisLabel(rows, profileId, today) {
  const basis = compBasisOn(rows, profileId, today);
  if (!basis) return null;
  const live = [...(rows || [])]
    .filter(r => r.profile_id === profileId && String(r.effective_from).slice(0, 10) <= today)
    .sort((a, b) => (a.effective_from < b.effective_from ? 1 : -1))[0];
  return live
    ? `${SHORT[live.basis]} since ${fmtDate(live.effective_from)}`
    : '1099, never changed';
}

/**
 * @param {object} props.creator the profile row
 * @param {object[]} props.rows every `creator_comp_basis` row (all creators; filtered here)
 * @param {Set<number>} props.closedYears fiscal years that are closed or locked
 * @param {string} props.today 'YYYY-MM-DD', so the caller decides what "now" means
 * @param {function} props.onSaved re-fetch after a write
 */
export default function CompBasisPanel({ creator, rows, closedYears, today, onSaved }) {
  const askConfirm = useConfirm();
  const toast = useToast();
  const [form, setForm]     = useState(null);   // { id, basis, effective_from } while editing
  const [saving, setSaving] = useState(false);
  const [error, setError]   = useState('');

  const mine = (rows || [])
    .filter(r => r.profile_id === creator.id)
    .sort((a, b) => (a.effective_from < b.effective_from ? 1 : -1));   // newest first

  const liveOn = compBasisOn(rows, creator.id, today);

  /** A row inside a closed year is sealed, and so is a date that would move one into it. */
  const sealed = (ymd) => closedYears.has(yearOf(ymd));

  function startAdd() {
    setError('');
    // The next change is a change FROM what she is on now, so the other basis is the useful
    // default. Guessing the date would be worse than leaving it empty: it is the whole decision.
    setForm({ id: null, basis: liveOn === 'w2' ? '1099' : 'w2', effective_from: '' });
  }

  function startEdit(row) {
    setError('');
    setForm({ id: row.id, basis: row.basis, effective_from: String(row.effective_from).slice(0, 10) });
  }

  async function remove(row) {
    const ok = await askConfirm({
      title: `Delete the ${SHORT[row.basis]} change dated ${fmtDate(row.effective_from)}?`,
      body: 'The change will be deleted, and whatever she was on before this date applies from '
          + 'it too. That restates the tax character of anything paid since, so check the 1099 '
          + 'tab and Form 1065 afterwards.',
      danger: true,
    });
    if (!ok) return;
    const { error: err } = await mutate(supabase.from('creator_comp_basis').delete().eq('id', row.id));
    if (err) { setError(err); return; }
    toast.success('Change deleted');
    onSaved();
  }

  const date = form?.effective_from || '';
  const duplicate = !!date && mine.some(r => String(r.effective_from).slice(0, 10) === date && r.id !== form?.id);
  const intoClosed = !!date && sealed(date);
  const midMonth = !!date && date !== firstOfMonth(date);
  const blocked = !date || duplicate || intoClosed;

  async function save() {
    setSaving(true);
    setError('');
    const payload = { profile_id: creator.id, basis: form.basis, effective_from: date };
    const { error: err } = form.id
      ? await mutate(supabase.from('creator_comp_basis').update(payload).eq('id', form.id))
      : await mutate(supabase.from('creator_comp_basis').insert(payload));
    setSaving(false);
    if (err) { setError(err); return; }
    setForm(null);
    toast.success('Compensation basis saved');
    onSaved();
  }

  return (
    <div className="basis-panel">
      <div className="basis-head">
        <span className="basis-title">Compensation basis</span>
        <span className="basis-sub">
          How her pay is reported. Decides the paycheck split below, her 1099, and where Form 1065
          carries her wages.
        </span>
      </div>

      {error && <Feedback value={error} style={{ marginBottom: 12 }} />}

      {mine.length === 0 ? (
        <EmptyState variant="note"
          text="Nothing recorded, so she is treated as a 1099 contractor. Record a change to put her on payroll from a date." />
      ) : (
        <ul className="basis-list">
          {mine.map(row => {
            const isLive = String(row.effective_from).slice(0, 10) <= today
              && row === mine.find(r => String(r.effective_from).slice(0, 10) <= today);
            return (
              <li key={row.id} className="basis-row" data-live={isLive ? 'true' : 'false'}>
                <span className="basis-what">{LABEL[row.basis] || row.basis}</span>
                <span className="basis-when">from {fmtDate(row.effective_from)}</span>
                {/* An edited row saying only when it was first recorded would undercut the one
                    thing this list is for. Both dates, and only when they differ. */}
                <span className="basis-recorded">
                  recorded {fmtDate(row.created_at)}
                  {wasEdited(row) && <>, edited {fmtDate(row.updated_at)}</>}
                </span>
                {sealed(row.effective_from) ? (
                  <span className="basis-sealed" title={`FY${yearOf(row.effective_from)} is closed. Unlock it in Financials to change this.`}>
                    FY{yearOf(row.effective_from)} closed
                  </span>
                ) : (
                  <span className="basis-actions">
                    <button type="button" className="btn btn-ghost btn-sm" onClick={() => startEdit(row)}>Edit</button>
                    <button type="button" className="btn btn-ghost btn-sm" onClick={() => remove(row)}>Delete</button>
                  </span>
                )}
              </li>
            );
          })}
        </ul>
      )}

      {form ? (
        <div className="basis-form">
          <div className="basis-fields">
            <Field label="Basis">
              {(id) => (
                <select id={id} className="form-select" style={{ width: 190 }}
                  value={form.basis}
                  onChange={e => setForm(f => ({ ...f, basis: e.target.value }))}>
                  <option value="1099">{LABEL['1099']}</option>
                  <option value="w2">{LABEL.w2}</option>
                </select>
              )}
            </Field>
            <Field label="In effect from">
              {(id) => (
                <input id={id} type="date" className="form-input" style={{ width: 175 }}
                  min={DB_DATE_MIN} max={DB_DATE_MAX}
                  value={date}
                  onChange={e => setForm(f => ({ ...f, effective_from: e.target.value }))} />
              )}
            </Field>
          </div>

          {intoClosed && (
            <Feedback value={{
              tone: 'error',
              title: `FY${yearOf(date)} is closed`,
              body: `This would restate money already paid inside a closed year. Unlock FY${yearOf(date)} `
                  + 'in Financials, General Ledger, and it can be changed there and then.',
            }} />
          )}
          {duplicate && !intoClosed && (
            <Feedback value={{
              tone: 'error',
              title: 'She already has a change on that date',
              body: 'One basis per date. Edit the existing change instead, or pick another date.',
            }} />
          )}
          {midMonth && !blocked && (
            <div className="basis-warn">
              <WarningIcon size={13} />
              <span>
                {fmtMonth(date.slice(0, 7))} would be half {SHORT[form.basis === 'w2' ? '1099' : 'w2']} and
                half {SHORT[form.basis]}, and payroll cannot settle a month like that in one paycheck.
                Those invoices would each be settled on Payments instead.
              </span>
              <button type="button" className="btn btn-ghost btn-sm"
                onClick={() => setForm(f => ({ ...f, effective_from: firstOfMonth(date) }))}>
                Use {fmtDate(firstOfMonth(date))}
              </button>
            </div>
          )}

          <div className="basis-form-actions">
            <button type="button" className="btn btn-ghost btn-sm" onClick={() => { setForm(null); setError(''); }}>
              Cancel
            </button>
            <SubmitButton saving={saving} className="btn btn-primary btn-sm" onClick={save} disabled={saving || blocked}>
              {form.id ? 'Save change' : 'Record change'}
            </SubmitButton>
          </div>
        </div>
      ) : (
        <button type="button" className="btn btn-ghost btn-sm basis-add" onClick={startAdd}>
          Record a change
        </button>
      )}
    </div>
  );
}

/**
 * The creator-header control that opens the panel, carrying the answer so the common case needs
 * no click at all.
 */
export function BasisChip({ label, open, onToggle }) {
  return (
    <button type="button" className="basis-chip" aria-expanded={open} onClick={onToggle}>
      <span>{label}</span>
      <ChevronIcon size={10} style={{ transform: open ? 'rotate(90deg)' : 'none' }} />
    </button>
  );
}
