/**
 * components/admin/BusinessProfileView.js: admin Setup editor for the singleton
 * LLC FROM-side identity printed on every issued invoice, plus a one-off backfill
 * action that regenerates the stored invoice PDF for legacy billed invoices.
 *
 * Edits the single active `business_profile` row (legal name, EIN, address,
 * contact, default terms, footer text). No logo upload: the invoice identity is
 * the typographic NYSTERYS wordmark, not an image.
 *
 * @invariant legal_name is required and trimmed; a blank one blocks save.
 * @gotcha All string fields are sliced to FIELD[k].max and emptied to null before
 *         save, so the DB never stores over-length or whitespace-only values.
 * @see docs/CODEBASE.md (invoice identity), components/shared/pdf/InvoicePDF.js
 */
import React, { useState, useEffect, useCallback } from 'react';
import { supabase } from '../../lib/supabase';
import { generateAndUploadIssuedInvoice, loadCurrentDoc } from '../../utils/invoiceDocuments';
import { humanizeError } from '../../utils/errors';
import { BILLED_PAYMENT_VALUES } from '../../utils/statusValues';
import HelpIcon from '../shared/HelpIcon';
import { useConfirm } from '../shared/ConfirmDialog';
import { useToast } from '../shared/Toast';
import ReadError from '../shared/ReadError';
import Field from '../shared/Field';
import Loading from '../shared/Loading';
import SubmitButton from '../shared/SubmitButton';
import { useFormValidation } from '../../hooks/useFormValidation';


const log = (...args) => {
  if (process.env.NODE_ENV !== 'production') console.error('[BusinessProfileView]', ...args);
};

const errBody = (e) => humanizeError(e)?.body || 'Unknown error';

const FIELD = {
  legal_name:       { label: 'Legal name',                 max: 200, required: true },
  ein:              { label: 'EIN (XX-XXXXXXX)',           max: 11 },
  street_address:   { label: 'Street address',             max: 200 },
  city:             { label: 'City',                       max: 80 },
  state_province:   { label: 'State / Province',           max: 80 },
  postal_code:      { label: 'Postal code',                max: 20 },
  country:          { label: 'Country',                    max: 80 },
  contact_email:    { label: 'Contact email',              max: 254 },
  contact_phone:    { label: 'Contact phone',              max: 30 },
  footer_text:      { label: 'Invoice footer text',        max: 500, multiline: true },
};

/**
 * The one required field, as a rule the hook can read.
 *
 * It was enforced twice in code and stated nowhere on screen: `handleSave` returned early and
 * Save carried its own `!legal_name.trim()`, so clearing the box produced a permanently grey
 * button beside an "Unsaved changes" dot and no sentence saying which field. One rule, read by
 * the message and by the button.
 */
const RULES = {
  legal_name: { required: true, message: 'Legal name is required. It is the FROM name on every issued invoice.' },
};

export default function BusinessProfileView() {
  const askConfirm = useConfirm();
  const toast = useToast();
  const [profile, setProfile]           = useState(null);
  const [paymentTerms, setPaymentTerms] = useState([]);
  const [loading, setLoading]           = useState(true);
  // The third state. The fallback below carries no `id`, so a form built on it INSERTS on the
  // first Save: a refused read produced a second active business_profile row, after which the
  // invoice PDF's .maybeSingle() raises PGRST116 and Form 1065 picks one of the two.
  const [loadError, setLoadError]       = useState(null);
  const [saving, setSaving]             = useState(false);
  const [savedAt, setSavedAt]           = useState(null);
  const [dirty, setDirty]               = useState(false);
  const v = useFormValidation(RULES);
  const [legacyState, setLegacyState]   = useState({ running: false, total: 0, done: 0, skipped: 0, errored: 0, lastError: null });

  const fetchAll = useCallback(async () => {
    setLoading(true);
    setLoadError(null);
    const [{ data: bp, error: bpErr }, { data: terms, error: termsErr }] = await Promise.all([
      supabase.from('business_profile').select('*').eq('is_active', true).maybeSingle(),
      supabase.from('payment_terms').select('*').eq('is_active', true).order('sort_order').order('name'),
    ]);
    if (bpErr || termsErr) {
      log('fetch profile', bpErr || termsErr);
      setLoadError(bpErr || termsErr);
      setProfile(null);
      setPaymentTerms([]);
      setLoading(false);
      return;
    }
    setProfile(bp || { legal_name: 'Nysterys Media LLC', country: 'United States', is_active: true });
    setPaymentTerms(terms || []);
    setDirty(false);
    setLoading(false);
  }, []);

  useEffect(() => { fetchAll(); }, [fetchAll]);

  const set = (key) => (e) => {
    const val = typeof e === 'string' ? e : e.target.value;
    setProfile((p) => ({ ...p, [key]: val }));
    setSavedAt(null);
    setDirty(true);
    // On CHANGE rather than on blur, because Save greys out on the same keystroke and a
    // disabled control cannot report its own reason. Trimmed, so a box of spaces is a blank.
    const msg = v.validateField(key, typeof val === 'string' ? val.trim() : val);
    if (msg) v.setErrors((errs) => ({ ...errs, [key]: msg }));
    else v.clear(key);
  };

  async function handleSave() {
    if (!v.validate({ ...profile, legal_name: String(profile.legal_name || '').trim() })) return;
    setSaving(true);
    const payload = { ...profile, legal_name: profile.legal_name.trim() };
    Object.keys(FIELD).forEach((k) => {
      if (typeof payload[k] === 'string') {
        payload[k] = payload[k].slice(0, FIELD[k].max).trim();
        if (payload[k] === '') payload[k] = null;
      }
    });
    delete payload.id;
    delete payload.updated_at;

    let result;
    if (profile.id) {
      result = await supabase.from('business_profile').update(payload).eq('id', profile.id).select().single();
    } else {
      result = await supabase.from('business_profile').insert(payload).select().single();
    }
    if (result.error) {
      log('save', result.error);
      toast.error({ title: 'Save failed', body: errBody(result.error) });
    } else {
      setProfile(result.data);
      setSavedAt(new Date());
      setDirty(false);
    }
    setSaving(false);
  }

  /**
   * Backfill: render + store an issued-invoice PDF for every billed invoice that
   * lacks one. Idempotent (skips invoices that already have a current doc), so it
   * is safe to re-run; serial to keep storage writes simple, not for speed.
   */
  async function generateLegacyPdfs() {
    if (!(await askConfirm({ title: 'Generate issued invoice PDFs?', body: 'Creates a PDF for every billed invoice missing one. May take a few minutes.', confirmLabel: 'Generate' }))) return;
    setLegacyState({ running: true, total: 0, done: 0, skipped: 0, errored: 0, lastError: null });

    const { data: statusRows, error: stErr } = await supabase
      .from('status_options').select('id,value').eq('group_key', 'payment').in('value', BILLED_PAYMENT_VALUES);
    if (stErr) { log('status lookup', stErr); setLegacyState((s) => ({ ...s, running: false, lastError: stErr.message })); return; }
    const billedIds = (statusRows || []).map((r) => r.id);
    if (billedIds.length === 0) {
      setLegacyState({ running: false, total: 0, done: 0, skipped: 0, errored: 0, lastError: 'No billed payment statuses configured' });
      return;
    }
    const { data: invoices, error: invErr } = await supabase
      .from('invoices').select('id').in('payment_status_id', billedIds);
    if (invErr) { log('invoice list', invErr); setLegacyState((s) => ({ ...s, running: false, lastError: invErr.message })); return; }

    const ids = (invoices || []).map((r) => r.id);
    setLegacyState((s) => ({ ...s, total: ids.length }));

    let done = 0;
    let skipped = 0;
    let errored = 0;
    let lastError = null;
    for (const id of ids) {
      try {
        // A refused probe is not "no PDF yet": generating over it supersedes the version the
        // agency already holds. The catch below counts it as errored and names it.
        const { doc: existing, error: probeErr } = await loadCurrentDoc(id, 'issued_invoice');
        if (probeErr) throw probeErr;
        if (existing) { skipped += 1; }
        else {
          await generateAndUploadIssuedInvoice(id);
          done += 1;
        }
      } catch (e) {
        log('legacy gen', id, e);
        errored += 1;
        lastError = e?.message || String(e);
      }
      setLegacyState({ running: true, total: ids.length, done, skipped, errored, lastError });
    }
    setLegacyState({ running: false, total: ids.length, done, skipped, errored, lastError });
  }

  if (loading) return <div className="page"><Loading /></div>;
  if (loadError) return <div className="page"><ReadError error={loadError} onRetry={fetchAll} /></div>;

  const input = (key) => {
    const f = FIELD[key];
    const val = profile[key] || '';
    const err = v.errors[key];
    return (
      <Field key={key} label={`${f.label}${f.required ? ' *' : ''}`}>
        {(id) => (<>
          {f.multiline ? (
            <textarea id={id} className="form-textarea" rows={3} maxLength={f.max} value={val} {...v.fieldProps(key)} onChange={set(key)} />
          ) : (
            <input id={id} className="form-input" type="text" maxLength={f.max} value={val} {...v.fieldProps(key)} onChange={set(key)} />
          )}
          {err ? <div {...v.errorProps(key)}>{err}</div> : null}
        </>)}
      </Field>
    );
  };

  const legacyTouched = legacyState.done || legacyState.skipped || legacyState.errored || legacyState.lastError;

  return (
    <div className="page">
      <div className="page-header">
        <h1 className="page-title">BUSINESS PROFILE<HelpIcon slug="business-profile" /></h1>
      </div>

      <div className="editorial-form">
          <div className="editorial-row">
            <div className="editorial-eyebrow">Identity</div>
            <div className="editorial-grid cols-2">
              {input('legal_name')}
              {input('ein')}
            </div>
          </div>

          <div className="editorial-row">
            <div className="editorial-eyebrow">Mailing</div>
            <div>
              {input('street_address')}
              <div className="editorial-grid cols-4" style={{ marginTop: 12 }}>
                {input('city')}
                {input('state_province')}
                {input('postal_code')}
                {input('country')}
              </div>
            </div>
          </div>

          <div className="editorial-row">
            <div className="editorial-eyebrow">Contact</div>
            <div className="editorial-grid cols-2">
              {input('contact_email')}
              {input('contact_phone')}
            </div>
          </div>

          <div className="editorial-row">
            <div className="editorial-eyebrow">Defaults</div>
            <div>
              <Field label="Default payment terms">{(id) => (<>
                <select id={id}
                  className="form-select"
                  value={profile.default_payment_terms_id || ''}
                  onChange={set('default_payment_terms_id')}
                >
                  <option value="">None</option>
                  {paymentTerms.map((t) => (
                    <option key={t.id} value={t.id}>{t.name}</option>
                  ))}
                </select>
              </>)}</Field>
              {input('footer_text')}
            </div>
          </div>

          <div className="editorial-row">
            <div className="editorial-eyebrow">Maintenance</div>
            <div>
              <div className="rail-meta" style={{ marginBottom: 12 }}>
                Regenerate the stored invoice PDF for every billed invoice. Invoices that already have one are skipped, so this is safe to re-run.
              </div>
              <button className="btn btn-secondary btn-sm" onClick={generateLegacyPdfs} disabled={legacyState.running || !profile?.id}>
                {legacyState.running ? `Working… ${legacyState.done + legacyState.skipped + legacyState.errored} / ${legacyState.total}` : 'Regenerate invoice PDFs'}
              </button>
              {legacyTouched ? (
                <div className="rail-progress" style={{ marginTop: 10 }}>
                  <div>Generated <strong>{legacyState.done}</strong></div>
                  <div>Skipped <strong>{legacyState.skipped}</strong></div>
                  <div>Errored <strong style={{ color: legacyState.errored ? 'var(--red)' : undefined }}>{legacyState.errored}</strong></div>
                  {legacyState.lastError ? <div style={{ color: 'var(--red)' }}>Last error: {legacyState.lastError}</div> : null}
                </div>
              ) : null}
            </div>
          </div>
      </div>

      {(dirty || saving || savedAt) ? (
        <div className="save-bar">
          <div className="save-bar-status">
            {dirty ? (<><span className="save-bar-dot" /> Unsaved changes</>)
              : savedAt ? <>Saved {savedAt.toLocaleTimeString()}</>
              : null}
          </div>
          {dirty ? (
            <button className="btn btn-ghost btn-sm" onClick={fetchAll} disabled={saving}>Discard</button>
          ) : null}
          <SubmitButton saving={saving} className="btn btn-primary btn-sm" onClick={handleSave} disabled={saving || !dirty || !!v.errors.legal_name}>Save</SubmitButton>
        </div>
      ) : null}
    </div>
  );
}
