/**
 * components/admin/CreatorDestinations.js: one creator's payout accounts, the share of her
 * paycheck each takes, and the classification that decides whether she has a paycheck at all.
 *
 * The share is a COLUMN, not a panel underneath. It lives on the same database row as the
 * account, and a second list repeating each account by name and last four restated what was
 * already on screen one row above. Editing puts every share cell into edit mode at once,
 * because they save in one statement.
 *
 * @gotcha the whole creator's shares go in ONE upsert. `trg_check_payroll_pct_sum` is AFTER
 *         ROW, so it judges the finished statement, and a per-row save would be refused at the
 *         first 25. @see components/shared/PaycheckSplit.js
 * @see components/admin/PaymentSetupView.js, which owns the section this sits in
 */
import React from 'react';
import { useSplitEditor, isPayrollTarget, hasShare } from '../shared/PaycheckSplit';
import CompBasisPanel, { BasisChip, currentBasisLabel } from '../shared/CompBasisPanel';
import { todayYMD } from '../../utils/format';
import { InstitutionLogo } from '../shared/PaymentLogos';
import SubmitButton from '../shared/SubmitButton';
import Feedback from '../shared/Feedback';

const TYPE_COLOR = {
  Checking:   'var(--blue)',
  Savings:    'var(--green)',
  UTMA:       '#a78bfa',
  Investment: 'var(--orange)',
  Other:      'var(--muted)',
};


/**
 * One creator's payout accounts, the shares of her paycheck they take, and the classification
 * that decides whether she has a paycheck at all.
 *
 * The share is a COLUMN, not a panel: it lives on the same database row as the account, and a
 * second list repeating each account by name and last four restated what was already on screen.
 * Editing puts every share cell into edit mode at once, because they save in one statement.
 *
 * @gotcha the whole creator's shares go in ONE upsert. `trg_check_payroll_pct_sum` is AFTER
 *         ROW, so it judges the finished statement, and a per-row save would be refused at the
 *         first 25. @see components/shared/PaycheckSplit.js
 */
export default function CreatorDestinations({
  creator, destinations, compBases, closedYears, basisOpen, onToggleBasis,
  onAdd, onEdit, onToggle, onDelete, onNavigateToLedger, onSaved,
}) {
  const split = useSplitEditor(destinations, onSaved);
  const today = todayYMD();
  const basisLabel = currentBasisLabel(compBases, creator.id, today);

  return (
    <div>
      {/* Creator header */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '10px 0', borderBottom: '2px solid var(--surface2)' }}>
        <span style={{ fontWeight: 700, fontSize: 13, letterSpacing: '0.04em' }}>
          {(creator.creator_name || creator.full_name).toUpperCase()}
        </span>
        {basisLabel && <BasisChip label={basisLabel} open={basisOpen} onToggle={onToggleBasis} />}
        <div style={{ marginLeft: 'auto', display: 'flex', gap: 4 }}>
          {split.canEdit && !split.editing && (
            <button className="btn btn-ghost btn-sm" onClick={split.start}>
              {split.hasAnyShare ? 'Edit split' : 'Set split'}
            </button>
          )}
          <button className="btn btn-ghost btn-sm" style={{ color: 'var(--white)' }} onClick={onAdd}>
            + Add Destination
          </button>
        </div>
      </div>

      {basisOpen && (
        <CompBasisPanel creator={creator} rows={compBases} closedYears={closedYears}
          today={today} onSaved={onSaved} />
      )}

      {split.error && <Feedback value={split.error} style={{ margin: '12px 0 0' }} />}

      {/* Destinations table */}
      <div className="table-wrap" style={{ marginTop: 0, borderTopLeftRadius: 0, borderTopRightRadius: 0 }}
           {...split.dirtyProps}>
        <table className="pinned-actions" style={{ width: '100%' }}>
          <thead>
            <tr>
              <th scope="col"></th><th scope="col">Destination</th><th scope="col">Type</th>
              <th scope="col">Account</th><th scope="col">Memo</th>
              <th scope="col" className="dest-split-col">Split</th>
              <th scope="col">Status</th><th scope="col"></th>
            </tr>
          </thead>
          <tbody>
            {destinations.map(d => (
              <tr key={d.id} style={{ opacity: d.is_active ? 1 : 0.5 }}>
                <td style={{ paddingRight: 0 }}><InstitutionLogo institution={d.institution} size={24} /></td>
                <td style={{ fontWeight: 500 }}>
                  {d.name}
                  {d.is_deferred && (
                    <span title="Deferred: money stays in the LLC checking account; splits cannot be marked cleared until you flip this off."
                      style={{ marginLeft: 8, fontSize: 10, fontWeight: 700, letterSpacing: 0.5, textTransform: 'uppercase', color: 'var(--orange2)', border: '1px solid var(--orange2)', padding: '1px 6px', borderRadius: 4 }}>
                      Deferred
                    </span>
                  )}
                </td>
                <td>
                  <span style={{ fontSize: 11, fontWeight: 600, color: TYPE_COLOR[d.account_type] || 'var(--muted)', textTransform: 'uppercase', letterSpacing: 0.5 }}>
                    {d.account_type}
                  </span>
                </td>
                <td style={{ fontSize: 12, color: 'var(--muted)' }}>
                  {d.institution && <span>{d.institution}</span>}
                  {d.institution && d.account_last4 && <span style={{ color: 'var(--dim)' }}> · </span>}
                  {d.account_last4 && <span>···· {d.account_last4}</span>}
                  {!d.institution && !d.account_last4 && <span className="text-muted">—</span>}
                </td>
                <td style={{ fontSize: 12, color: 'var(--muted)' }}>
                  {d.memo || <span className="text-muted">—</span>}
                </td>
                <td className="dest-split-col">
                  <SplitCell d={d} split={split} />
                </td>
                <td>
                  <span className={`badge ${d.is_active ? 'badge-orange' : 'badge-red-soft'}`}>
                    {d.is_active ? 'Active' : 'Inactive'}
                  </span>
                </td>
                <td>
                  <div className="flex gap-8">
                    {d.ledger_account?.code && onNavigateToLedger ? (
                      <button
                        className="btn btn-ghost btn-sm"
                        onClick={() => onNavigateToLedger({ tab: 'coa' })}
                        title={`Open ledger account ${d.ledger_account.code} in Financials → Chart of Accounts`}
                        style={{ color: 'var(--blue)' }}
                      >→ {d.ledger_account.code}</button>
                    ) : null}
                    <button className="btn btn-ghost btn-sm" onClick={() => onEdit(d)}>Edit</button>
                    <button className="btn btn-ghost btn-sm" onClick={() => onToggle(d)}>
                      {d.is_active ? 'Deactivate' : 'Activate'}
                    </button>
                    {!d.hasPayouts && (
                      <button className="btn btn-ghost btn-sm" style={{ color: 'var(--red)' }} onClick={() => onDelete(d)}>
                        Delete
                      </button>
                    )}
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
          {/* The total the 100 rule is checked against, in the column it totals. Only while
              editing: at rest every share is on screen and a stored total is arithmetic the
              reader did not ask for. */}
          {split.editing && (
            <tfoot>
              <tr>
                <td colSpan={5} style={{ fontSize: 12, color: 'var(--muted)' }}>
                  Of the net check, after tax withheld. Holds the same split as Gusto.
                </td>
                <td className="dest-split-col">
                  {/* Same shape as an input cell, so the total's digits sit under the digits it
                      totals rather than 15px to their right. */}
                  <span className="dest-split-input">
                    <span role="status" aria-label="Total share" className="dest-split-total"
                      data-off={split.balanced ? 'false' : 'true'}>
                      {split.typed}
                    </span>
                    <span>%</span>
                  </span>
                </td>
                <td colSpan={2}>
                  <div className="flex gap-8" style={{ justifyContent: 'flex-end' }}>
                    {!split.balanced && <span className="dest-split-rule">has to total 100</span>}
                    <button className="btn btn-ghost btn-sm" onClick={split.clear}>Clear</button>
                    <button className="btn btn-ghost btn-sm" onClick={split.cancel}>Cancel</button>
                    <SubmitButton saving={split.saving} className="btn btn-primary btn-sm"
                      onClick={split.save} disabled={split.saving || !split.balanced}>
                      Save split
                    </SubmitButton>
                  </div>
                </td>
              </tr>
            </tfoot>
          )}
        </table>
      </div>
    </div>
  );
}

/**
 * One destination's share of the paycheck.
 *
 * @gotcha an out-of-pocket or deferred bucket can NEVER hold one, which is different from a
 *         payroll account that happens to have none yet. The two read differently or the reader
 *         goes looking for a percentage the database would refuse.
 */
function SplitCell({ d, split }) {
  if (!isPayrollTarget(d)) {
    return <span className="dest-split-never" title="Not a payroll account: a reimbursement or deferred bucket never takes a share of a paycheck.">n/a</span>;
  }
  if (split.editing) {
    return (
      <span className="dest-split-input">
        <input
          className="form-input"
          type="number" min="0" max="100" step="0.01" inputMode="decimal"
          aria-label={`${d.name}, share of the paycheck in percent`}
          value={split.field(d)}
          onChange={e => split.setField(d, e.target.value)} />
        <span>%</span>
      </span>
    );
  }
  return hasShare(d)
    ? <span className="dest-split-value">{Number(d.payroll_pct)}%</span>
    : <span className="text-muted">—</span>;
}
