/**
 * components/admin/SystemHealthView.js: admin System Health dashboard (renderer).
 *
 * Renders the check sweep grouped into sources / jobs / coverage / financial, plus
 * drill-down panels, run history, the public-site probe detail, and Tracked Work.
 * The check logic and polling are NOT here: registry is utils/systemHealthChecks.js
 * and the always-on poller is hooks/useSystemHealth.js. This file only displays
 * what useSystemHealth() exposes (so the view, beacon, and nav dot never disagree).
 *
 * @see docs/CODEBASE.md (System Health), utils/systemHealthChecks.js
 */
import React, { useState, useEffect, useCallback, useRef } from 'react';
import { supabase } from '../../lib/supabase';
import { fmtDate, fmtMoney } from '../../utils/format';
import HelpIcon from '../shared/HelpIcon';
import Loading from '../shared/Loading';
import { openPopup } from '../../utils/openPopup';
import { useSystemHealth } from '../../hooks/useSystemHealth';
import { CHECKS, hoursAgo, agoLabel, runStatus, runStatusLabel } from '../../utils/systemHealthChecks';
import { humanizeError } from '../../utils/errors';
import { healthDetailEvent } from '../../utils/ledgerSourceLink';
import { recordTitle, lineFor } from '../../utils/ledgerCheckCopy';
import { ArrowRightIcon, ChevronIcon } from '../shared/Icon';
import EmptyState from '../shared/EmptyState';
import { activationProps } from '../../utils/rowActivation';
import { useUnsavedGuard } from '../../hooks/useUnsavedGuard';

// ── Status helpers ─────────────────────────────────────────────────────────────
function badgeClass(status) {
  return status === 'healthy' ? 'badge-orange' : status === 'degraded' ? 'badge-amber' : 'badge-red-soft';
}

function pipelineTriggerLabel(meta) {
  const t = meta?.triggered_by || '';
  if (t === 'watchdog') return 'Watchdog';
  if (t === 'startup-recovery') return 'Recovery';
  if (t === 'manual') return 'Manual';
  return 'Coupler';
}

// ── Log line formatter ─────────────────────────────────────────────────────────
function formatLogLine(entry) {
  const d     = new Date(entry.ran_at);
  const date  = fmtDate(d, 'MMM d');
  const time  = d.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true });
  const meta  = entry.meta || {};

  let trigger = meta.triggered_by === 'manual' ? 'manual'
    : meta.triggered_by === 'webhook' ? 'webhook'
    : meta.triggered_by === 'cron'   ? 'cron'
    : meta.status === 'heartbeat'    ? '—'
    : meta.mode || '—';

  let info;
  const isError = entry.failed > 0 && entry.processed === 0;
  if (meta.status === 'heartbeat') {
    info = 'heartbeat';
  } else if (meta.status === 'started') {
    info = 'started';
  } else if (meta.error) {
    info = `error: ${meta.error}`;
  } else if (entry.total === 0 && !meta.steps) {
    info = 'up to date';
  } else if (meta.steps) {
    const d = meta.steps.dedup?.deleted ?? 0;
    const c = meta.steps.cache?.cached ?? 0;
    const s = meta.steps.stats?.synced ?? 0;
    info = `dedup ${d} · cache ${c} · stats ${s}`;
    if (meta.status === 'failed') info += ' · failed';
  } else {
    info = `${entry.processed} processed`;
    if (entry.failed > 0) info += `, ${entry.failed} failed`;
  }

  const isHeartbeat = meta.status === 'heartbeat';
  return { date, time, job: entry.job, trigger, info, isError, isHeartbeat };
}

// ── Main view ──────────────────────────────────────────────────────────────────
export default function SystemHealthView() {
  // Results, polling, and overall status come from the app-wide provider, so
  // the page, the global beacon, and the nav dot always agree.
  const { results, loading, lastRefresh, refreshAll, refreshOne, overall } = useSystemHealth();
  const [running, setRunning]         = useState({});
  const [actionMsg, setActionMsg]     = useState({});
  const [openPanel, setOpenPanel]     = useState(null);
  const [logLines, setLogLines]       = useState([]);
  const [logErr,   setLogErr]         = useState(null);
  const logBodyRef                    = useRef(null);
  // True while the user is tailing the bottom of the log. Starts true so the
  // pane opens on the latest entry; flips false the moment they scroll up.
  const stickToBottomRef              = useRef(true);

  const onLogScroll = useCallback(() => {
    const el = logBodyRef.current;
    if (!el) return;
    stickToBottomRef.current = el.scrollHeight - el.scrollTop - el.clientHeight < 24;
  }, []);

  const fetchLog = useCallback(async () => {
    const { data, error } = await supabase
      .from('automation_log')
      .select('*')
      .order('ran_at', { ascending: false })
      .limit(150);
    // An empty log panel reads as "nothing has run". Say which it is.
    if (error) { setLogErr(humanizeError(error)); return; }
    setLogErr(null);
    if (data) setLogLines([...data].reverse());
  }, []);

  useEffect(() => {
    fetchLog();
    const id = setInterval(fetchLog, 10000);
    return () => clearInterval(id);
  }, [fetchLog]);

  useEffect(() => {
    // Keep the latest entry visible only when the user is already tailing the
    // bottom, and scroll the pane itself (never the page).
    const el = logBodyRef.current;
    if (el && stickToBottomRef.current) el.scrollTop = el.scrollHeight;
  }, [logLines]);

  async function runAction(check, action) {
    setRunning(r => ({ ...r, [check.id]: true }));
    setActionMsg(m => ({ ...m, [check.id]: null }));
    try {
      const result = await action.run(supabase);
      // Async actions (trigger-style) resolve before the job finishes.
      // Sync actions (RPC calls) return data immediately - re-fetch the check.
      const isAsync = result?.data === 'triggered';
      if (isAsync) {
        setActionMsg(m => ({ ...m, [check.id]: { ok: true, text: 'Running in background. Hit Refresh in a minute to see the result' } }));
      } else {
        await refreshOne(check.id);
        setActionMsg(m => ({ ...m, [check.id]: { ok: true, text: 'Done' } }));
      }
    } catch (e) {
      setActionMsg(m => ({ ...m, [check.id]: { ok: false, text: humanizeError(e).body || 'Unknown error' } }));
    }
    setRunning(r => ({ ...r, [check.id]: false }));
  }

  const openCheck  = openPanel ? CHECKS.find(c => c.id === openPanel) : null;
  const openResult = openPanel ? results[openPanel] : null;

  const jobChecks      = CHECKS.filter(c => c.group === 'jobs');
  const sourceChecks   = CHECKS.filter(c => c.group === 'sources');
  const coverageChecks = CHECKS.filter(c => c.group === 'coverage');
  const tileChecks     = CHECKS.filter(c => c.tile);
  const financialCheck = CHECKS.find(c => c.group === 'financial');

  const refreshLabel = lastRefresh
    ? lastRefresh.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true })
    : null;

  // `overall` is the provider's single source - same value the global beacon
  // and the System Health nav dot consume, so the three can never disagree.
  const overallStatus = overall;

  return (
    <div className="page">
      <div className="page-header">
        <div>
          <h1 className="page-title">SYSTEM HEALTH<HelpIcon slug="system-health" /></h1>
          {overallStatus && (
            <div className="page-subtitle" style={{ color: overallStatus === 'healthy' ? 'var(--green)' : overallStatus === 'degraded' ? 'var(--orange2)' : 'var(--red)' }}>
              {overallStatus === 'healthy' ? `All systems operational · ${refreshLabel}` : overallStatus === 'degraded' ? `Degraded · ${refreshLabel}` : `Issues detected · ${refreshLabel}`}
            </div>
          )}
          {loading && <div className="page-subtitle">Checking systems…</div>}
        </div>
        <button className="btn btn-ghost" onClick={refreshAll} disabled={loading}>
          {loading ? 'Checking…' : 'Refresh'}
        </button>
      </div>

      {/* ── Financial Health: its own section, above the operational plumbing ── */}
      {financialCheck && (
        <FinancialHealthSection
          check={financialCheck}
          result={results[financialCheck.id]}
          loading={loading}
          running={!!running[financialCheck.id]}
          actionMsg={actionMsg[financialCheck.id] ?? null}
          onRunAction={(action) => runAction(financialCheck, action)}
        />
      )}

      {/* ── Status strip ── */}
      <div className="health-strip">
        {tileChecks.map((check, i) => {
          const result  = results[check.id];
          const status  = loading ? 'loading' : (result?.status || 'loading');
          const divided = i < tileChecks.length - 1;
          return (
            <div
              key={check.id}
              className={`health-strip-item${divided ? ' health-strip-item--divided' : ''}`}
              {...activationProps(() => result && setOpenPanel(check.id), { expanded: openPanel === check.id })}
              title={check.description}
            >
              <div className="health-strip-label">
                <span className={`health-dot health-dot--${status}`} />
                {check.label}
              </div>
              <div className={`health-strip-value health-strip-value--${status}`}>
                {result ? result.summary : '—'}
              </div>
            </div>
          );
        })}
      </div>

      {/* ── Main grid ── */}
      <div className="health-content-grid">
        <div>
          <div className="health-section-label">Automation Jobs</div>
          <div className="health-job-list">
            {jobChecks.map(check => (
              <HealthJobRow
                key={check.id}
                check={check}
                result={results[check.id]}
                running={!!running[check.id]}
                onRunAction={(action) => runAction(check, action)}
                onOpen={() => setOpenPanel(check.id)}
              />
            ))}
          </div>
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: 28 }}>
          <div>
            <div className="health-section-label">Data Sources</div>
            <div className="health-job-list">
              {sourceChecks.map(check => (
                <HealthSourceRow
                  key={check.id}
                  check={check}
                  result={results[check.id]}
                  onOpen={() => setOpenPanel(check.id)}
                />
              ))}
            </div>
          </div>
          <div>
            <div className="health-section-label">Content Coverage</div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
              {coverageChecks.map(check => (
                <HealthCoverageMeter
                  key={check.id}
                  check={check}
                  result={results[check.id]}
                  onOpen={() => setOpenPanel(check.id)}
                />
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* ── Drill-down panel ── */}
      {openPanel && openCheck && (
        <>
          <div aria-hidden="true" style={{ position: 'fixed', inset: 0, zIndex: 149 }} onClick={() => setOpenPanel(null)} />
          <DrillDownPanel
            check={openCheck}
            result={openResult}
            running={!!running[openPanel]}
            actionMsg={actionMsg[openPanel] ?? null}
            onRunAction={(action) => runAction(openCheck, action)}
            onClose={() => setOpenPanel(null)}
          />
        </>
      )}

      {/* ── Tracked work: open GitHub project issues, its own section ── */}
      <ProjectIssuesSection />

      {/* ── Live activity log ── */}
      <div className="health-log-panel">
        <div className="health-log-header">
          <span className="health-log-title">Activity Log</span>
          <span className="health-log-live">
            <span className="health-log-live-dot" />
            Live
          </span>
        </div>
        <div className="health-log-body" ref={logBodyRef} onScroll={onLogScroll}>
          {logErr && (
            <div style={{ padding: '8px 16px', color: 'var(--orange)' }}>{logErr.title || 'Could not read the activity log.'}</div>
          )}
          {/* --muted, not a hairline token: --border2 read 1.35:1 on this #0d0d0d body. */}
          {!logErr && logLines.length === 0 && (
            <EmptyState variant="note" text="No activity yet." style={{ padding: '8px 16px' }} />
          )}
          {logLines.map(entry => {
            const { date, time, job, trigger, info, isError, isHeartbeat } = formatLogLine(entry);
            const lineClass = `health-log-line${isError ? ' health-log-line--error' : isHeartbeat ? ' health-log-line--dim' : ''}`;
            return (
              <div key={entry.id} className={lineClass}>
                <span className="health-log-col-time">{date}&nbsp;&nbsp;{time}</span>
                <span className="health-log-col-job">{job}</span>
                <span className="health-log-col-trigger">{trigger}</span>
                <span className="health-log-col-info">{info}</span>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

// ── Sub-components ─────────────────────────────────────────────────────────────

function HealthJobRow({ check, result, running, onRunAction, onOpen }) {
  const status         = result?.status || 'loading';
  const isFailed       = status === 'failed';
  // Listener badge lives on the pipeline tile (the VPS daemon serves it)
  const listenerOnline = result?.extra?.listenerOnline;
  const showListener   = check.id === 'pipeline' && result;
  // Only non-panelOnly actions appear in the row
  const rowActions     = (check.actions || []).filter(a => !a.panelOnly);

  return (
    /* This row is the ONE that carries its own action buttons, so it cannot be a button
       itself: a control inside a control is a serious `nested-interactive` violation and a
       screen reader reads neither. The title is the button, stretched over the row by
       `.health-job-open::after`, with the actions raised above it. The other rows in this
       file have no nested control and use `activationProps` directly. */
    <div className={`health-job-row health-job-row--stretch${isFailed ? ' health-job-row--failed' : ''}`}>
      <span className={`health-dot health-dot--${status}`} style={{ flexShrink: 0 }} />
      <button type="button" className="health-job-name health-job-open" onClick={onOpen}>
        {check.title}
      </button>
      {result && <span className="health-job-summary">{result.summary}</span>}
      {showListener && (
        <span
          style={{ fontSize: 10, color: listenerOnline ? 'var(--green)' : 'var(--dim)', flexShrink: 0 }}
          title={listenerOnline ? 'sync-server daemon is running on the VPS' : 'sync-server daemon appears offline. Check `systemctl status nysterys-sync` on the VPS'}
        >
          <span style={{ display: 'inline-block', width: 7, height: 7, borderRadius: '50%', marginRight: 6, verticalAlign: 'middle', background: listenerOnline ? 'currentColor' : 'transparent', border: listenerOnline ? 'none' : '1.5px solid currentColor', boxSizing: 'border-box' }} />
          listener
        </span>
      )}
      {rowActions.map(action => (
        <button
          key={action.label}
          className="btn btn-ghost btn-sm health-job-action"
          disabled={running}
          onClick={e => { e.stopPropagation(); onRunAction(action); }}
        >
          {running ? action.loadingLabel : action.label}
        </button>
      ))}
    </div>
  );
}

function HealthSourceRow({ check, result, onOpen }) {
  const status = result?.status || 'loading';
  const extra  = result?.extra || {};
  return (
    <div className={`health-job-row${status === 'failed' ? ' health-job-row--failed' : ''}`} {...activationProps(onOpen)}>
      <span className={`health-dot health-dot--${status}`} style={{ flexShrink: 0 }} />
      <span className="health-job-name">{check.title}</span>
      {extra.synced_at && (
        <span style={{ fontSize: 11, color: 'var(--dim)', marginRight: 4 }}>
          {new Date(extra.synced_at).toLocaleString('en-US', { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit', hour12: true })}
        </span>
      )}
      <span className={`health-strip-value health-strip-value--${status}`} style={{ fontSize: 16 }}>
        {result?.summary || '—'}
      </span>
    </div>
  );
}

// Public site drill-down: the three layers a visitor depends on, each with a
// pass/fail dot, plus a way to open the live site.
function PublicSiteRow({ status, label, detail }) {
  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '7px 2px', borderTop: '1px solid var(--border)' }}>
      <span className={`health-dot health-dot--${status}`} style={{ flexShrink: 0 }} />
      <span style={{ fontSize: 12, color: status === 'failed' ? 'var(--white)' : 'var(--dim)', fontWeight: status === 'failed' ? 600 : 300 }}>{label}</span>
      <span style={{ fontSize: 11, color: 'var(--dim)', marginLeft: 'auto', flexShrink: 0 }}>{detail}</span>
    </div>
  );
}

function PublicSiteDetail({ extra }) {
  const { feeds = [], photos, page, checkedSite } = extra;
  return (
    <div className="detail-section">
      <h3 className="detail-section-title">What a visitor sees</h3>

      <div style={{ fontSize: 10, fontWeight: 600, textTransform: 'uppercase', letterSpacing: '1.5px', color: 'var(--muted)', margin: '6px 0 2px' }}>
        Stat feeds (read with the public key)
      </div>
      {/* Labels strip only the _view suffix. The platform prefix used to be
          stripped for TikTok alone, which read fine when TikTok was 4 of the 5
          feeds but looks like a missing label now that YouTube and Instagram
          rows sit in the same list showing theirs. */}
      {feeds.map(f => (
        <PublicSiteRow
          key={f.name}
          status={(f.ok && f.rows > 0) ? 'healthy' : 'failed'}
          label={f.name.replace(/_view$/, '').replace(/_/g, ' ')}
          detail={f.ok ? (f.rows > 0 ? 'rows OK' : 'no rows') : `HTTP ${f.status || 'error'}`}
        />
      ))}

      <div style={{ fontSize: 10, fontWeight: 600, textTransform: 'uppercase', letterSpacing: '1.5px', color: 'var(--muted)', margin: '16px 0 2px' }}>
        Creator photos
      </div>
      {checkedSite && photos
        ? photos.map(p => (
            <PublicSiteRow
              key={p.path}
              status={p.ok ? 'healthy' : 'failed'}
              label={`/${p.path}`}
              detail={p.ok ? 'loads' : `HTTP ${p.status || 'error'}`}
            />
          ))
        : <div style={{ fontSize: 11, color: 'var(--dim)', padding: '7px 2px' }}>Not checked off-production.</div>}

      <div style={{ fontSize: 10, fontWeight: 600, textTransform: 'uppercase', letterSpacing: '1.5px', color: 'var(--muted)', margin: '16px 0 2px' }}>
        Homepage
      </div>
      {checkedSite && page
        ? <PublicSiteRow status={page.ok ? 'healthy' : 'failed'} label="nysterys.com" detail={page.ok ? 'responds' : `HTTP ${page.status || 'error'}`} />
        : <div style={{ fontSize: 11, color: 'var(--dim)', padding: '7px 2px' }}>Not checked off-production.</div>}

      <button className="btn btn-ghost btn-sm" style={{ marginTop: 14, paddingLeft: 0 }} onClick={() => openPopup('https://nysterys.com')}>
        Open nysterys.com
      </button>
    </div>
  );
}

function HealthCoverageMeter({ check, result, onOpen }) {
  const status = result?.status || 'loading';
  const extra  = result?.extra || {};
  const pct    = extra.pct ?? 0;
  const label  = check.id === 'thumbnail-coverage' ? 'Thumbnails' : 'Music';
  const detail = check.id === 'thumbnail-coverage'
    ? `${extra.cached ?? 0} cached · ${extra.uncached ?? 0} uncached`
    : `${extra.enriched ?? 0} enriched · ${extra.missing ?? 0} missing`;

  return (
    <div className="health-coverage-meter" {...activationProps(onOpen)}>
      <div className="health-coverage-header">
        <div className="flex items-center gap-8">
          <span className={`health-dot health-dot--${status}`} />
          <span style={{ fontSize: 12, fontWeight: 600 }}>{label}</span>
          {result && <span style={{ fontSize: 11, color: 'var(--dim)', fontWeight: 300 }}>{detail}</span>}
        </div>
        <span className={`health-strip-value health-strip-value--${status}`} style={{ fontSize: 20 }}>
          {result ? `${pct}%` : '—'}
        </span>
      </div>
      <div className="health-progress-bar" style={{ marginTop: 8 }}>
        <div
          className={`health-progress-fill${status !== 'healthy' ? ` health-progress-fill--${status}` : ''}`}
          style={{ width: result ? `${pct}%` : '0%' }}
        />
      </div>
    </div>
  );
}

function DrillDownPanel({ check, result, running, actionMsg, onRunAction, onClose }) {
  const { dirtyProps } = useUnsavedGuard();
  const status        = result ? result.status : 'loading';
  const primaryActions  = (check.actions || []).filter(a => !a.panelOnly);
  const recoveryActions = (check.actions || []).filter(a => a.panelOnly);

  return (
    <div className="detail-panel" {...dirtyProps}>
      <div className="detail-header">
        <div style={{ flex: 1, minWidth: 0 }}>
          <div className="flex items-center gap-8" style={{ marginBottom: 4 }}>
            <span className={`health-dot health-dot--${status}`} />
            <h2 className="detail-panel-title">
              {check.title.toUpperCase()}
            </h2>
          </div>
          <div style={{ fontSize: 11, color: 'var(--muted)', marginLeft: 15, lineHeight: 1.4 }}>{check.description}</div>
        </div>
        <button className="btn btn-ghost btn-icon" onClick={onClose} aria-label="Close check details" style={{ flexShrink: 0 }}>✕</button>
      </div>

      <div className="detail-body">
        {/* Alert banner */}
        {result?.tip && (
          <div style={{
            background: status === 'failed' ? 'rgba(239,68,68,0.08)' : 'rgba(251,146,60,0.08)',
            border: `1px solid ${status === 'failed' ? 'rgba(239,68,68,0.2)' : 'rgba(251,146,60,0.2)'}`,
            borderRadius: 8, padding: '12px 14px', marginBottom: 20,
          }}>
            <div style={{ fontSize: 9, fontWeight: 600, textTransform: 'uppercase', letterSpacing: '1.5px', color: status === 'failed' ? 'var(--red)' : 'var(--orange2)', marginBottom: 5 }}>
              {status === 'failed' ? 'Action Required' : 'Attention'}
            </div>
            <div style={{ fontSize: 12, color: 'var(--white)', lineHeight: 1.6 }}>{result.tip}</div>
          </div>
        )}

        {/* Actions */}
        {(primaryActions.length > 0 || recoveryActions.length > 0) && (
          <div style={{ marginBottom: 24 }}>
            <h3 className="detail-section-title">Actions</h3>

            {/* Pipeline listener status. Gated on `extra`, not on `result`, the same way the
                coverage breakdown below is: a check whose fetch threw has no `extra`, and
                `!listenerOnline` then reads as a FACT about the VPS rather than as an
                absence. It told an admin to SSH in and restart a service on the evidence of
                a database read that failed. */}
            {check.id === 'pipeline' && result?.extra && (
              <div style={{ marginBottom: 12, fontSize: 12, color: result.extra?.listenerOnline ? 'var(--green)' : 'var(--dim)' }}>
                <span style={{ display: 'inline-block', width: 7, height: 7, borderRadius: '50%', marginRight: 6, verticalAlign: 'middle', background: result.extra?.listenerOnline ? 'currentColor' : 'transparent', border: result.extra?.listenerOnline ? 'none' : '1.5px solid currentColor', boxSizing: 'border-box' }} />
                {result.extra?.listenerOnline
                  ? 'VPS listener is online, trigger will be received immediately'
                  : 'VPS listener appears offline. SSH to the VPS and run: systemctl restart nysterys-sync'}
              </div>
            )}

            {/* Primary action(s) */}
            <div className="flex gap-8" style={{ alignItems: 'center' }}>
              {primaryActions.map(action => (
                <button
                  key={action.label}
                  className="btn btn-secondary"
                  disabled={running}
                  onClick={() => onRunAction(action)}
                >
                  {running ? action.loadingLabel : action.label}
                </button>
              ))}
              {actionMsg && (
                <span style={{ fontSize: 12, color: actionMsg.ok ? 'var(--green)' : 'var(--red)' }}>
                  {actionMsg.text}
                </span>
              )}
            </div>

            {/* Recovery actions (panel-only) */}
            {recoveryActions.length > 0 && (
              <div style={{ marginTop: 14 }}>
                <div style={{ fontSize: 10, fontWeight: 600, textTransform: 'uppercase', letterSpacing: '1.5px', color: 'var(--muted)', marginBottom: 8 }}>
                  Manual overrides
                </div>
                <div className="flex gap-8" style={{ alignItems: 'center' }}>
                  {recoveryActions.map(action => (
                    <button
                      key={action.label}
                      className="btn btn-ghost btn-sm"
                      disabled={running}
                      onClick={() => onRunAction(action)}
                    >
                      {running ? action.loadingLabel : action.label}
                    </button>
                  ))}
                </div>
                <div style={{ fontSize: 11, color: 'var(--dim)', marginTop: 6 }}>
                  Run a single pipeline step without triggering the full sequence. Use for targeted recovery.
                </div>
              </div>
            )}
          </div>
        )}

        {/* Pipeline: last run step breakdown */}
        {check.id === 'pipeline' && result?.history?.length > 0 && (() => {
          const lastRun  = result.history[0];
          const lastYtdlp = result.extra?.lastYtdlp;
          const deleted  = lastRun.meta?.steps?.dedup?.deleted ?? 0;
          const dedupErr = lastRun.meta?.steps?.dedup?.error;
          const cached   = lastRun.meta?.steps?.cache?.cached ?? 0;
          const synced   = lastRun.meta?.steps?.stats?.synced ?? 0;
          const cacheErr = lastRun.meta?.steps?.cache?.error;
          const statsErr = lastRun.meta?.steps?.stats?.error;
          const ytdlpProcessed = lastYtdlp?.processed ?? 0;
          return (
            <div className="detail-section">
              <h3 className="detail-section-title">Last Run Steps</h3>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr 1fr', gap: 10, marginBottom: 8 }}>
                <StatMini
                  label="Dedup"
                  value={dedupErr ? 'Error' : deleted}
                  color={dedupErr ? 'var(--red)' : deleted > 0 ? 'var(--green)' : undefined}
                />
                <StatMini
                  label="Cache"
                  value={cacheErr ? 'Error' : cached}
                  color={cacheErr ? 'var(--red)' : cached > 0 ? 'var(--green)' : undefined}
                />
                <StatMini
                  label="Stats"
                  value={statsErr ? 'Error' : synced}
                  color={statsErr ? 'var(--red)' : synced > 0 ? 'var(--green)' : undefined}
                />
                <StatMini
                  label="Music"
                  value={ytdlpProcessed > 0 ? ytdlpProcessed : '—'}
                  color={ytdlpProcessed > 0 ? 'var(--green)' : undefined}
                />
              </div>
              <div style={{ fontSize: 11, color: 'var(--dim)' }}>
                {pipelineTriggerLabel(lastRun.meta)} · {new Date(lastRun.ran_at).toLocaleString('en-US', { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit', hour12: true })}
                {lastYtdlp && (
                  <span style={{ marginLeft: 12 }}>
                    Music last ran {new Date(lastYtdlp.ran_at).toLocaleString('en-US', { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit', hour12: true })}
                  </span>
                )}
              </div>
            </div>
          );
        })()}

        {/* Gated on pct, never on the group: three of the five coverage checks measure no proportion and drew an empty breakdown. @see __tests__/coverageBreakdownScope.test.js */}
        {check.group === 'coverage' && Number.isFinite(result?.extra?.pct) && (
          <div className="detail-section">
            <h3 className="detail-section-title">Coverage Breakdown</h3>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 10, marginBottom: 14 }}>
              {check.id === 'thumbnail-coverage' ? (
                <>
                  <StatMini label="Total Videos" value={result.extra.total} />
                  <StatMini label="Cached" value={result.extra.cached} color="var(--green)" />
                  <StatMini label="Uncached" value={result.extra.uncached} color={result.extra.uncached > 0 ? 'var(--red)' : 'var(--dim)'} />
                </>
              ) : (
                <>
                  <StatMini label="Total Videos" value={result.extra.total} />
                  <StatMini label="Enriched" value={result.extra.enriched} color="var(--green)" />
                  <StatMini label="Missing" value={result.extra.missing} color={result.extra.missing > 0 ? 'var(--red)' : 'var(--dim)'} />
                </>
              )}
            </div>
            <div className="health-progress-bar" style={{ height: 8 }}>
              <div
                className={`health-progress-fill${result.status !== 'healthy' ? ` health-progress-fill--${result.status}` : ''}`}
                style={{ width: `${result.extra.pct}%` }}
              />
            </div>
          </div>
        )}

        {/* Source detail */}
        {check.group === 'sources' && result?.extra?.synced_at && (
          <div className="detail-section">
            <h3 className="detail-section-title">Last Sync</h3>
            <div style={{ fontSize: 15, fontWeight: 700, marginBottom: 4 }}>
              {new Date(result.extra.synced_at).toLocaleString('en-US', { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric', hour: 'numeric', minute: '2-digit', hour12: true })}
            </div>
            <div style={{ fontSize: 11, color: 'var(--muted)' }}>Expected every ~8 hours (6AM, 12PM, 6PM CDT)</div>
          </div>
        )}

        {/* Public site: what a visitor sees, layer by layer */}
        {check.id === 'public-site' && result?.extra && (
          <PublicSiteDetail extra={result.extra} />
        )}

        {/* Run history */}
        {result?.history?.length > 0 && (
          <div className="detail-section">
            <h3 className="detail-section-title">Run History</h3>
            {check.id === 'pipeline'
              ? <PipelineHistoryTable runs={result.history} />
              : <HistoryTable check={check} runs={result.history} />
            }
          </div>
        )}

        {result?.history?.length === 0 && check.group === 'jobs'
          && <EmptyState variant="note" text="No runs logged yet." />}
      </div>
    </div>
  );
}

// Financial Health - its own elevated page section (not a strip tile / not a
// drawer). The plumbing stays boxed in its grid; the money question sits on the
// open canvas above it, framed only by Bebas, a hairline, and space.
/**
 * One offending record inside a failing invariant: what it is called, one line of supporting
 * fact, and a quiet deep-link to the page that fixes it. Reuses the `.ledger-srclink`
 * treatment the GL and Reconcile Bank lines already use, so the gesture is one the reader has
 * met before.
 *
 * Every word here comes from `utils/ledgerCheckCopy.js` and every destination from
 * `healthDetailEvent`. This component reads NO field of `d` itself beyond passing it on, which
 * is deliberate: the row it replaces read `invoice_number` and `days` directly, so when the
 * query stopped shipping them it drew a blank name and "waiting 0 days" instead of failing.
 *
 * @param {object} props
 * @param {string} props.checkId - the invariant this record belongs to, which decides its line
 * @param {object} props.d - one entry from that check's `details`
 * @gotcha a real <button> so it is keyboard reachable; stopPropagation keeps a click from also
 *         collapsing the invariant row it sits under.
 */
function HealthRecordRow({ checkId, d }) {
  const evt   = healthDetailEvent(d);
  const title = recordTitle(d);
  const line  = lineFor(checkId, d);
  const body = (
    <>
      {title && <span style={{ fontWeight: 500 }}>{title}</span>}
      {line && <span style={{ color: 'var(--dim)' }}>{title ? ' · ' : ''}{line}</span>}
    </>
  );
  if (!evt) return <div className="health-gap-row" style={{ fontSize: 11, padding: '4px 0' }}>{body}</div>;
  return (
    <div className="health-gap-row" style={{ fontSize: 11, padding: '4px 0' }}>
      <button
        type="button"
        className="ledger-srclink"
        title={title ? `Open ${title}` : 'Open this record'}
        onClick={(ev) => {
          ev.stopPropagation();
          window.dispatchEvent(new window.CustomEvent(evt.name, { detail: evt.detail }));
        }}
        onKeyDown={(ev) => { if (ev.key === 'Enter' || ev.key === ' ') ev.stopPropagation(); }}
      >
        <span className="ledger-srclink-text">{body}</span>
        <ArrowRightIcon className="ledger-srclink-arrow" size={11} />
      </button>
    </div>
  );
}

/**
 * One invariant row in the Financial Health list: the rule on the left, its
 * verdict on the right. Every check names its offending records, so the reader can act on the
 * number instead of going hunting for what it refers to.
 *
 * @param {object} props
 * @param {object} props.c - check row {id, label, severity, count, details?}
 * @param {boolean} props.first - suppress the divider above the first row
 * @param {boolean} props.defaultOpen - start with the detail list revealed. True
 *        in "Needs attention", where failing rows are the entire content and the
 *        point is to act; false in the full invariant list, where this is one row
 *        among twenty five and an open list would drown its neighbours.
 * @gotcha `details` is capped server-side at 8 rows; `count` is the true total,
 *         so render the remainder rather than implying the list is complete.
 */
export function LedgerRow({ c, first, defaultOpen = false }) {
  const failed  = (c.count || 0) > 0;
  const listed  = failed && Array.isArray(c.details) ? c.details : [];
  const [open, setOpen] = useState(defaultOpen);
  const tone    = c.severity === 'critical' ? 'var(--red)' : 'var(--orange2)';
  const hidden  = Math.max(0, (c.count || 0) - listed.length);
  const toggles = listed.length > 0;

  const header = (
    <>
      <span style={{ fontSize: 12, color: failed ? 'var(--white)' : 'var(--dim)', fontWeight: failed ? 600 : 300 }}>
        {c.label}
      </span>
      <span style={{
        display: 'inline-flex', alignItems: 'center', gap: 5,
        fontSize: 11, flexShrink: 0, marginLeft: 12,
        color: failed ? tone : 'var(--dim)',
        fontWeight: failed ? 600 : 300,
        letterSpacing: failed ? 0 : '0.5px',
      }}>
        {failed ? `${c.count} found` : 'pass'}
        {toggles && (
          <ChevronIcon
            size={11}
            style={{ transform: open ? 'rotate(90deg)' : 'none', transition: 'transform 140ms ease' }}
          />
        )}
      </span>
    </>
  );

  return (
    <div style={{ borderTop: first ? 'none' : '1px solid var(--border)' }}>
      {toggles ? (
        <button
          type="button"
          className="health-invariant-toggle"
          aria-expanded={open}
          onClick={() => setOpen(o => !o)}
        >
          {header}
        </button>
      ) : (
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '7px 2px' }}>
          {header}
        </div>
      )}

      {toggles && open && (
        <div style={{ padding: '2px 2px 8px 14px' }}>
          {listed.map((d, i) => <HealthRecordRow key={`${d.title || d.code || ''}-${i}`} checkId={c.id} d={d} />)}
          {hidden > 0 && (
            <div style={{ fontSize: 11, color: 'var(--dim)', padding: '4px 0' }}>
              +{hidden} older
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function FinancialHealthSection({ check, result, loading, running, actionMsg, onRunAction }) {
  const [expanded, setExpanded] = useState(false);
  const status   = result?.status || 'loading';
  const extra    = result?.extra || {};
  const neverRun = !!extra.neverRun;
  const checks   = Array.isArray(extra.checks) ? extra.checks : [];
  const failing  = checks.filter(c => (c.count || 0) > 0);
  const crit     = checks.filter(c => c.severity === 'critical');
  const high     = checks.filter(c => c.severity === 'high');
  const last     = extra.last || null;
  const tbDr     = Number(extra.tbDr ?? 0);
  const tbCr     = Number(extra.tbCr ?? 0);
  const diff     = Math.abs(tbDr - tbCr);
  const balanced = diff < 0.005;
  const h        = last ? hoursAgo(last.ran_at) : null;

  const tone = status === 'healthy' ? 'var(--green)'
    : status === 'failed' ? 'var(--red)'
    : status === 'degraded' ? 'var(--orange2)'
    : 'var(--dim)';

  const failedCount = last?.failed || failing.length;
  const verdict = loading && !result ? '—'
    : neverRun ? 'NOT RUN'
    : status === 'healthy' ? 'BALANCED'
    : status === 'failed' ? `${failedCount} ISSUE${failedCount !== 1 ? 'S' : ''}`
    : failing.length ? `${failedCount} TO REVIEW`
    : 'STALE';

  const subline = loading && !result ? 'Checking the books…'
    : neverRun ? 'Never run. Run the check to reconcile the books.'
    : `${checks.length} invariants ${failing.length ? `· ${failing.length} failing ` : 'hold '}· checked ${agoLabel(h)} · ${check.triggerLabel(last)}`;

  const action = (check.actions || [])[0];

  return (
    <div style={{ paddingBottom: 28, marginBottom: 28, borderBottom: '1px solid var(--border)' }}>
      <div className="health-section-label">Financial Health</div>

      {result?.tip && status !== 'healthy' && (
        <div style={{
          background: status === 'failed' ? 'rgba(239,68,68,0.08)' : 'rgba(251,146,60,0.08)',
          border: `1px solid ${status === 'failed' ? 'rgba(239,68,68,0.2)' : 'rgba(251,146,60,0.2)'}`,
          borderRadius: 8, padding: '12px 14px', marginBottom: 18, maxWidth: '80ch',
        }}>
          <div style={{ fontSize: 9, fontWeight: 600, textTransform: 'uppercase', letterSpacing: '1.5px', color: status === 'failed' ? 'var(--red)' : 'var(--orange2)', marginBottom: 5 }}>
            {status === 'failed' ? 'Action Required' : 'Attention'}
          </div>
          <div style={{ fontSize: 12, color: 'var(--white)', lineHeight: 1.6 }}>{result.tip}</div>
        </div>
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 24, flexWrap: 'wrap' }}>
        <div style={{ minWidth: 0 }}>
          <div className="flex items-center gap-8">
            <span className={`health-dot health-dot--${status}`} style={{ flexShrink: 0 }} />
            <span style={{ fontFamily: 'var(--font-display)', fontSize: 34, letterSpacing: 2, color: tone, lineHeight: 1 }}>
              {verdict}
            </span>
          </div>
          <div style={{ fontSize: 12, color: 'var(--dim)', marginTop: 8 }}>{subline}</div>
        </div>

        {action && (
          <div style={{ display: 'flex', alignItems: 'center', gap: 12, flexShrink: 0 }}>
            {actionMsg && (
              <span style={{ fontSize: 12, color: actionMsg.ok ? 'var(--green)' : 'var(--red)' }}>
                {actionMsg.text}
              </span>
            )}
            <button className="btn btn-secondary" disabled={running || (loading && !result)} onClick={() => onRunAction(action)}>
              {running ? action.loadingLabel : action.label}
            </button>
          </div>
        )}
      </div>

      {!neverRun && (result || !loading) && (
        <div style={{ display: 'flex', alignItems: 'baseline', gap: 16, flexWrap: 'wrap', marginTop: 22 }}>
          <div>
            <div style={{ fontFamily: 'var(--font-display)', fontSize: 32, letterSpacing: 1, color: 'var(--white)' }}>{fmtMoney(tbDr)}</div>
            <div style={{ fontSize: 9, textTransform: 'uppercase', letterSpacing: '2px', color: 'var(--muted)', marginTop: 3 }}>Debits</div>
          </div>
          <span style={{ fontSize: 22, color: 'var(--dim)' }}>=</span>
          <div>
            <div style={{ fontFamily: 'var(--font-display)', fontSize: 32, letterSpacing: 1, color: 'var(--white)' }}>{fmtMoney(tbCr)}</div>
            <div style={{ fontSize: 9, textTransform: 'uppercase', letterSpacing: '2px', color: 'var(--muted)', marginTop: 3 }}>Credits</div>
          </div>
          <span style={{ fontSize: 13, fontWeight: 600, marginLeft: 6, alignSelf: 'center', color: balanced ? 'var(--green)' : 'var(--red)' }}>
            {balanced ? 'Balanced' : `Off by ${fmtMoney(diff)}`}
          </span>
        </div>
      )}

      {!neverRun && checks.length > 0 && (
        <div style={{ marginTop: 22, maxWidth: '70ch' }}>
          {failing.length > 0 && !expanded && (
            <>
              <div style={{ fontSize: 10, fontWeight: 600, textTransform: 'uppercase', letterSpacing: '1.5px', color: 'var(--muted)', marginBottom: 4 }}>
                Needs attention
              </div>
              {failing.map((c, i) => <LedgerRow key={c.id} c={c} first={i === 0} defaultOpen />)}
            </>
          )}

          {expanded && (
            <>
              <div style={{ fontSize: 10, fontWeight: 600, textTransform: 'uppercase', letterSpacing: '1.5px', color: 'var(--muted)', marginBottom: 4 }}>
                Critical
              </div>
              {crit.map((c, i) => <LedgerRow key={c.id} c={c} first={i === 0} />)}
              <div style={{ fontSize: 10, fontWeight: 600, textTransform: 'uppercase', letterSpacing: '1.5px', color: 'var(--muted)', margin: '16px 0 4px' }}>
                Checks
              </div>
              {high.map((c, i) => <LedgerRow key={c.id} c={c} first={i === 0} />)}
            </>
          )}

          <button
            className="btn btn-ghost btn-sm"
            style={{ marginTop: failing.length > 0 || expanded ? 12 : 0, paddingLeft: 0 }}
            onClick={() => setExpanded(v => !v)}
          >
            {expanded ? 'Hide invariants' : failing.length > 0 ? `View all ${checks.length}` : `All ${checks.length} invariants hold. View`}
          </button>
        </div>
      )}
    </div>
  );
}

/**
 * Tracked Work: open GitHub issues from the "Nysterys Media LLC" project. Its own
 * section, separate from the operational plumbing.
 *
 * @security Issues load through the github-issues edge function; the read-only
 *           GitHub PAT lives server-side and never reaches the client.
 */
function ProjectIssuesSection() {
  const [state, setState] = useState({ status: 'loading', issues: [], project: null, error: null });

  useEffect(() => {
    let alive = true;
    (async () => {
      try {
        const { data: { session } } = await supabase.auth.getSession();
        const { data, error } = await supabase.functions.invoke('github-issues', {
          headers: session ? { Authorization: `Bearer ${session.access_token}` } : {},
        });
        if (!alive) return;
        if (error || data?.error) {
          setState({ status: 'error', issues: [], project: null, error: data?.error || error.message });
          return;
        }
        setState({ status: 'ready', issues: data.issues || [], project: data.project || null, error: null });
      } catch (e) {
        if (alive) setState({ status: 'error', issues: [], project: null, error: e?.message || 'Failed to load' });
      }
    })();
    return () => { alive = false; };
  }, []);

  const { status, issues, error } = state;

  return (
    <div style={{ marginBottom: 28 }}>
      <div className="health-section-label">Tracked Work</div>
      <div className="health-job-list">
        {status === 'loading' && (
          <div className="health-job-row" style={{ cursor: 'default' }}>
            <span className="health-dot health-dot--loading" style={{ flexShrink: 0 }} />
            <Loading className="health-job-name" style={{ fontWeight: 400, color: 'var(--dim)' }}>Loading open issues…</Loading>
          </div>
        )}
        {status === 'error' && (
          <div className="health-job-row" style={{ cursor: 'default' }}>
            <span className="health-dot health-dot--failed" style={{ flexShrink: 0 }} />
            <span className="health-job-name" role="alert" style={{ fontWeight: 400, color: 'var(--red)' }}>
              Couldn’t load issues: {error}
            </span>
          </div>
        )}
        {status === 'ready' && issues.length === 0 && (
          <div className="health-job-row" style={{ cursor: 'default' }}>
            <span className="health-dot health-dot--healthy" style={{ flexShrink: 0 }} />
            <span className="health-job-name" style={{ fontWeight: 400, color: 'var(--muted)' }}>
              No open issues. Backlog is clear.
            </span>
          </div>
        )}
        {status === 'ready' && issues.map(i => (
          <div key={i.number} className="health-job-row" {...activationProps(() => openPopup(i.url))}>
            <span style={{ fontSize: 12, color: 'var(--muted)', flexShrink: 0, width: 30 }}>
              #{i.number}
            </span>
            <span className="health-job-name">{i.title}</span>
            {i.labels && i.labels.length > 0 && (
              <span className="health-job-summary">{i.labels.join(' · ')}</span>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

function StatMini({ label, value, color }) {
  return (
    <div style={{ background: 'var(--surface2)', borderRadius: 8, padding: '10px 12px' }}>
      <div style={{ fontSize: 9, fontWeight: 600, textTransform: 'uppercase', letterSpacing: '2px', color: 'var(--muted)', marginBottom: 4 }}>
        {label}
      </div>
      <div style={{ fontSize: 20, fontWeight: 700, color: color || 'var(--white)' }}>
        {value ?? '—'}
      </div>
    </div>
  );
}

// Generic history table for dedup and backup
function HistoryTable({ check, runs }) {
  return (
    <div className="table-wrap" style={{ marginTop: 0 }}>
      <table style={{ width: '100%' }}>
        <thead>
          <tr>
            <th scope="col">Time</th>
            <th scope="col" style={{ whiteSpace: 'nowrap' }}>Trigger</th>
            {check.processedLabel && <th scope="col" style={{ whiteSpace: 'nowrap' }}>{check.processedLabel}</th>}
            <th scope="col" style={{ whiteSpace: 'nowrap' }}>Failed</th>
            <th scope="col" style={{ whiteSpace: 'nowrap' }}>Result</th>
          </tr>
        </thead>
        <tbody>
          {runs.map(run => {
            const d       = new Date(run.ran_at);
            const dateStr = fmtDate(d, 'MMM d, yyyy');
            const timeStr = d.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true });
            const s       = runStatus(run);
            return (
              <tr key={run.id}>
                <td style={{ fontSize: 12, whiteSpace: 'nowrap' }}>
                  {dateStr}
                  <span style={{ color: 'var(--muted)', marginLeft: 8 }}>{timeStr}</span>
                </td>
                <td style={{ fontSize: 12, color: 'var(--muted)', whiteSpace: 'nowrap' }}>{check.triggerLabel(run)}</td>
                {check.processedLabel && (
                  <td style={{ fontSize: 12, whiteSpace: 'nowrap' }}>
                    {run.processed > 0
                      ? run.processed
                      : <span style={{ color: 'var(--dim)' }}>{run.total === 0 ? '—' : '0'}</span>}
                  </td>
                )}
                <td style={{ fontSize: 12, color: run.failed > 0 ? 'var(--red)' : 'var(--dim)', whiteSpace: 'nowrap' }}>
                  {run.failed > 0 ? run.failed : '—'}
                </td>
                <td style={{ whiteSpace: 'nowrap' }}>
                  <span className={`badge ${badgeClass(s)}`}>{runStatusLabel(run)}</span>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

// Pipeline-specific history table: shows per-step counts instead of generic processed/failed
function PipelineHistoryTable({ runs }) {
  return (
    <div className="table-wrap" style={{ marginTop: 0 }}>
      <table style={{ width: '100%' }}>
        <thead>
          <tr>
            <th scope="col">Time</th>
            <th scope="col" style={{ whiteSpace: 'nowrap' }}>Trigger</th>
            <th scope="col" style={{ whiteSpace: 'nowrap' }}>Dedup</th>
            <th scope="col" style={{ whiteSpace: 'nowrap' }}>Cache</th>
            <th scope="col" style={{ whiteSpace: 'nowrap' }}>Stats</th>
            <th scope="col" style={{ whiteSpace: 'nowrap' }}>Result</th>
          </tr>
        </thead>
        <tbody>
          {runs.map(run => {
            const d        = new Date(run.ran_at);
            const dateStr  = fmtDate(d, 'MMM d, yyyy');
            const timeStr  = d.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true });
            const failed   = run.meta?.status === 'failed';
            const deleted  = run.meta?.steps?.dedup?.deleted;
            const cached   = run.meta?.steps?.cache?.cached;
            const synced   = run.meta?.steps?.stats?.synced;
            const dedupErr = run.meta?.steps?.dedup?.error;
            const cacheErr = run.meta?.steps?.cache?.error;
            const statsErr = run.meta?.steps?.stats?.error;
            return (
              <tr key={run.id}>
                <td style={{ fontSize: 12, whiteSpace: 'nowrap' }}>
                  {dateStr}
                  <span style={{ color: 'var(--muted)', marginLeft: 8 }}>{timeStr}</span>
                </td>
                <td style={{ fontSize: 12, color: 'var(--muted)', whiteSpace: 'nowrap' }}>{pipelineTriggerLabel(run.meta)}</td>
                <td style={{ fontSize: 12, whiteSpace: 'nowrap' }}>
                  {dedupErr
                    ? <span style={{ color: 'var(--red)' }}>Error</span>
                    : deleted > 0
                    ? deleted
                    : <span style={{ color: 'var(--dim)' }}>—</span>}
                </td>
                <td style={{ fontSize: 12, whiteSpace: 'nowrap' }}>
                  {cacheErr
                    ? <span style={{ color: 'var(--red)' }}>Error</span>
                    : cached > 0
                    ? cached
                    : <span style={{ color: 'var(--dim)' }}>—</span>}
                </td>
                <td style={{ fontSize: 12, whiteSpace: 'nowrap' }}>
                  {statsErr
                    ? <span style={{ color: 'var(--red)' }}>Error</span>
                    : synced > 0
                    ? synced
                    : <span style={{ color: 'var(--dim)' }}>—</span>}
                </td>
                <td style={{ whiteSpace: 'nowrap' }}>
                  <span className={`badge ${failed ? 'badge-red-soft' : 'badge-orange'}`}>
                    {failed ? 'Failed' : 'OK'}
                  </span>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
