/**
 * components/admin/WorkflowSetupView.js: admin Config editor for status_options
 * (the campaign / payment / deliverable / payout / split status vocabularies).
 *
 * Edits value, display label, badge color, and sort order per group; rows in use
 * (per get_status_usage_counts) are locked from rename/delete. Substantial view.
 *
 * @gotcha BADGE_PALETTE is keyed by its bg color string; paletteFor() reverse-maps
 *         a stored bg back to a swatch, so changing a palette bg orphans old rows.
 * @see contexts/StatusOptionsContext.js (the consumer of these options)
 */
import React, { useState, useEffect, useCallback, useId, useRef } from 'react';
import { supabase } from '../../lib/supabase';
import { useStatusOptions } from '../../contexts/StatusOptionsContext';
import HelpIcon from '../shared/HelpIcon';
import LockIcon from '../shared/LockIcon';
import { DragHandleIcon, ArrowUpIcon, ArrowDownIcon } from '../shared/Icon';
import { useConfirm } from '../shared/ConfirmDialog';
import { mutate } from '../../utils/mutate';
import { useToast } from '../shared/Toast';
import ReadError from '../shared/ReadError';

const BADGE_PALETTE = [
  { id: 'muted',   bg: '#161616',               text: '#a8a8a8', label: 'Muted'   },
  { id: 'blue',    bg: 'rgba(74,158,255,0.12)',  text: '#4a9eff', label: 'Blue'    },
  { id: 'orange',  bg: 'rgba(255,92,0,0.10)',    text: '#ff5c00', label: 'Orange'  },
  { id: 'amber',   bg: 'rgba(255,140,66,0.12)',  text: '#ff8c42', label: 'Amber'   },
  { id: 'green',   bg: 'rgba(61,220,132,0.12)',  text: '#3ddc84', label: 'Green'   },
  { id: 'red',     bg: 'rgba(255,68,68,0.12)',   text: '#ff4444', label: 'Red'     },
  { id: 'purple',  bg: 'rgba(169,112,248,0.12)', text: '#a970f8', label: 'Purple'  },
  { id: 'sky',     bg: 'rgba(99,179,237,0.12)',  text: '#63b3ed', label: 'Sky'     },
];

const GROUP_META = [
  { key: 'campaign',    title: 'Campaign Status',    desc: 'Negotiation → completion workflow' },
  { key: 'payment',     title: 'Payment Status',     desc: 'Invoice status, agency to Patrick' },
  { key: 'deliverable', title: 'Deliverable Status', desc: 'Content draft workflow' },
  { key: 'payout',      title: 'Payout Status',      desc: 'Patrick → creator payout tracking' },
  { key: 'split',       title: 'Split Status',       desc: 'Individual split payment tracking' },
];

function paletteFor(bgColor) {
  return BADGE_PALETTE.find(p => p.bg === bgColor) || null;
}

const MOVE_BTN = { padding: '3px 6px', fontSize: 11, lineHeight: 1 }; // level with Edit beside it

// ── Color swatches ────────────────────────────────────────────────────────────

/**
 * The eight badge colours, as a radiogroup.
 *
 * Native `<input type="radio">` rather than a `<div role="radio">`, so the browser owns the
 * roving tabindex, the arrow keys and the checked state, and a taken colour is skipped by
 * both. Each input is transparent and `appearance: none` over the `<label>` that draws the
 * swatch, so the control announces itself without changing what is on screen.
 *
 * @gotcha the group `name` is a `useId`. Six of these mount at once, one per group card plus
 *         the row being edited, and a shared name would fuse all forty eight into one group.
 * @gotcha the tick is decoration and stays hidden. Selection is stated by the radio, never by
 *         a glyph, which is what a name alone on a roleless div could not do.
 * @see components/shared/Tabs.js for the same idea written by hand
 */
export function ColorSwatches({ selectedId, onChange, takenIds = [] }) {
  const groupName = useId();
  return (
    <div role="radiogroup" aria-label="Badge color" style={{ display: 'flex', gap: 4, flexShrink: 0 }}>
      {BADGE_PALETTE.map(p => {
        const isTaken    = takenIds.includes(p.id);
        const isSelected = selectedId === p.id;
        return (
          <label
            key={p.id}
            title={isTaken ? `${p.label} (already used)` : p.label}
            style={{
              position: 'relative',
              width: 22, height: 22, borderRadius: 4,
              background: p.bg, border: `1px solid ${isSelected ? p.text : 'transparent'}`,
              cursor: isTaken ? 'not-allowed' : 'pointer',
              opacity: isTaken ? 0.3 : 1,
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              transition: 'border 0.1s',
            }}
          >
            <input
              type="radio"
              name={groupName}
              value={p.id}
              checked={isSelected}
              disabled={isTaken}
              onChange={() => onChange(p.id)}
              aria-label={isTaken ? `${p.label}, already used` : p.label}
              style={{
                position: 'absolute', top: 0, left: 0, width: '100%', height: '100%',
                margin: 0, appearance: 'none', WebkitAppearance: 'none',
                background: 'transparent', border: 0, borderRadius: 4, cursor: 'inherit',
              }}
            />
            {isSelected && <span aria-hidden="true" style={{ color: p.text, fontSize: 12, lineHeight: 1 }}>✓</span>}
          </label>
        );
      })}
    </div>
  );
}

// ── Single status row ─────────────────────────────────────────────────────────

/**
 * One editable status row: rename, recolor, reorder (drag or the move buttons), delete. When
 * inUse, the value and delete are locked (a status referenced by live rows cannot change).
 *
 * @gotcha the move buttons put the focus back themselves. React MOVES the row's DOM node and
 *         the browser blurs a moved (or newly disabled) control, so without this a second
 *         press lands on whichever row slid under the reader.
 */
function StatusRow({ row, inUse, takenIds, canMoveUp, canMoveDown, onMove, isDragging, isDragOver, onDragStart, onDragOver, onDrop, onDragEnd, onRefresh }) {
  const toast = useToast();
  const askConfirm = useConfirm();
  const [editing,   setEditing]   = useState(false);
  const [editValue, setEditValue] = useState(row.value);
  const [editLabel, setEditLabel] = useState(row.label);
  const [editColor, setEditColor] = useState(() => paletteFor(row.bg_color)?.id || 'muted');
  const [saving,    setSaving]    = useState(false);

  const palette = BADGE_PALETTE.find(p => p.id === editColor) || { bg: row.bg_color, text: row.text_color };

  // Both controls below are disabled once the status is in use, and a `title` on a disabled
  // element reaches neither keyboard nor touch. Named once, used as tooltip and as name.
  const valueReason  = inUse > 0 ? `In use by ${inUse} records, value cannot be changed` : 'Canonical identifier';
  const deleteReason = inUse > 0 ? `Cannot delete: in use by ${inUse} records` : `Delete "${row.value}"`;
  const upName   = canMoveUp   ? `Move "${row.label}" up`   : `Move "${row.label}" up, already first`;
  const downName = canMoveDown ? `Move "${row.label}" down` : `Move "${row.label}" down, already last`;

  const moves = useRef({}); // the up and down button nodes, plus which one was just pressed
  useEffect(() => {
    const dir = moves.current.pressed;
    if (!dir) return;
    moves.current.pressed = null;
    const pressed = moves.current[dir];
    // At an end of the list that button is disabled now, so focus falls to its neighbour.
    const el = pressed && !pressed.disabled ? pressed : moves.current[dir === 'up' ? 'down' : 'up'];
    if (el && !el.disabled) el.focus();
  });

  const handleSave = async () => {
    const v = editValue.trim();
    const l = editLabel.trim();
    if (!v || !l) return;
    setSaving(true);
    await supabase.from('status_options').update({
      label: l, value: v, bg_color: palette.bg, text_color: palette.text,
    }).eq('id', row.id);
    setSaving(false);
    setEditing(false);
    onRefresh();
  };

  const handleCancel = () => {
    setEditing(false);
    setEditValue(row.value);
    setEditLabel(row.label);
    setEditColor(paletteFor(row.bg_color)?.id || 'muted');
  };

  const handleDelete = async () => {
    if (inUse > 0) return;
    if (!(await askConfirm({ title: `Delete "${row.value}"?`, body: 'This cannot be undone.', danger: true }))) return;
    const { error } = await mutate(supabase.from('status_options').delete().eq('id', row.id));
    if (error) { toast.error(error); return; }
    onRefresh();
  };

  const rowBg = isDragOver ? 'rgba(255,92,0,0.07)'
    : isDragging ? 'rgba(255,255,255,0.02)'
    : 'transparent';

  return (
    <div
      draggable
      onDragStart={e => onDragStart(e, row.id)}
      onDragOver={e => onDragOver(e, row.id)}
      onDrop={e => onDrop(e, row.id)}
      onDragEnd={onDragEnd}
      style={{
        display: 'flex', alignItems: 'center', gap: 10,
        padding: '8px 10px', borderRadius: 6,
        background: rowBg,
        opacity: isDragging ? 0.45 : 1,
        transition: 'background 0.1s, opacity 0.1s',
        minHeight: 38,
      }}
    >
      <DragHandleIcon size={13} style={{ color: 'var(--dim)', cursor: 'grab', flexShrink: 0 }} />

      <div style={{ width: 90, flexShrink: 0 }}>
        <span className="badge" style={{
          background: editing ? palette.bg : row.bg_color,
          color: editing ? palette.text : row.text_color,
          width: '100%', justifyContent: 'center',
        }}>
          {editing ? (editLabel || row.label) : row.label}
        </span>
      </div>

      {editing ? (
        <div style={{ flex: 1, display: 'flex', alignItems: 'center', gap: 10, flexWrap: 'wrap' }}>
          <ColorSwatches selectedId={editColor} onChange={setEditColor} takenIds={takenIds} />

          <input
            className="form-input"
            value={editValue}
            onChange={e => setEditValue(e.target.value)}
            disabled={inUse > 0}
            aria-label={valueReason}
            title={valueReason}
            placeholder="Value"
            maxLength={100}
            style={{ width: 150, padding: '4px 8px', fontSize: 12, opacity: inUse > 0 ? 0.5 : 1 }}
          />
          <input
            className="form-input"
            value={editLabel}
            onChange={e => setEditLabel(e.target.value)}
            onKeyDown={e => e.key === 'Enter' && handleSave()}
            aria-label="Display label"
            placeholder="Display label"
            maxLength={100}
            style={{ width: 150, padding: '4px 8px', fontSize: 12 }}
          />
          {inUse > 0 && <span style={{ fontSize: 11, color: 'var(--dim)', flexShrink: 0, display: 'inline-flex', alignItems: 'center', gap: 4 }}><LockIcon size={11} /> {inUse} active</span>}

          <div style={{ marginLeft: 'auto', display: 'flex', gap: 6, flexShrink: 0 }}>
            <button className="btn btn-primary btn-sm" onClick={handleSave} disabled={saving} style={{ padding: '3px 10px' }}>
              {saving ? '…' : 'Save'}
            </button>
            <button className="btn btn-ghost btn-sm" onClick={handleCancel} style={{ padding: '3px 8px' }}>Cancel</button>
          </div>
        </div>
      ) : (
        <>
          <code title={row.value} style={{ fontSize: 11, color: 'var(--muted)', width: 160, flexShrink: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{row.value}</code>
          <span style={{ fontSize: 13, color: 'var(--white)', flex: 1 }}>{row.label}</span>
          <span style={{ fontSize: 11, color: 'var(--muted)', flexShrink: 0, width: 58, textAlign: 'right' }}>
            {inUse > 0 ? `${inUse} active` : ''}
          </span>

          <div style={{ display: 'flex', gap: 6, flexShrink: 0, minWidth: 134 }}>
            <button ref={el => { moves.current.up = el; }} className="btn btn-ghost btn-sm" style={MOVE_BTN}
              onClick={() => { moves.current.pressed = 'up'; onMove(-1); }} disabled={!canMoveUp} aria-label={upName} title={upName}><ArrowUpIcon size={11} /></button>
            <button ref={el => { moves.current.down = el; }} className="btn btn-ghost btn-sm" style={MOVE_BTN}
              onClick={() => { moves.current.pressed = 'down'; onMove(1); }} disabled={!canMoveDown} aria-label={downName} title={downName}><ArrowDownIcon size={11} /></button>
            <button className="btn btn-ghost btn-sm" onClick={() => setEditing(true)} style={{ padding: '3px 8px', fontSize: 11 }}>
              Edit
            </button>
            <button
              onClick={handleDelete}
              disabled={inUse > 0}
              aria-label={deleteReason}
              title={deleteReason}
              style={{
                background: 'none', border: 'none', cursor: inUse > 0 ? 'not-allowed' : 'pointer',
                color: inUse > 0 ? 'var(--dim)' : 'var(--red)', fontSize: 13, padding: '3px 6px',
                fontFamily: 'inherit',
              }}
            >
              {inUse > 0 ? <LockIcon size={12} /> : '✕'}
            </button>
          </div>
        </>
      )}
    </div>
  );
}

// ── Add row ───────────────────────────────────────────────────────────────────

function AddStatusRow({ groupKey, sortOrder, takenIds, onRefresh }) {
  const [value,    setValue]    = useState('');
  const [label,    setLabel]    = useState('');
  const [colorId,  setColorId]  = useState('muted');
  const [adding,   setAdding]   = useState(false);

  const palette = BADGE_PALETTE.find(p => p.id === colorId) || BADGE_PALETTE[0];

  const handleAdd = async () => {
    const v = value.trim();
    const l = label.trim();
    if (!v || !l) return;
    setAdding(true);
    await supabase.from('status_options').insert({
      group_key: groupKey, value: v, label: l,
      bg_color: palette.bg, text_color: palette.text, sort_order: sortOrder,
    });
    setValue(''); setLabel(''); setColorId('muted');
    setAdding(false);
    onRefresh();
  };

  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '10px 10px', marginTop: 6, borderTop: '1px solid var(--border)' }}>
      <span style={{ width: 20, flexShrink: 0 }} />

      <div style={{ width: 90, flexShrink: 0, opacity: value ? 1 : 0.35 }}>
        <span className="badge" style={{ background: palette.bg, color: palette.text, width: '100%', justifyContent: 'center' }}>
          {label || value || 'Preview'}
        </span>
      </div>

      <ColorSwatches selectedId={colorId} onChange={setColorId} takenIds={takenIds} />

      <input
        className="form-input"
        aria-label="Value for the new option"
        placeholder="Value"
        value={value}
        onChange={e => setValue(e.target.value)}
        onKeyDown={e => e.key === 'Enter' && handleAdd()}
        maxLength={100}
        style={{ width: 150, padding: '4px 8px', fontSize: 12 }}
      />
      <input
        className="form-input"
        aria-label="Display label for the new option"
        placeholder="Display label"
        value={label}
        onChange={e => setLabel(e.target.value)}
        onKeyDown={e => e.key === 'Enter' && handleAdd()}
        maxLength={100}
        style={{ width: 150, padding: '4px 8px', fontSize: 12 }}
      />

      <button
        className="btn btn-primary btn-sm"
        onClick={handleAdd}
        disabled={adding || !value.trim() || !label.trim()}
        style={{ marginLeft: 'auto', flexShrink: 0 }}
      >
        {adding ? '…' : '+ Add'}
      </button>
    </div>
  );
}

// ── Group card ────────────────────────────────────────────────────────────────

function StatusGroupCard({ groupKey, title, desc, rows, counts, onRefresh }) {
  const toast = useToast();
  const [localRows,  setLocalRows]  = useState(rows);
  const [dragId,     setDragId]     = useState(null);
  const [dragOverId, setDragOverId] = useState(null);

  useEffect(() => { setLocalRows(rows); }, [rows]);

  const allUsedPaletteIds = rows.map(r => paletteFor(r.bg_color)?.id).filter(Boolean);

  const handleDragStart = (e, id) => {
    setDragId(id);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragOver = (e, id) => {
    e.preventDefault();
    if (id !== dragId) setDragOverId(id);
  };

  /** The one renumbering rule: a drop and a move button both land here, so `sort_order` is
   *  rewritten from each row's new INDEX in one place and a failed write is reported once. */
  const reorder = useCallback(async (fromIdx, toIdx) => {
    const next = [...localRows];
    next.splice(toIdx, 0, ...next.splice(fromIdx, 1));
    const updated = next.map((r, i) => ({ ...r, sort_order: i }));
    setLocalRows(updated);
    const results = await Promise.all(updated.map(r =>
      mutate(supabase.from('status_options').update({ sort_order: r.sort_order }).eq('id', r.id))
    ));
    const failed = results.find(r => r.error);
    if (failed) toast.error(failed.error);
    onRefresh();
  }, [localRows, onRefresh, toast]);

  const handleDrop = useCallback(async (e, targetId) => {
    e.preventDefault();
    if (!dragId || dragId === targetId) return;
    const fromIdx = localRows.findIndex(r => r.id === dragId);
    const toIdx   = localRows.findIndex(r => r.id === targetId);
    setDragId(null);
    setDragOverId(null);
    await reorder(fromIdx, toIdx);
  }, [dragId, localRows, reorder]);

  const handleDragEnd = () => { setDragId(null); setDragOverId(null); };

  return (
    <div className="card">
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 14 }}>
        <div>
          <h2 className="card-title">{title}</h2>
          <div style={{ fontSize: 12, color: 'var(--muted)', marginTop: 2 }}>{desc}</div>
        </div>
        <span style={{ fontSize: 11, color: 'var(--dim)' }}>{rows.length} statuses</span>
      </div>

      <div style={{ display: 'flex', flexDirection: 'column' }}>
        {localRows.map((row, i) => {
          const ownPaletteId = paletteFor(row.bg_color)?.id;
          const takenIds = allUsedPaletteIds.filter(id => id !== ownPaletteId);
          return (
            <StatusRow
              key={row.id}
              row={row}
              inUse={counts[`${groupKey}:${row.value}`] || 0}
              takenIds={takenIds}
              canMoveUp={i > 0}
              canMoveDown={i < localRows.length - 1}
              onMove={delta => reorder(i, i + delta)}
              isDragging={dragId === row.id}
              isDragOver={dragOverId === row.id}
              onDragStart={handleDragStart}
              onDragOver={handleDragOver}
              onDrop={handleDrop}
              onDragEnd={handleDragEnd}
              onRefresh={onRefresh}
            />
          );
        })}
      </div>

      <AddStatusRow
        groupKey={groupKey}
        sortOrder={rows.length}
        takenIds={allUsedPaletteIds}
        onRefresh={onRefresh}
      />
    </div>
  );
}

// ── Main view ─────────────────────────────────────────────────────────────────

export default function WorkflowSetupView() {
  const { options, refresh } = useStatusOptions();
  const [counts, setCounts] = useState({});
  // The third state. These counts decide whether Delete is offered: a status in use must not
  // be deletable. Returning early on a refused read kept the PREVIOUS counts, which on the
  // first load are none at all, so every row read as unused and armed its own Delete.
  const [countsError, setCountsError] = useState(null);

  const loadCounts = useCallback(async () => {
    setCountsError(null);
    const { data, error } = await supabase.rpc('get_status_usage_counts');
    if (error) { setCountsError(error); return; }
    const map = {};
    (data || []).forEach(r => { map[`${r.group_key}:${r.value}`] = Number(r.count); });
    setCounts(map);
  }, []);

  useEffect(() => { loadCounts(); }, [loadCounts]);

  const handleRefresh = useCallback(() => {
    refresh();
    loadCounts();
  }, [refresh, loadCounts]);

  return (
    <div style={{ padding: '36px 40px' }}>
      <div style={{ marginBottom: 32 }}>
        <h1 style={{ fontFamily: 'var(--font-display)', fontSize: 28, fontWeight: 400, letterSpacing: 2, color: 'var(--white)', margin: 0 }}>
          WORKFLOW SETUP<HelpIcon slug="workflow-setup" />
        </h1>
        <div style={{ fontSize: 12, color: 'var(--muted)', marginTop: 6 }}>
          Status options, display labels, and badge colors used across campaigns, payments, and deliverables.
          Reorder by dragging a row or with its move buttons. Values in use cannot be renamed or deleted. Expense categories are managed in Financials → Chart of Accounts.
        </div>
      </div>

      {countsError ? <ReadError error={countsError} onRetry={loadCounts} /> : (
      <div style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>
        {GROUP_META.map(g => (
          <StatusGroupCard
            key={g.key}
            groupKey={g.key}
            title={g.title}
            desc={g.desc}
            rows={options[g.key] || []}
            counts={counts}
            onRefresh={handleRefresh}
          />
        ))}
      </div>
      )}
    </div>
  );
}
