/**
 * components/admin/ExpensesView.js: thin admin wrapper around components/shared/ExpensesPage.
 *
 * Passes isAdmin=true, profileId=null, and the deep-link target (pendingExpenseId)
 * a ledger line uses to open an expense. All logic lives in ExpensesPage.
 * Pass-through by design.
 */
import React from 'react';
import ExpensesPage from '../shared/ExpensesPage';

export default function ExpensesView({ pendingExpenseId, onConsumed }) {
  return <ExpensesPage isAdmin={true} profileId={null} pendingExpenseId={pendingExpenseId} onConsumed={onConsumed} />;
}
