/**
 * components/shared/PayrollTaxRemittance.js: the month's last beat, where the tax leaves the
 * books too.
 *
 * Gusto pulls TWO debits for a run regardless of headcount: one for both creators' net pay,
 * one for both creators' tax. `PayrollPaycheck` handles the pay side, and every paycheck it
 * records credits 2200 with the tax it kept back. Nothing debits 2200, so without this band the
 * books hold cash the IRS already has, every month, forever.
 *
 * It belongs to the MONTH rather than to a creator, because the bank line does: two per-creator
 * entries would produce two cash amounts that no single statement line matches, and Reconcile
 * Bank ties a bank line to a cash line by exact amount.
 *
 * @invariant the amount is never typed and never sent. `record_payroll_tax_remittance` derives
 *            it from the period's paychecks, which is the same figure the admin already entered
 *            when he settled each creator and which the database seals once that paycheck's
 *            entry posts. This screen confirms; it does not collect.
 * @invariant a failed read renders the error, never the un-recorded state. "Not recorded yet"
 *            and "I could not find out" look identical and only one is safe to act on.
 * @gotcha `reverse_journal_entry` COPIES the original's reference onto the reversal, so a
 *         reversed month holds TWO entries carrying this month's reference. Both are dropped:
 *         the original by `reversed_by_je_id`, the reversal by `isReversalEntry`.
 * @see utils/payroll.js buildTaxRemittance; docs/MONEY.md 10.0b and 10.0c
 */
import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { supabase } from '../../lib/supabase';
import { fmtDate, fmtMoney, fmtMonth, todayYMD } from '../../utils/format';
import { humanizeError } from '../../utils/errors';
import { isReversalEntry } from '../../utils/journalEntry';
import { DB_DATE_MIN } from '../../utils/dbLimits';
import { buildTaxRemittance, payrollDateWindow } from '../../utils/payroll';
import Field from './Field';
import Feedback from './Feedback';
import ReadError from './ReadError';
import Skeleton from './Skeleton';
import SubmitButton from './SubmitButton';
import { useToast } from './Toast';

const log = (...args) => {
  if (process.env.NODE_ENV !== 'production') console.error('[PayrollTaxRemittance]', ...args);
};

/** The reference `record_payroll_tax_remittance` stamps on the entry it posts. One per month. */
const referenceFor = (month) => `PR-TAX-${month}`;

const creatorName = (profile) => profile.full_name || profile.creator_name || 'Unnamed';

/** "Kym", "Kym and Mys", "Kym, Mys and Ada". Reads as a sentence, because it is inside one. */
function nameList(rows) {
  const names = rows.map((r) => creatorName(r.profile));
  if (names.length <= 1) return names[0] || '';
  return `${names.slice(0, -1).join(', ')} and ${names[names.length - 1]}`;
}

export default function PayrollTaxRemittance({ month, rows, onSaved }) {
  const toast = useToast();
  const today = todayYMD();

  const dateWindow = payrollDateWindow(month);

  const [load, setLoad] = useState({ loading: true, error: null, data: null });
  const [date, setDate] = useState('');
  const [saving, setSaving] = useState(false);
  const [saveError, setSaveError] = useState(null);

  const fetchAll = useCallback(async () => {
    setLoad((s) => ({ ...s, loading: true, error: null }));
    const [entryRes, acctRes] = await Promise.all([
      supabase
        .from('ledger_journal_entries')
        .select('id, entry_date, description, source_type, reversed_by_je_id')
        .eq('reference', referenceFor(month))
        .eq('is_posted', true),
      supabase.from('ledger_accounts').select('id').eq('code', '2200').maybeSingle(),
    ]);
    if (entryRes.error || acctRes.error) {
      log('load', entryRes.error || acctRes.error);
      setLoad({ loading: false, error: entryRes.error || acctRes.error, data: null });
      return;
    }
    const live = (entryRes.data || []).find((e) => e.reversed_by_je_id == null && !isReversalEntry(e));
    setLoad({ loading: false, error: null, data: { entry: live || null, accountId: acctRes.data?.id || null } });
  }, [month]);

  useEffect(() => { fetchAll(); }, [fetchAll]);

  const view = useMemo(
    () => buildTaxRemittance({ rows, entry: load.data?.entry || null }),
    [rows, load.data]
  );

  // The run's own date, not today: this is recorded in the same sitting as payroll, so the day
  // the tax leaves is the day the run pays out, and that day is normally still ahead. The
  // paychecks are bound to the same window as the field below, so the floor is always a legal
  // value for it. @see utils/payroll.js payrollDateWindow
  useEffect(() => {
    if (view.floorDate && !date) setDate(view.floorDate);
  }, [view.floorDate, date]);

  async function record() {
    // @invariant the tax cannot have left before the run that withheld it. `min` on the field
    //            is advisory and a typed or pasted date walks straight past it, so this compare
    //            is the guard that holds. ISO YYYY-MM-DD sorts lexically. The function refuses
    //            it too; this is the half that answers without a round trip.
    if (view.floorDate && date < view.floorDate) {
      setSaveError({
        tone: 'error',
        title: 'That date is before the run',
        body: `This run paid out on ${fmtDate(view.floorDate)}. Gusto cannot have taken the tax before that.`,
      });
      return;
    }
    setSaving(true);
    setSaveError(null);
    const { error } = await supabase.rpc('record_payroll_tax_remittance', {
      p_period: `${month}-01`,
      p_entry_date: date,
    });
    if (error) { log('record', error); setSaveError(humanizeError(error)); setSaving(false); return; }
    toast.success('Tax recorded');
    // Refetched BEFORE the flag comes back, or the button is live again for the moment the read
    // takes and a second click posts a second entry against the same month.
    await fetchAll();
    setSaving(false);
    if (onSaved) onSaved();
  }

  const openLedger = useCallback(() => {
    window.dispatchEvent(new window.CustomEvent('nys:open-ledger', {
      detail: { tab: 'gl', accountId: load.data?.accountId || undefined },
    }));
  }, [load.data]);

  if (load.loading) {
    return (
      <section className="payroll-tax">
        <h4 className="payroll-tax-head">Tax Gusto sends to the IRS</h4>
        <Skeleton label="Loading the month's tax" bars={1} />
      </section>
    );
  }
  if (load.error) {
    return (
      <section className="payroll-tax">
        <h4 className="payroll-tax-head">Tax Gusto sends to the IRS</h4>
        <ReadError error={load.error} onRetry={fetchAll} />
      </section>
    );
  }

  return (
    <section className="payroll-tax" data-done={view.state === 'recorded' || view.state === 'none' ? 'true' : 'false'}>
      <h4 className="payroll-tax-head">Tax Gusto sends to the IRS</h4>

      {view.state === 'waiting' && (
        <p className="payroll-tax-body">
          Gusto pulls one tax debit for the whole run, so the figure is not final until
          {' '}{nameList(view.waitingOn)}
          {view.waitingOn.length === 1 ? ' has ' : ' have '}
          been settled above.
        </p>
      )}

      {view.state === 'none' && (
        <p className="payroll-tax-body">
          Nothing was withheld this month, so Gusto pulls no tax debit and there is nothing to
          record. {fmtMonth(month)} is finished.
        </p>
      )}

      {view.state === 'ready' && (
        <>
          <p className="payroll-tax-body">
            Gusto takes this out of the account in its own debit, apart from the pay. Until it is
            recorded the books still count it as money the company has.
          </p>

          <div className="payroll-tax-total">
            <span>Withheld across the run</span>
            <span className="payroll-plain">{fmtMoney(view.total)}</span>
          </div>

          {view.perCreator.length > 1 && (
            <ul className="payroll-tax-list">
              {view.perCreator.map(({ profile, amount }) => (
                <li key={profile.id} data-zero={amount === 0 ? 'true' : 'false'}>
                  <span className="payroll-tax-name">{creatorName(profile)}</span>
                  <span className="payroll-tax-amount">{fmtMoney(amount)}</span>
                </li>
              ))}
            </ul>
          )}

          <div className="payroll-return-fields" style={{ marginTop: 16 }}>
            <Field label="Gusto takes it on">
              {(id) => (
                <input
                  id={id} className="form-input" type="date"
                  min={view.floorDate || dateWindow?.min || DB_DATE_MIN} max={dateWindow?.max}
                  value={date}
                  onChange={(e) => setDate(e.target.value)}
                />
              )}
            </Field>
          </div>

          {saveError && <Feedback value={saveError} style={{ marginTop: 14 }} />}

          <div className="payroll-return-actions">
            <SubmitButton
              saving={saving} className="btn btn-primary btn-sm"
              onClick={record} disabled={saving || !date}
            >
              Record the tax
            </SubmitButton>
          </div>
        </>
      )}

      {view.state === 'recorded' && (
        <>
          <div className="payroll-tax-total">
            <span>
              {load.data.entry.entry_date > today
                ? `Recorded. Gusto takes it ${fmtDate(load.data.entry.entry_date)}.`
                : `Recorded ${fmtDate(load.data.entry.entry_date)}`}
            </span>
            <span className="payroll-plain">{fmtMoney(view.total)}</span>
          </div>
          {view.waitingOn.length > 0 && (
            <p className="payroll-tax-body">
              {nameList(view.waitingOn)}
              {view.waitingOn.length === 1 ? ' is ' : ' are '}
              still unsettled for this month. A paycheck now would withhold tax this entry has
              already sent, so reverse it first and record the month again.
            </p>
          )}
          <div className="payroll-return-actions">
            <button type="button" className="payroll-quiet" onClick={openLedger}>
              See the ledger entry
            </button>
          </div>
        </>
      )}
    </section>
  );
}
